import{_ as n,o as s,c as a,f as t,a as p}from"./app-v4ODCOL5.js";const o={},e=p(`<h2 id="第-24-章-算法与数据结构-前端高频" tabindex="-1"><a class="header-anchor" href="#第-24-章-算法与数据结构-前端高频" aria-hidden="true">#</a> 第 24 章 算法与数据结构（前端高频）</h2><h3 id="q1-面试里让你分析一段代码的时间复杂度-你一般怎么下手" tabindex="-1"><a class="header-anchor" href="#q1-面试里让你分析一段代码的时间复杂度-你一般怎么下手" aria-hidden="true">#</a> Q1 面试里让你分析一段代码的时间复杂度，你一般怎么下手？</h3><p><strong>考察点</strong>：考是否真懂复杂度（Big O）的定义与推导方法，而不是背&quot;双层循环就是 O(n²)&quot;。能说清&quot;抓最高阶、去常数&quot;并现场推导就过关。</p><p><strong>参考答案</strong>：</p><blockquote><p><strong>一句话结论</strong>：复杂度描述的是数据规模 n 增长时运算量的<strong>增长趋势</strong>，不是具体耗时；推导就看最深层代码执行了多少次，取最高阶、扔掉常数与低阶项。</p></blockquote><ol><li>只看增长趋势，不看常数：<code>O(2n)</code> 与 <code>O(n)</code> 是同一量级；<code>n=10</code> 时 O(n²) 可能比 O(n log n) 快，但 n 一大必然反超——面试问的是规模变大后谁先崩。</li><li>推导三步：找出执行次数最多的那行 → 写出它关于 n 的表达式 → 只保留最高阶。<code>for</code> 里 <code>i *= 2</code> 是 O(log n)，因为循环次数是 log₂n 级别。</li><li>看循环结构而不是看行数：并列两个循环是相加取最大，嵌套是相乘。递归要写递推式，再靠主定理或画递归树得出，例如归并排序 <code>T(n) = 2T(n/2) + O(n)</code> 得 O(n log n)。</li><li>常见量级排序：O(1) &lt; O(log n) &lt; O(n) &lt; O(n log n) &lt; O(n²) &lt; O(2ⁿ) &lt; O(n!)。面试里把 O(n log n) 说成&quot;比 O(n²) 好一个 log 因子&quot;就够了。</li><li><strong>复杂度与边界</strong>：空间复杂度只算<strong>额外</strong>开销，输入本身不计入；最容易让推导失效的三种边界是 n=0 的空输入、n=1 的单元素、全部元素相同。</li></ol><p><strong>追问与易错点</strong>：</p><ul><li>追问：<code>Array.prototype.includes</code> 的复杂度是多少？答：O(n) 线性查找；<code>Set.has</code> / <code>Map.get</code> 是 O(1) 平均，这正是&quot;用 Map 换时间&quot;的理论依据。</li><li>追问：<code>arr.push</code> 和 <code>arr.unshift</code> 呢？答：<code>push</code> 均摊 O(1)（偶发扩容），<code>unshift</code>/<code>shift</code> 要把所有元素整体搬移，是 O(n)，循环里用 <code>shift</code> 是最常见的性能坑。</li><li>陷阱：说&quot;复杂度就是代码跑多久&quot;，或者把 <code>O(2n)</code> 说成比 <code>O(n)</code> 慢一倍还当结论，都会被当场纠正。</li></ul><h3 id="q2-时间复杂度和空间复杂度怎么权衡-什么是均摊复杂度" tabindex="-1"><a class="header-anchor" href="#q2-时间复杂度和空间复杂度怎么权衡-什么是均摊复杂度" aria-hidden="true">#</a> Q2 时间复杂度和空间复杂度怎么权衡？什么是均摊复杂度？</h3><p><strong>考察点</strong>：考&quot;用空间换时间&quot;的取舍判断，以及均摊（Amortized）分析这个高频概念，<code>push</code> 与哈希表扩容是最好的例子。</p><p><strong>参考答案</strong>：</p><blockquote><p><strong>一句话结论</strong>：时间与空间通常此消彼长，算法题里默认优先换时间（哈希表、前缀和、备忘录），只有在内存受限（移动端、大文件、流式场景）时才反向优化；均摊复杂度指的是&quot;偶尔一次很贵，平摊到每次操作很便宜&quot;。</p></blockquote><ol><li>空间复杂度只算<strong>额外</strong>开销，不算输入本身：原地（In-place）算法额外空间 O(1)，转存一份数组就是 O(n)。</li><li>换时间的典型手段：哈希表把查找从 O(n) 降到 O(1)；前缀和把区间求和从 O(n) 降到 O(1)；记忆化把递归从 O(2ⁿ) 降到 O(n)。</li><li>保空间的典型场景：前端处理大数组/大文件时不能整份转存，要流式或分块处理，用 O(1) 双指针代替 O(n) 的辅助数组。</li><li>均摊复杂度（Amortized Complexity）：<code>push</code> 平时 O(1)，数组容量满时扩容要整体复制一次 O(n)，但扩容是倍数增长（V8 约为 1.5 倍），连续 n 次 push 总代价 O(n)，摊到每次仍是 O(1)。</li><li>均摊 ≠ 平均：平均复杂度是对输入分布求期望，均摊是对<strong>一串操作序列</strong>求平均，不依赖概率假设，是最坏情况下的总量摊派。</li><li><strong>复杂度与边界</strong>：均摊分析的前提是&quot;扩容按倍数增长&quot;；若每次只扩容固定长度（如 +1），<code>push</code> 会退化成 O(n)。</li></ol><div class="language-javascript line-numbers-mode" data-ext="js"><pre class="language-javascript"><code><span class="token comment">// 均摊的直观来源：倍数扩容，总复制次数 1+2+4+...+n &lt; 2n</span>
<span class="token keyword">let</span> cap <span class="token operator">=</span> <span class="token number">1</span><span class="token punctuation">,</span> copies <span class="token operator">=</span> <span class="token number">0</span><span class="token punctuation">;</span>
<span class="token keyword">for</span> <span class="token punctuation">(</span><span class="token keyword">let</span> n <span class="token operator">=</span> <span class="token number">1</span><span class="token punctuation">;</span> n <span class="token operator">&lt;=</span> <span class="token number">1024</span><span class="token punctuation">;</span> n <span class="token operator">*=</span> <span class="token number">2</span><span class="token punctuation">)</span> <span class="token punctuation">{</span> copies <span class="token operator">+=</span> cap<span class="token punctuation">;</span> cap <span class="token operator">*=</span> <span class="token number">2</span><span class="token punctuation">;</span> <span class="token punctuation">}</span>
<span class="token comment">// copies 最终 &lt; 2 * 1024 =&gt; 每次 push 均摊 O(1)</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>追问与易错点</strong>：</p><ul><li>追问：哈希表查询&quot;O(1)&quot;是严格保证吗？答：是均摊/平均 O(1)。冲突退化成链表且负载因子高时最坏 O(n)，这也是哈希冲突要处理的根因。</li><li>追问：什么场景必须放弃哈希表？答：内存极其受限或需要稳定可预测的延迟（如嵌入式），此时用排序 + 二分（O(n log n) + O(log n)）更稳。</li><li>陷阱：把均摊说成&quot;平均情况下很快&quot;，就把两种分析混为一谈；也别说&quot;空间复杂度就是用了几个变量&quot;。</li></ul><h3 id="q3-冒泡、选择、插入、快排、归并、堆排序-怎么实现、怎么对比-稳定性又是什么" tabindex="-1"><a class="header-anchor" href="#q3-冒泡、选择、插入、快排、归并、堆排序-怎么实现、怎么对比-稳定性又是什么" aria-hidden="true">#</a> Q3 冒泡、选择、插入、快排、归并、堆排序，怎么实现、怎么对比？稳定性又是什么？</h3><p><strong>考察点</strong>：考六大排序的实现能力、复杂度表、稳定性，以及&quot;为什么工程里实际用 TimSort 而不是裸快排&quot;。能手写快排/归并且答出对比表才算过关。</p><p><strong>参考答案</strong>：</p><blockquote><p><strong>一句话结论</strong>：冒泡/选择/插入是 O(n²) 的入门级，快排/归并/堆排是 O(n log n) 的主力；快排平均最快但最坏 O(n²) 且不稳定，归并稳定但需 O(n) 额外空间，堆排原地且最坏仍 O(n log n) 但常数大、不稳定。</p></blockquote><ol><li>冒泡（Bubble）：相邻两两比较，每轮把最大值冒到末尾，稳定；加&quot;本轮无交换则提前结束&quot;可对近乎有序数据做到 O(n)。</li><li>选择（Selection）：每轮从未排序区间找最小值交换到前面，交换次数最少（最多 n-1 次），但不稳定。</li><li>插入（Insertion）：把当前元素插入前面已排序区间，稳定，对基本有序数据接近 O(n)，是小区间排序的最优选择，也是 V8 TimSort 的底层组件。</li><li>快速排序（Quick Sort）：选基准分区（Partition），左边都比基准小、右边都比基准大，再递归两侧。平均 O(n log n)，最坏 O(n²)（已有序 + 固定选首元素做基准），靠随机基准/三数取中规避。不稳定、原地。</li><li>归并排序（Merge Sort）：对半切分再合并两个有序数组，<code>T(n)=2T(n/2)+O(n)</code> 得稳定 O(n log n)，<strong>天生适合链表排序</strong>，代价是 O(n) 额外空间。</li><li>堆排序（Heap Sort）：建大顶堆 O(n)，反复把堆顶换到末尾再下沉，最坏也是 O(n log n)、额外空间 O(1)，但访问跳跃、缓存不友好，实测常慢于快排，不稳定。</li><li><strong>稳定性</strong>：指相等元素排序后<strong>相对次序不变</strong>；有远距离交换的算法（快排、选择、堆排）不稳定，只做相邻比较与插入的（冒泡、插入、归并）稳定。业务上&quot;先按分数排、再按班级排&quot;就靠它实现多字段排序。</li><li><strong>边界条件</strong>：空数组与单元素数组要能直接返回；比较器必须返回数字，返回 <code>true/false</code> 会被转成 <code>1/0</code> 导致排序错乱。</li></ol><table><thead><tr><th>排序</th><th>平均</th><th>最坏</th><th>空间</th><th>稳定性</th><th>适用</th></tr></thead><tbody><tr><td>冒泡</td><td>O(n²)</td><td>O(n²)</td><td>O(1)</td><td>稳定</td><td>教学 / 少量数据</td></tr><tr><td>选择</td><td>O(n²)</td><td>O(n²)</td><td>O(1)</td><td>不稳定</td><td>交换成本高的场景</td></tr><tr><td>插入</td><td>O(n²)</td><td>O(n²)</td><td>O(1)</td><td>稳定</td><td>小数组 / 基本有序</td></tr><tr><td>快排</td><td>O(n log n)</td><td>O(n²)</td><td>O(log n)</td><td>不稳定</td><td>通用内存排序，常数最优</td></tr><tr><td>归并</td><td>O(n log n)</td><td>O(n log n)</td><td>O(n)</td><td>稳定</td><td>链表 / 要求稳定</td></tr><tr><td>堆排</td><td>O(n log n)</td><td>O(n log n)</td><td>O(1)</td><td>不稳定</td><td>只求 TopK / 内存极紧</td></tr></tbody></table><div class="language-javascript line-numbers-mode" data-ext="js"><pre class="language-javascript"><code><span class="token keyword">const</span> <span class="token function-variable function">quickSort</span> <span class="token operator">=</span> <span class="token punctuation">(</span><span class="token parameter">arr</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token punctuation">{</span>
  <span class="token keyword">if</span> <span class="token punctuation">(</span>arr<span class="token punctuation">.</span>length <span class="token operator">&lt;=</span> <span class="token number">1</span><span class="token punctuation">)</span> <span class="token keyword">return</span> arr<span class="token punctuation">;</span>              <span class="token comment">// 递归出口</span>
  <span class="token keyword">const</span> <span class="token punctuation">[</span>p<span class="token punctuation">,</span> <span class="token operator">...</span>rest<span class="token punctuation">]</span> <span class="token operator">=</span> arr<span class="token punctuation">;</span>                     <span class="token comment">// 取首元素为基准（生产应随机化）</span>
  <span class="token comment">// 注：filter 分区会额外分配数组，本实现额外空间是 O(n log n)；要对应表格的&quot;原地 O(log n)&quot;须改成双指针原地分区</span>
  <span class="token keyword">const</span> left <span class="token operator">=</span> rest<span class="token punctuation">.</span><span class="token function">filter</span><span class="token punctuation">(</span><span class="token punctuation">(</span><span class="token parameter">x</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> x <span class="token operator">&lt;</span> p<span class="token punctuation">)</span><span class="token punctuation">;</span>
  <span class="token keyword">const</span> right <span class="token operator">=</span> rest<span class="token punctuation">.</span><span class="token function">filter</span><span class="token punctuation">(</span><span class="token punctuation">(</span><span class="token parameter">x</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> x <span class="token operator">&gt;=</span> p<span class="token punctuation">)</span><span class="token punctuation">;</span>     <span class="token comment">// &gt;= 保证等值元素不漏</span>
  <span class="token keyword">return</span> <span class="token punctuation">[</span><span class="token operator">...</span><span class="token function">quickSort</span><span class="token punctuation">(</span>left<span class="token punctuation">)</span><span class="token punctuation">,</span> p<span class="token punctuation">,</span> <span class="token operator">...</span><span class="token function">quickSort</span><span class="token punctuation">(</span>right<span class="token punctuation">)</span><span class="token punctuation">]</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span><span class="token punctuation">;</span>

<span class="token keyword">const</span> <span class="token function-variable function">byScoreDesc</span> <span class="token operator">=</span> <span class="token punctuation">(</span><span class="token parameter">a<span class="token punctuation">,</span> b</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> b<span class="token punctuation">.</span>score <span class="token operator">-</span> a<span class="token punctuation">.</span>score<span class="token punctuation">;</span>   <span class="token comment">// 比较器必须返回数字</span>
<span class="token keyword">const</span> <span class="token function-variable function">byClassAsc</span> <span class="token operator">=</span> <span class="token punctuation">(</span><span class="token parameter">a<span class="token punctuation">,</span> b</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> a<span class="token punctuation">.</span>classId <span class="token operator">-</span> b<span class="token punctuation">.</span>classId<span class="token punctuation">;</span>
list<span class="token punctuation">.</span><span class="token function">sort</span><span class="token punctuation">(</span>byScoreDesc<span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">sort</span><span class="token punctuation">(</span>byClassAsc<span class="token punctuation">)</span><span class="token punctuation">;</span>           <span class="token comment">// 借稳定性做二级排序</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>追问与易错点</strong>：</p><ul><li>追问：<code>Array.prototype.sort</code> 稳定吗？答：ES2019 起规范已明确要求稳定；V8 7.0 前长数组用不稳定快排、短数组用插入排序，之后统一改为 TimSort。</li><li>追问：快排最坏情况怎么优化？答：随机化基准或三数取中避免有序输入退化成 O(n²)，小区间（如 ≤10）切插入排序，递归深时改用尾递归/显式栈防止爆栈。</li><li>陷阱：说&quot;快排最坏 O(n log n)&quot;是硬伤；说&quot;归并原地排序&quot;也不对，标准归并必须 O(n) 辅助数组。</li></ul><h3 id="q4-手写单链表反转-怎么写最稳-顺便说说判环、找中点和合并有序链表。" tabindex="-1"><a class="header-anchor" href="#q4-手写单链表反转-怎么写最稳-顺便说说判环、找中点和合并有序链表。" aria-hidden="true">#</a> Q4 手写单链表反转，怎么写最稳？顺便说说判环、找中点和合并有序链表。</h3><p><strong>考察点</strong>：考指针操作的严谨性与&quot;链表四件套&quot;（反转、判环、找中点、合并）能否用同一套双指针语言讲清。</p><p><strong>参考答案</strong>：</p><blockquote><p><strong>一句话结论</strong>：反转用 <code>prev</code>/<code>curr</code> 双指针，每次先用 <code>next</code> 保存后继再反转方向，O(n) 时间 O(1) 空间；判环用快慢指针相遇，找中点用快指针走两步，合并有序链表用哑节点加双指针逐个接入。</p></blockquote><ol><li>反转三步不能颠倒：先 <code>next = curr.next</code> 存后继，再 <code>curr.next = prev</code> 反转，最后 <code>prev = curr; curr = next</code> 前进。漏存后继就会断链。</li><li>循环结束时 <code>curr</code> 为 <code>null</code>、<code>prev</code> 指向原链表尾节点（新头节点），所以返回 <code>prev</code>；空链表返回 <code>null</code>，单节点无需特判。</li><li>判环：慢指针每次 1 步、快指针每次 2 步；若有环，进入环后快指针每轮相对慢指针靠近 1 步，必然追上；若无环，快指针先到 <code>null</code> 退出。找中点：<code>while (fast &amp;&amp; fast.next)</code> 同步推进，快指针到头时慢指针即中点。</li><li>合并有序链表：建哑节点 <code>dummy</code> 与游标 <code>tail</code>，每次取两链表当前较小者接到 <code>tail.next</code>，最后 <code>tail.next = a || b</code> 把剩余部分整体挂上。哑节点的价值是省掉&quot;首节点单独判断&quot;的分支。</li><li>递归反转的代价：空间是递归栈 O(n)，链表很长时抛 <code>RangeError: Maximum call stack size exceeded</code>，所以工程上优先迭代版。</li><li><strong>复杂度与边界</strong>：反转/判环/找中点时间 O(n)、空间 O(1)；合并是 O(n+m)、空间 O(1)。边界：空链表、单节点、<code>while (fast &amp;&amp; fast.next)</code> 两个条件都不能少（漏掉 <code>fast</code> 判空会越界），合并比较用 <code>&lt;=</code> 以保持稳定性。</li></ol><div class="language-javascript line-numbers-mode" data-ext="js"><pre class="language-javascript"><code><span class="token keyword">function</span> <span class="token function">reverseList</span><span class="token punctuation">(</span><span class="token parameter">head</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
  <span class="token keyword">let</span> prev <span class="token operator">=</span> <span class="token keyword">null</span><span class="token punctuation">,</span> curr <span class="token operator">=</span> head<span class="token punctuation">;</span>
  <span class="token keyword">while</span> <span class="token punctuation">(</span>curr<span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token keyword">const</span> next <span class="token operator">=</span> curr<span class="token punctuation">.</span>next<span class="token punctuation">;</span> <span class="token comment">// 先存后继，否则断链</span>
    curr<span class="token punctuation">.</span>next <span class="token operator">=</span> prev<span class="token punctuation">;</span>       <span class="token comment">// 反转指针</span>
    prev <span class="token operator">=</span> curr<span class="token punctuation">;</span>
    curr <span class="token operator">=</span> next<span class="token punctuation">;</span>
  <span class="token punctuation">}</span>
  <span class="token keyword">return</span> prev<span class="token punctuation">;</span>              <span class="token comment">// 原尾节点即新头节点</span>
<span class="token punctuation">}</span>
<span class="token keyword">function</span> <span class="token function">mergeTwoLists</span><span class="token punctuation">(</span><span class="token parameter">a<span class="token punctuation">,</span> b</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
  <span class="token keyword">const</span> dummy <span class="token operator">=</span> <span class="token punctuation">{</span> <span class="token literal-property property">next</span><span class="token operator">:</span> <span class="token keyword">null</span> <span class="token punctuation">}</span><span class="token punctuation">;</span> <span class="token comment">// 哑节点，省掉首节点特判</span>
  <span class="token keyword">let</span> tail <span class="token operator">=</span> dummy<span class="token punctuation">;</span>
  <span class="token keyword">while</span> <span class="token punctuation">(</span>a <span class="token operator">&amp;&amp;</span> b<span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token keyword">if</span> <span class="token punctuation">(</span>a<span class="token punctuation">.</span>val <span class="token operator">&lt;=</span> b<span class="token punctuation">.</span>val<span class="token punctuation">)</span> <span class="token punctuation">{</span> tail<span class="token punctuation">.</span>next <span class="token operator">=</span> a<span class="token punctuation">;</span> a <span class="token operator">=</span> a<span class="token punctuation">.</span>next<span class="token punctuation">;</span> <span class="token punctuation">}</span> <span class="token comment">// &lt;= 保持稳定</span>
    <span class="token keyword">else</span> <span class="token punctuation">{</span> tail<span class="token punctuation">.</span>next <span class="token operator">=</span> b<span class="token punctuation">;</span> b <span class="token operator">=</span> b<span class="token punctuation">.</span>next<span class="token punctuation">;</span> <span class="token punctuation">}</span>
    tail <span class="token operator">=</span> tail<span class="token punctuation">.</span>next<span class="token punctuation">;</span>
  <span class="token punctuation">}</span>
  tail<span class="token punctuation">.</span>next <span class="token operator">=</span> a <span class="token operator">||</span> b<span class="token punctuation">;</span>           <span class="token comment">// 接上剩余部分</span>
  <span class="token keyword">return</span> dummy<span class="token punctuation">.</span>next<span class="token punctuation">;</span>
<span class="token punctuation">}</span>
<span class="token comment">// 判断有环：快慢指针，相遇即有环（时间 O(n)、空间 O(1)）</span>
<span class="token keyword">function</span> <span class="token function">hasCycle</span><span class="token punctuation">(</span><span class="token parameter">head</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
  <span class="token keyword">let</span> slow <span class="token operator">=</span> head<span class="token punctuation">,</span> fast <span class="token operator">=</span> head<span class="token punctuation">;</span>
  <span class="token keyword">while</span> <span class="token punctuation">(</span>fast <span class="token operator">&amp;&amp;</span> fast<span class="token punctuation">.</span>next<span class="token punctuation">)</span> <span class="token punctuation">{</span>
    slow <span class="token operator">=</span> slow<span class="token punctuation">.</span>next<span class="token punctuation">;</span> fast <span class="token operator">=</span> fast<span class="token punctuation">.</span>next<span class="token punctuation">.</span>next<span class="token punctuation">;</span>
    <span class="token keyword">if</span> <span class="token punctuation">(</span>slow <span class="token operator">===</span> fast<span class="token punctuation">)</span> <span class="token keyword">return</span> <span class="token boolean">true</span><span class="token punctuation">;</span>
  <span class="token punctuation">}</span>
  <span class="token keyword">return</span> <span class="token boolean">false</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
<span class="token comment">// 找中点：快指针走两步、慢指针走一步，快指针到头时慢指针即中点</span>
<span class="token keyword">const</span> <span class="token function-variable function">middleNode</span> <span class="token operator">=</span> <span class="token punctuation">(</span><span class="token parameter">head</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token punctuation">{</span>
  <span class="token keyword">let</span> slow <span class="token operator">=</span> head<span class="token punctuation">,</span> fast <span class="token operator">=</span> head<span class="token punctuation">;</span>
  <span class="token keyword">while</span> <span class="token punctuation">(</span>fast <span class="token operator">&amp;&amp;</span> fast<span class="token punctuation">.</span>next<span class="token punctuation">)</span> <span class="token punctuation">{</span> slow <span class="token operator">=</span> slow<span class="token punctuation">.</span>next<span class="token punctuation">;</span> fast <span class="token operator">=</span> fast<span class="token punctuation">.</span>next<span class="token punctuation">.</span>next<span class="token punctuation">;</span> <span class="token punctuation">}</span>
  <span class="token keyword">return</span> slow<span class="token punctuation">;</span>
<span class="token punctuation">}</span><span class="token punctuation">;</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>追问与易错点</strong>：</p><ul><li>追问：有环怎么找入口？答：相遇后让一个指针回到起点，两指针同速前进，再次相遇处就是入环点；数学上由&quot;头到入口距离 = 相遇点到入口距离&quot;保证。</li><li>追问：快指针能不能走三步？答：不行。相对速度为 1 才能保证在环内一定相遇，走三步可能直接跳过慢指针永远错过。</li><li>陷阱：把 <code>curr.next = prev</code> 写在 <code>const next = curr.next</code> 之前，或返回 <code>curr</code>（此时是 <code>null</code>）；合并时忘记 <code>tail.next = a || b</code> 收尾会漏掉剩余节点。</li></ul><h3 id="q5-用两个栈实现一个队列-怎么想-最小栈又怎么设计" tabindex="-1"><a class="header-anchor" href="#q5-用两个栈实现一个队列-怎么想-最小栈又怎么设计" aria-hidden="true">#</a> Q5 用两个栈实现一个队列，怎么想？最小栈又怎么设计？</h3><p><strong>考察点</strong>：考栈与队列的语义差异，以及&quot;一次倒腾只做一次&quot;的均摊思想与&quot;辅助栈记录历史极值&quot;的设计直觉。</p><p><strong>参考答案</strong>：</p><blockquote><p><strong>一句话结论</strong>：队列用 <code>inStack</code> 入队、<code>outStack</code> 出队，只在 <code>outStack</code> 为空时把 <code>inStack</code> 整体倒入，单次可能 O(n) 但每个元素只搬一次，均摊 O(1)；最小栈用一个同步的辅助栈记录&quot;每个历史状态的最小值&quot;，所有操作 O(1)。</p></blockquote><ol><li>栈是后进先出（LIFO），队列是先进先出（FIFO）；入栈顺序与出队顺序相反，所以要用第二个栈&quot;倒序&quot;一次。</li><li>关键纪律：只在 <code>outStack</code> 为空时才整体倒腾，绝不能每次 <code>pop</code> 都倒一遍，否则复杂度从均摊 O(1) 退化成 O(n)。</li><li>最小栈的核心洞察：最小值会随弹栈&quot;回退&quot;，所以必须把<strong>每个历史状态的最小值</strong>都存下来，这正是辅助栈的作用。</li><li>最小栈的规则：<code>push</code> 时主栈压 <code>val</code>、辅助栈压 <code>Math.min(val, 辅助栈顶)</code>；<code>pop</code> 时两栈同步弹出，<code>getMin</code> 直接取辅助栈顶。</li><li>辅助栈优化：只在&quot;新值 ≤ 当前最小值&quot;时才压入（注意用 <code>&lt;=</code> 而非 <code>&lt;</code>，否则重复最小值被提前弹走），常见数据下能明显省内存。</li><li><strong>复杂度与边界</strong>：双栈队列 <code>push</code> 稳定 O(1)，<code>pop</code>/<code>peek</code> 最坏 O(n)、均摊 O(1)，空间 O(n)；最小栈全部操作 O(1)，额外空间 O(n)。边界：空队列 <code>pop</code> 应返回 <code>undefined</code> 或抛错而不是静默出错；<code>outStack</code> 非空时不能再倒入 <code>inStack</code>，否则 FIFO 顺序被破坏。</li></ol><div class="language-javascript line-numbers-mode" data-ext="js"><pre class="language-javascript"><code><span class="token comment">// 用两个栈实现队列：只在 outStack 空时倒腾一次（均摊 O(1)）</span>
<span class="token keyword">class</span> <span class="token class-name">MyQueue</span> <span class="token punctuation">{</span>
  <span class="token function">constructor</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span> <span class="token keyword">this</span><span class="token punctuation">.</span>inStack <span class="token operator">=</span> <span class="token punctuation">[</span><span class="token punctuation">]</span><span class="token punctuation">;</span> <span class="token keyword">this</span><span class="token punctuation">.</span>outStack <span class="token operator">=</span> <span class="token punctuation">[</span><span class="token punctuation">]</span><span class="token punctuation">;</span> <span class="token punctuation">}</span>
  <span class="token function">push</span><span class="token punctuation">(</span><span class="token parameter">x</span><span class="token punctuation">)</span> <span class="token punctuation">{</span> <span class="token keyword">this</span><span class="token punctuation">.</span>inStack<span class="token punctuation">.</span><span class="token function">push</span><span class="token punctuation">(</span>x<span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token punctuation">}</span>
  <span class="token function">_shift</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>                                     <span class="token comment">// 只在 outStack 空时倒腾</span>
    <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token operator">!</span><span class="token keyword">this</span><span class="token punctuation">.</span>outStack<span class="token punctuation">.</span>length<span class="token punctuation">)</span> <span class="token punctuation">{</span>
      <span class="token keyword">while</span> <span class="token punctuation">(</span><span class="token keyword">this</span><span class="token punctuation">.</span>inStack<span class="token punctuation">.</span>length<span class="token punctuation">)</span> <span class="token keyword">this</span><span class="token punctuation">.</span>outStack<span class="token punctuation">.</span><span class="token function">push</span><span class="token punctuation">(</span><span class="token keyword">this</span><span class="token punctuation">.</span>inStack<span class="token punctuation">.</span><span class="token function">pop</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>
  <span class="token punctuation">}</span>
  <span class="token function">pop</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span> <span class="token keyword">this</span><span class="token punctuation">.</span><span class="token function">_shift</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token keyword">return</span> <span class="token keyword">this</span><span class="token punctuation">.</span>outStack<span class="token punctuation">.</span><span class="token function">pop</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token punctuation">}</span>
  <span class="token function">empty</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span> <span class="token keyword">return</span> <span class="token operator">!</span><span class="token keyword">this</span><span class="token punctuation">.</span>inStack<span class="token punctuation">.</span>length <span class="token operator">&amp;&amp;</span> <span class="token operator">!</span><span class="token keyword">this</span><span class="token punctuation">.</span>outStack<span class="token punctuation">.</span>length<span class="token punctuation">;</span> <span class="token punctuation">}</span>
<span class="token punctuation">}</span>
<span class="token comment">// 最小栈：辅助栈同步记录每个历史状态的最小值</span>
<span class="token keyword">class</span> <span class="token class-name">MinStack</span> <span class="token punctuation">{</span>
  <span class="token function">constructor</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span> <span class="token keyword">this</span><span class="token punctuation">.</span>stack <span class="token operator">=</span> <span class="token punctuation">[</span><span class="token punctuation">]</span><span class="token punctuation">;</span> <span class="token keyword">this</span><span class="token punctuation">.</span>min <span class="token operator">=</span> <span class="token punctuation">[</span><span class="token punctuation">]</span><span class="token punctuation">;</span> <span class="token punctuation">}</span>
  <span class="token function">push</span><span class="token punctuation">(</span><span class="token parameter">v</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token keyword">this</span><span class="token punctuation">.</span>stack<span class="token punctuation">.</span><span class="token function">push</span><span class="token punctuation">(</span>v<span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token keyword">this</span><span class="token punctuation">.</span>min<span class="token punctuation">.</span><span class="token function">push</span><span class="token punctuation">(</span>Math<span class="token punctuation">.</span><span class="token function">min</span><span class="token punctuation">(</span>v<span class="token punctuation">,</span> <span class="token keyword">this</span><span class="token punctuation">.</span>min<span class="token punctuation">.</span>length <span class="token operator">?</span> <span class="token keyword">this</span><span class="token punctuation">.</span>min<span class="token punctuation">[</span><span class="token keyword">this</span><span class="token punctuation">.</span>min<span class="token punctuation">.</span>length <span class="token operator">-</span> <span class="token number">1</span><span class="token punctuation">]</span> <span class="token operator">:</span> <span class="token number">Infinity</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
  <span class="token punctuation">}</span>
  <span class="token function">pop</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span> <span class="token keyword">this</span><span class="token punctuation">.</span>min<span class="token punctuation">.</span><span class="token function">pop</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token keyword">return</span> <span class="token keyword">this</span><span class="token punctuation">.</span>stack<span class="token punctuation">.</span><span class="token function">pop</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token punctuation">}</span> <span class="token comment">// 两栈同步弹</span>
  <span class="token function">getMin</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span> <span class="token keyword">return</span> <span class="token keyword">this</span><span class="token punctuation">.</span>min<span class="token punctuation">[</span><span class="token keyword">this</span><span class="token punctuation">.</span>min<span class="token punctuation">.</span>length <span class="token operator">-</span> <span class="token number">1</span><span class="token punctuation">]</span><span class="token punctuation">;</span> <span class="token punctuation">}</span>
<span class="token punctuation">}</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>追问与易错点</strong>：</p><ul><li>追问：最小栈能不能只用一个变量记最小值？答：不行。弹出当前最小值后&quot;上一个最小值&quot;就找不回来了，除非能 O(n) 重新扫描，那就破坏了 O(1)。</li><li>追问：为什么双栈队列的均摊是 O(1)？答：n 个元素总搬运次数不超过 n，总操作数 O(n)，摊到每个元素 O(1)。</li><li>陷阱：每次 <code>pop</code> 都无条件倒腾一遍，功能对但复杂度错；最小栈辅助栈用 <code>&lt;</code> 而不是 <code>&lt;=</code>，重复最小值只入栈一次，弹出一次后 <code>getMin</code> 就错了。</li></ul><h3 id="q6-有效的括号怎么解-单调栈又是什么" tabindex="-1"><a class="header-anchor" href="#q6-有效的括号怎么解-单调栈又是什么" aria-hidden="true">#</a> Q6 有效的括号怎么解？单调栈又是什么？</h3><p><strong>考察点</strong>：考栈的两个典型应用——配对校验与&quot;找下一个更大元素&quot;；能说清单调栈为什么是 O(n) 才算过关。</p><p><strong>参考答案</strong>：</p><blockquote><p><strong>一句话结论</strong>：括号题遇左括号入栈、遇右括号必须与栈顶配对，否则失败，遍历完栈必须为空；单调栈是栈内元素保持单调的栈，专门解&quot;找每个元素左/右第一个更大或更小的元素&quot;，每个元素最多进出栈一次，所以是 O(n)。</p></blockquote><ol><li>括号题的失败条件一：遇到右括号时栈为空，说明没有可配对的左括号，如 <code>&quot;)(&quot;</code>。</li><li>括号题的失败条件二：栈顶与当前右括号类型不一致，说明嵌套顺序非法，如 <code>&quot;([)]&quot;</code>——数量对但顺序错。</li><li>括号题的收尾条件：遍历结束后栈必须为空，否则有未闭合的左括号，如 <code>&quot;(((&quot;</code>。这一步最容易被漏掉。</li><li>优化：用哈希表存&quot;右括号 → 左括号&quot;的映射，把多层 <code>if/else</code> 压成一次查表；栈空时 <code>pop()</code> 返回 <code>undefined</code>，与任何字符都不等，天然返回 <code>false</code>。</li><li>单调栈的识别信号：题目出现&quot;下一个更大元素&quot;&quot;每日温度&quot;&quot;接雨水&quot;&quot;柱状图最大矩形&quot;就该想到它。求下一个更大元素用<strong>递减栈</strong>：<code>while (栈顶值 &lt; 当前值)</code> 弹出并记录当前值就是栈顶的下一个更大元素；需要求&quot;滑动窗口最大值&quot;时用的是它的近亲<strong>单调队列</strong>。</li><li><strong>复杂度与边界</strong>：括号题时间 O(n)、空间 O(n)；单调栈虽然内层有 <code>while</code>，但每个元素只入栈一次、出栈一次，总操作数 ≤ 2n，所以也是 O(n)、空间 O(n)。边界：空字符串应返回 <code>true</code>；单调栈要求存<strong>下标</strong>而不是值，否则无法计算距离或位置。</li></ol><div class="language-javascript line-numbers-mode" data-ext="js"><pre class="language-javascript"><code><span class="token comment">// 有效的括号：遇左括号入栈，遇右括号必须与栈顶配对</span>
<span class="token keyword">function</span> <span class="token function">isValid</span><span class="token punctuation">(</span><span class="token parameter">s</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
  <span class="token keyword">const</span> map <span class="token operator">=</span> <span class="token punctuation">{</span> <span class="token string-property property">&#39;)&#39;</span><span class="token operator">:</span> <span class="token string">&#39;(&#39;</span><span class="token punctuation">,</span> <span class="token string-property property">&#39;]&#39;</span><span class="token operator">:</span> <span class="token string">&#39;[&#39;</span><span class="token punctuation">,</span> <span class="token string-property property">&#39;}&#39;</span><span class="token operator">:</span> <span class="token string">&#39;{&#39;</span> <span class="token punctuation">}</span><span class="token punctuation">;</span>
  <span class="token keyword">const</span> st <span class="token operator">=</span> <span class="token punctuation">[</span><span class="token punctuation">]</span><span class="token punctuation">;</span>
  <span class="token keyword">for</span> <span class="token punctuation">(</span><span class="token keyword">const</span> ch <span class="token keyword">of</span> s<span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token operator">!</span>map<span class="token punctuation">[</span>ch<span class="token punctuation">]</span><span class="token punctuation">)</span> st<span class="token punctuation">.</span><span class="token function">push</span><span class="token punctuation">(</span>ch<span class="token punctuation">)</span><span class="token punctuation">;</span>            <span class="token comment">// 左括号入栈</span>
    <span class="token keyword">else</span> <span class="token keyword">if</span> <span class="token punctuation">(</span>st<span class="token punctuation">.</span><span class="token function">pop</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">!==</span> map<span class="token punctuation">[</span>ch<span class="token punctuation">]</span><span class="token punctuation">)</span> <span class="token keyword">return</span> <span class="token boolean">false</span><span class="token punctuation">;</span> <span class="token comment">// 栈空或错配都失败</span>
  <span class="token punctuation">}</span>
  <span class="token keyword">return</span> st<span class="token punctuation">.</span>length <span class="token operator">===</span> <span class="token number">0</span><span class="token punctuation">;</span>                 <span class="token comment">// 结尾必须清空</span>
<span class="token punctuation">}</span>
<span class="token comment">// 每日温度：下一个更高温还有几天（单调递减栈，栈存下标）</span>
<span class="token keyword">function</span> <span class="token function">dailyTemperatures</span><span class="token punctuation">(</span><span class="token parameter"><span class="token constant">T</span></span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
  <span class="token keyword">const</span> res <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token class-name">Array</span><span class="token punctuation">(</span><span class="token constant">T</span><span class="token punctuation">.</span>length<span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">fill</span><span class="token punctuation">(</span><span class="token number">0</span><span class="token punctuation">)</span><span class="token punctuation">,</span> stack <span class="token operator">=</span> <span class="token punctuation">[</span><span class="token punctuation">]</span><span class="token punctuation">;</span>
  <span class="token keyword">for</span> <span class="token punctuation">(</span><span class="token keyword">let</span> i <span class="token operator">=</span> <span class="token number">0</span><span class="token punctuation">;</span> i <span class="token operator">&lt;</span> <span class="token constant">T</span><span class="token punctuation">.</span>length<span class="token punctuation">;</span> i<span class="token operator">++</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token keyword">while</span> <span class="token punctuation">(</span>stack<span class="token punctuation">.</span>length <span class="token operator">&amp;&amp;</span> <span class="token constant">T</span><span class="token punctuation">[</span>i<span class="token punctuation">]</span> <span class="token operator">&gt;</span> <span class="token constant">T</span><span class="token punctuation">[</span>stack<span class="token punctuation">[</span>stack<span class="token punctuation">.</span>length <span class="token operator">-</span> <span class="token number">1</span><span class="token punctuation">]</span><span class="token punctuation">]</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
      <span class="token keyword">const</span> j <span class="token operator">=</span> stack<span class="token punctuation">.</span><span class="token function">pop</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>              <span class="token comment">// j 的下一个更高温就是 i</span>
      res<span class="token punctuation">[</span>j<span class="token punctuation">]</span> <span class="token operator">=</span> i <span class="token operator">-</span> j<span class="token punctuation">;</span>
    <span class="token punctuation">}</span>
    stack<span class="token punctuation">.</span><span class="token function">push</span><span class="token punctuation">(</span>i<span class="token punctuation">)</span><span class="token punctuation">;</span>
  <span class="token punctuation">}</span>
  <span class="token keyword">return</span> res<span class="token punctuation">;</span>                             <span class="token comment">// 栈中剩余元素保持 0</span>
<span class="token punctuation">}</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>追问与易错点</strong>：</p><ul><li>追问：求&quot;下一个更小元素&quot;怎么改？答：把递减栈改成递增栈，比较符号反过来（栈顶 &gt; 当前值就弹出）。</li><li>追问：单调栈和优先队列怎么选？答：需要&quot;整体有序并随时取最大&quot;用堆；只需要&quot;每个元素找最近的更大/更小邻居&quot;用单调栈，后者 O(n) 且实现更简单。</li><li>陷阱：括号题只统计左右括号数量是否相等，会放过 <code>&quot;([)]&quot;</code>；说单调栈是 O(n²)（因为看到两层循环），没意识到每个元素只进出一次。</li></ul><h3 id="q7-哈希表是怎么实现的-哈希冲突怎么解决-js-里-map-和对象有什么区别" tabindex="-1"><a class="header-anchor" href="#q7-哈希表是怎么实现的-哈希冲突怎么解决-js-里-map-和对象有什么区别" aria-hidden="true">#</a> Q7 哈希表是怎么实现的？哈希冲突怎么解决？JS 里 Map 和对象有什么区别？</h3><p><strong>考察点</strong>：考哈希函数、冲突处理与 JS 落地实现的差异；能说清&quot;为什么 Map 的 key 可以是任意类型&quot;才算过关。</p><p><strong>参考答案</strong>：</p><blockquote><p><strong>一句话结论</strong>：哈希表用哈希函数把 key 映射到桶下标，实现平均 O(1) 的增删查；冲突用链地址法（拉链）或开放寻址法解决；JS 的 <code>Map</code> 允许任意类型 key 且保留插入顺序，普通对象只允许字符串（和 Symbol）key。</p></blockquote><ol><li>基本结构：<code>bucket = hash(key) % capacity</code>，桶里存键值对；查找时先定位桶，再在桶内比较 key 是否相等。</li><li>冲突处理——链地址法：同一下标的元素挂成链表（Java 的 <code>HashMap</code> 在链表过长时转红黑树）；实现简单、删除方便，是主流做法。</li><li>冲突处理——开放寻址法：位置被占就按线性探测/平方探测往后找空位；省去指针开销、缓存友好，但删除要打墓碑标记，负载因子高时性能骤降。</li><li>扩容与负载因子：元素数 / 桶数超过阈值（如 0.75）就扩容并重新哈希（Rehash），保证平均 O(1)；这就是哈希表&quot;均摊 O(1)&quot;的来源。</li><li>JS 差异：<code>Map</code> 的 key 可以是对象、函数、<code>NaN</code>（用 SameValueZero 比较），并保证插入顺序遍历；普通对象的 key 都会被 <code>toString</code> 成字符串，所以 <code>obj[{a:1}]</code> 实际是 <code>obj[&quot;[object Object]&quot;]</code>，是个隐蔽 bug。</li><li><strong>复杂度与边界</strong>：平均 O(1) 是&quot;哈希均匀 + 负载因子受控&quot;的假设下的结论，最坏 O(n)（全部撞同一个桶）；边界：用 <code>WeakMap</code> 存 DOM 节点或对象引用可避免内存泄漏，但 <code>WeakMap</code> 不可遍历、也没有 <code>size</code>。</li></ol><table><thead><tr><th>对比项</th><th>Object</th><th>Map</th></tr></thead><tbody><tr><td>key 类型</td><td>字符串 / Symbol</td><td>任意类型（含对象）</td></tr><tr><td>顺序</td><td>整数键升序 + 字符串插入序</td><td>严格插入顺序</td></tr><tr><td>大小</td><td>需 <code>Object.keys().length</code></td><td><code>map.size</code> O(1)</td></tr><tr><td>原型污染</td><td>有（可用 <code>Object.create(null)</code> 规避）</td><td>无</td></tr><tr><td>JSON</td><td>直接支持</td><td>需手动转数组</td></tr></tbody></table><p><strong>追问与易错点</strong>：</p><ul><li>追问：为什么说 <code>Map</code> 查找是&quot;平均&quot; O(1)？答：假设哈希均匀分布且负载因子受控；最坏情况所有 key 撞同一个桶，退化成 O(n)。</li><li>追问：什么是哈希洪水攻击（Hash Flooding）？答：攻击者构造大量同桶 key 让哈希表退化成链表，拖垮服务；防御手段是随机化哈希种子（如 SipHash）。</li><li>陷阱：用对象当 key 做缓存，<code>cache[obj]</code> 实际是 <code>cache[&quot;[object Object]&quot;]</code>，所有对象互相覆盖；这种 bug 只能用 <code>Map</code> 或 <code>WeakMap</code> 解决。</li></ul><h3 id="q8-两数之和怎么做-能不能再优" tabindex="-1"><a class="header-anchor" href="#q8-两数之和怎么做-能不能再优" aria-hidden="true">#</a> Q8 两数之和怎么做？能不能再优？</h3><p><strong>考察点</strong>：考从暴力 O(n²) 到哈希 O(n) 的优化推导，以及&quot;为什么必须先查后存&quot;这个细节。</p><p><strong>参考答案</strong>：</p><blockquote><p><strong>一句话结论</strong>：用哈希表存&quot;已遍历元素 → 下标&quot;，遍历时先查 <code>target - nums[i]</code> 是否出现过，存在即返回两个下标；时间 O(n)、空间 O(n)，比双重循环的 O(n²) 快一个量级。</p></blockquote><ol><li>暴力法：两层循环枚举所有组合，时间 O(n²)、空间 O(1)。面试要先说出暴力解，再给出优化，体现推导过程而不是直接背答案。</li><li>优化动机：暴力法的瓶颈在&quot;每次都要重新找一个数是否存在&quot;——这正是哈希表擅长的事，把&quot;查找&quot;从 O(n) 降到 O(1)。</li><li>一次遍历：遍历时先查补数是否已在表里，在就返回；不在就把当前元素和下标存表。顺序不能反，否则同一个元素会被自己匹配两次（如 <code>[3], target=6</code>）。</li><li><strong>复杂度与边界</strong>：时间 O(n)、空间 O(n)。边界：空数组或无解返回空数组；重复值（<code>[3,3], target=6</code>）必须靠&quot;下标不同&quot;判断，先查后存的写法天然满足。</li><li>取舍：有解且只需一组时哈希最优；如果数组<strong>已排序</strong>且要求 O(1) 额外空间，用左右双指针更优，时间 O(n)、空间 O(1)。</li><li>同族题：三数之和、四数之和用排序 + 双指针；&quot;和为 K 的子数组&quot;用前缀和 + 哈希表。</li></ol><div class="language-javascript line-numbers-mode" data-ext="js"><pre class="language-javascript"><code><span class="token keyword">function</span> <span class="token function">twoSum</span><span class="token punctuation">(</span><span class="token parameter">nums<span class="token punctuation">,</span> target</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
  <span class="token keyword">const</span> map <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token class-name">Map</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>                  <span class="token comment">// 值 -&gt; 下标</span>
  <span class="token keyword">for</span> <span class="token punctuation">(</span><span class="token keyword">let</span> i <span class="token operator">=</span> <span class="token number">0</span><span class="token punctuation">;</span> i <span class="token operator">&lt;</span> nums<span class="token punctuation">.</span>length<span class="token punctuation">;</span> i<span class="token operator">++</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token keyword">const</span> need <span class="token operator">=</span> target <span class="token operator">-</span> nums<span class="token punctuation">[</span>i<span class="token punctuation">]</span><span class="token punctuation">;</span>
    <span class="token keyword">if</span> <span class="token punctuation">(</span>map<span class="token punctuation">.</span><span class="token function">has</span><span class="token punctuation">(</span>need<span class="token punctuation">)</span><span class="token punctuation">)</span> <span class="token keyword">return</span> <span class="token punctuation">[</span>map<span class="token punctuation">.</span><span class="token function">get</span><span class="token punctuation">(</span>need<span class="token punctuation">)</span><span class="token punctuation">,</span> i<span class="token punctuation">]</span><span class="token punctuation">;</span> <span class="token comment">// 先查</span>
    map<span class="token punctuation">.</span><span class="token function">set</span><span class="token punctuation">(</span>nums<span class="token punctuation">[</span>i<span class="token punctuation">]</span><span class="token punctuation">,</span> i<span class="token punctuation">)</span><span class="token punctuation">;</span>                          <span class="token comment">// 后存</span>
  <span class="token punctuation">}</span>
  <span class="token keyword">return</span> <span class="token punctuation">[</span><span class="token punctuation">]</span><span class="token punctuation">;</span>                              <span class="token comment">// 无解</span>
<span class="token punctuation">}</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>追问与易错点</strong>：</p><ul><li>追问：为什么不能先存后查？答：会把当前元素自己当成补数，<code>[3], target=6</code> 会错误返回 <code>[0,0]</code>。</li><li>追问：如果数组有序，还有更优解吗？答：左右双指针，和小于 target 左指针右移、和大于 target 右指针左移，O(n) 时间 O(1) 空间，比哈希省内存。</li><li>陷阱：用对象 <code>{}</code> 做表时下标为 <code>0</code> 会被判假，<code>if (map[need])</code> 漏掉下标 0；应该用 <code>!== undefined</code> 或直接用 <code>Map</code>。</li></ul><h3 id="q9-字符串反转、单词反转、最长公共前缀、回文判断怎么一次讲清" tabindex="-1"><a class="header-anchor" href="#q9-字符串反转、单词反转、最长公共前缀、回文判断怎么一次讲清" aria-hidden="true">#</a> Q9 字符串反转、单词反转、最长公共前缀、回文判断怎么一次讲清？</h3><p><strong>考察点</strong>：考字符串 API 组合能力、<code>Unicode</code> 边界意识与&quot;逐字符纵向比较&quot;的直觉；能主动提&quot;表情符号会被拆坏&quot;才算过关。</p><p><strong>参考答案</strong>：</p><blockquote><p><strong>一句话结论</strong>：字符串反转用 <code>[...str].reverse().join(&#39;&#39;)</code>；单词反转先按空格切分再反转单词顺序；最长公共前缀以第一个字符串为基准逐字符与其他串同位比较；回文用左右双指针跳过非字母数字字符。四者都是 O(n) 级别。</p></blockquote><ol><li>字符反转：用扩展运算符而不是 <code>split(&#39;&#39;)</code>，因为扩展运算符按 Unicode 码点切分，不会把 emoji 拆成两个乱码字符。</li><li>单词反转（句子翻转）：经典做法是先整体反转再对每个单词反转；或者 <code>split(/\\s+/)</code> 反转后拼接——<strong>注意</strong>这会丢失原来的连续空格与首尾空格，若题目要求保留空格就必须用双指针原地处理。</li><li>最长公共前缀（Longest Common Prefix）：纵向扫描，同时比较所有字符串的第 <code>i</code> 个字符，有一个不同或长度不足就返回前 <code>i</code> 个字符。最坏时间 O(n·m)（n 为串个数、m 为最短串长度），空间 O(1)。</li><li>回文判断（Palindrome）：左右双指针，跳过非字母数字字符并统一小写，指针相遇即回文。允许删除一个字符的变体用双指针 + 一次跳过的分支判断。</li><li><strong>复杂度与边界</strong>：字符反转与回文 O(n) 时间，<code>split/reverse/join</code> 额外 O(n) 空间、双指针 O(1)；最长公共前缀 O(n·m)。边界：数组为空返回 <code>&#39;&#39;</code>、只有一个字符串返回它本身、存在空串时公共前缀必然是 <code>&#39;&#39;</code>、回文要能跳过标点。</li><li>常见追问：<code>&#39;👍&#39;.split(&#39;&#39;)</code> 会得到两个乱码代理项，所以必须用扩展运算符或 <code>Array.from</code>；&quot;最长公共子串&quot;与&quot;最长公共前缀&quot;不是一回事，前者允许出现在任意位置。</li></ol><div class="language-javascript line-numbers-mode" data-ext="js"><pre class="language-javascript"><code><span class="token keyword">function</span> <span class="token function">longestCommonPrefix</span><span class="token punctuation">(</span><span class="token parameter">strs</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
  <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token operator">!</span>strs<span class="token punctuation">.</span>length<span class="token punctuation">)</span> <span class="token keyword">return</span> <span class="token string">&#39;&#39;</span><span class="token punctuation">;</span>          <span class="token comment">// 空数组边界</span>
  <span class="token keyword">for</span> <span class="token punctuation">(</span><span class="token keyword">let</span> i <span class="token operator">=</span> <span class="token number">0</span><span class="token punctuation">;</span> i <span class="token operator">&lt;</span> strs<span class="token punctuation">[</span><span class="token number">0</span><span class="token punctuation">]</span><span class="token punctuation">.</span>length<span class="token punctuation">;</span> i<span class="token operator">++</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token keyword">const</span> ch <span class="token operator">=</span> strs<span class="token punctuation">[</span><span class="token number">0</span><span class="token punctuation">]</span><span class="token punctuation">[</span>i<span class="token punctuation">]</span><span class="token punctuation">;</span>
    <span class="token keyword">for</span> <span class="token punctuation">(</span><span class="token keyword">let</span> j <span class="token operator">=</span> <span class="token number">1</span><span class="token punctuation">;</span> j <span class="token operator">&lt;</span> strs<span class="token punctuation">.</span>length<span class="token punctuation">;</span> j<span class="token operator">++</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
      <span class="token keyword">if</span> <span class="token punctuation">(</span>i <span class="token operator">&gt;=</span> strs<span class="token punctuation">[</span>j<span class="token punctuation">]</span><span class="token punctuation">.</span>length <span class="token operator">||</span> strs<span class="token punctuation">[</span>j<span class="token punctuation">]</span><span class="token punctuation">[</span>i<span class="token punctuation">]</span> <span class="token operator">!==</span> ch<span class="token punctuation">)</span> <span class="token keyword">return</span> strs<span class="token punctuation">[</span><span class="token number">0</span><span class="token punctuation">]</span><span class="token punctuation">.</span><span class="token function">slice</span><span class="token punctuation">(</span><span class="token number">0</span><span class="token punctuation">,</span> i<span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>
  <span class="token punctuation">}</span>
  <span class="token keyword">return</span> strs<span class="token punctuation">[</span><span class="token number">0</span><span class="token punctuation">]</span><span class="token punctuation">;</span>                       <span class="token comment">// 第一个串本身就是公共前缀</span>
<span class="token punctuation">}</span>
<span class="token comment">// 回文判断：左右双指针，跳过非字母数字字符</span>
<span class="token keyword">function</span> <span class="token function">isPalindrome</span><span class="token punctuation">(</span><span class="token parameter">s</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
  <span class="token keyword">const</span> t <span class="token operator">=</span> s<span class="token punctuation">.</span><span class="token function">toLowerCase</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
  <span class="token keyword">let</span> i <span class="token operator">=</span> <span class="token number">0</span><span class="token punctuation">,</span> j <span class="token operator">=</span> t<span class="token punctuation">.</span>length <span class="token operator">-</span> <span class="token number">1</span><span class="token punctuation">;</span>
  <span class="token keyword">const</span> <span class="token function-variable function">ok</span> <span class="token operator">=</span> <span class="token punctuation">(</span><span class="token parameter">c</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token regex"><span class="token regex-delimiter">/</span><span class="token regex-source language-regex">[a-z0-9]</span><span class="token regex-delimiter">/</span></span><span class="token punctuation">.</span><span class="token function">test</span><span class="token punctuation">(</span>c<span class="token punctuation">)</span><span class="token punctuation">;</span>
  <span class="token keyword">while</span> <span class="token punctuation">(</span>i <span class="token operator">&lt;</span> j<span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token keyword">while</span> <span class="token punctuation">(</span>i <span class="token operator">&lt;</span> j <span class="token operator">&amp;&amp;</span> <span class="token operator">!</span><span class="token function">ok</span><span class="token punctuation">(</span>t<span class="token punctuation">[</span>i<span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">)</span> i<span class="token operator">++</span><span class="token punctuation">;</span>
    <span class="token keyword">while</span> <span class="token punctuation">(</span>i <span class="token operator">&lt;</span> j <span class="token operator">&amp;&amp;</span> <span class="token operator">!</span><span class="token function">ok</span><span class="token punctuation">(</span>t<span class="token punctuation">[</span>j<span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">)</span> j<span class="token operator">--</span><span class="token punctuation">;</span>
    <span class="token keyword">if</span> <span class="token punctuation">(</span>t<span class="token punctuation">[</span>i<span class="token operator">++</span><span class="token punctuation">]</span> <span class="token operator">!==</span> t<span class="token punctuation">[</span>j<span class="token operator">--</span><span class="token punctuation">]</span><span class="token punctuation">)</span> <span class="token keyword">return</span> <span class="token boolean">false</span><span class="token punctuation">;</span>
  <span class="token punctuation">}</span>
  <span class="token keyword">return</span> <span class="token boolean">true</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
<span class="token keyword">const</span> <span class="token function-variable function">reverseStr</span> <span class="token operator">=</span> <span class="token punctuation">(</span><span class="token parameter">s</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span><span class="token operator">...</span>s<span class="token punctuation">]</span><span class="token punctuation">.</span><span class="token function">reverse</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">join</span><span class="token punctuation">(</span><span class="token string">&#39;&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token comment">// 按码点反转，emoji 安全</span>

</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>追问与易错点</strong>：</p><ul><li>追问：<code>s.trim().split(/\\s+/)</code> 做单词反转的缺陷？答：把多个空格压成一个并去掉首尾空格，若题目要求&quot;保持原有空格&quot;就错了，此时要用双指针原地反转。</li><li>追问：最长公共前缀字符串很长时怎么优化？答：先按长度排序只比较最短串的长度上限，或用二分答案 + 校验公共前缀把每次比较规模压下来。</li><li>陷阱：回文判断忘记跳过标点，<code>&quot;A man, a plan, a canal: Panama&quot;</code> 会被判成非回文；最长公共前缀漏判 <code>i &gt;= strs[j].length</code> 会依赖&quot;读到 undefined&quot;的巧合。</li></ul><h3 id="q10-无重复字符的最长子串-滑动窗口怎么写" tabindex="-1"><a class="header-anchor" href="#q10-无重复字符的最长子串-滑动窗口怎么写" aria-hidden="true">#</a> Q10 无重复字符的最长子串，滑动窗口怎么写？</h3><p><strong>考察点</strong>：考滑动窗口（Sliding Window）模板与&quot;窗口何时收缩&quot;的判断；能说清为什么是 O(n) 而非 O(n²) 才算过关。</p><p><strong>参考答案</strong>：</p><blockquote><p><strong>一句话结论</strong>：用左右指针维护一个&quot;无重复字符&quot;的窗口，右指针扩张、遇到重复就把左指针跳到&quot;上次出现位置 + 1&quot;；每个字符最多被左右指针各访问一次，所以时间 O(n)、空间 O(字符集大小)。</p></blockquote><ol><li>窗口定义：<code>[left, right]</code> 内始终没有重复字符，<code>right</code> 每次右移一步尝试扩张。</li><li>收缩规则：若 <code>s[right]</code> 已在窗口内出现过，就更新 <code>left = max(left, 上次出现下标 + 1)</code>；取 <code>max</code> 是为了防止 <code>left</code> 回退。</li><li>用 <code>Map</code> 记录&quot;字符 → 最近一次出现的下标&quot;，查重与定位一步到位，比&quot;发现重复后逐个左指针后移&quot;更简洁（后者是 while 收缩版，复杂度同样是 O(n)）。</li><li><strong>复杂度与边界</strong>：<code>right</code> 单向走到 n-1、<code>left</code> 只增不减，每个字符进出窗口各一次，总操作 O(n)，空间 O(min(n, 字符集))。边界：空串返回 0；全同字符串返回 1；<code>left</code> 更新前要先算当前长度 <code>right - left + 1</code>；必须判断&quot;上次出现的位置是否在当前窗口内&quot;。</li><li>同族题：最小覆盖子串、至多含 K 个不同字符的最长子串、找所有字母异位词——都是同一套&quot;右扩左缩&quot;模板，差别只在窗口合法性的判定条件。</li></ol><div class="language-javascript line-numbers-mode" data-ext="js"><pre class="language-javascript"><code><span class="token keyword">function</span> <span class="token function">lengthOfLongestSubstring</span><span class="token punctuation">(</span><span class="token parameter">s</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
  <span class="token keyword">const</span> last <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token class-name">Map</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>        <span class="token comment">// 字符 -&gt; 最近出现的下标</span>
  <span class="token keyword">let</span> left <span class="token operator">=</span> <span class="token number">0</span><span class="token punctuation">,</span> max <span class="token operator">=</span> <span class="token number">0</span><span class="token punctuation">;</span>
  <span class="token keyword">for</span> <span class="token punctuation">(</span><span class="token keyword">let</span> right <span class="token operator">=</span> <span class="token number">0</span><span class="token punctuation">;</span> right <span class="token operator">&lt;</span> s<span class="token punctuation">.</span>length<span class="token punctuation">;</span> right<span class="token operator">++</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token keyword">const</span> ch <span class="token operator">=</span> s<span class="token punctuation">[</span>right<span class="token punctuation">]</span><span class="token punctuation">;</span>
    <span class="token keyword">if</span> <span class="token punctuation">(</span>last<span class="token punctuation">.</span><span class="token function">has</span><span class="token punctuation">(</span>ch<span class="token punctuation">)</span> <span class="token operator">&amp;&amp;</span> last<span class="token punctuation">.</span><span class="token function">get</span><span class="token punctuation">(</span>ch<span class="token punctuation">)</span> <span class="token operator">&gt;=</span> left<span class="token punctuation">)</span> <span class="token punctuation">{</span>
      left <span class="token operator">=</span> last<span class="token punctuation">.</span><span class="token function">get</span><span class="token punctuation">(</span>ch<span class="token punctuation">)</span> <span class="token operator">+</span> <span class="token number">1</span><span class="token punctuation">;</span>   <span class="token comment">// 只收缩到重复字符的下一位</span>
    <span class="token punctuation">}</span>
    last<span class="token punctuation">.</span><span class="token function">set</span><span class="token punctuation">(</span>ch<span class="token punctuation">,</span> right<span class="token punctuation">)</span><span class="token punctuation">;</span>
    max <span class="token operator">=</span> Math<span class="token punctuation">.</span><span class="token function">max</span><span class="token punctuation">(</span>max<span class="token punctuation">,</span> right <span class="token operator">-</span> left <span class="token operator">+</span> <span class="token number">1</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
  <span class="token punctuation">}</span>
  <span class="token keyword">return</span> max<span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>追问与易错点</strong>：</p><ul><li>追问：为什么必须判断 <code>last.get(ch) &gt;= left</code>？答：如果上次出现在窗口左侧之外（已被移出窗口），就不该收缩，否则 <code>left</code> 会倒退导致结果偏小。</li><li>追问：字符集只有 ASCII 时怎么优化？答：用长度 128 的数组代替 <code>Map</code>，访问更快且省去哈希开销。</li><li>陷阱：写成&quot;发现重复就 <code>left++</code> 并重新扫描窗口&quot;，虽然结果对，但会退化成 O(n²)，这正是面试官想区分的实现。</li></ul><h3 id="q11-有序数组去重、盛最多水的容器、三数之和-双指针为什么快" tabindex="-1"><a class="header-anchor" href="#q11-有序数组去重、盛最多水的容器、三数之和-双指针为什么快" aria-hidden="true">#</a> Q11 有序数组去重、盛最多水的容器、三数之和，双指针为什么快？</h3><p><strong>考察点</strong>：考双指针的核心前提——&quot;有序性带来的剪枝&quot;，三题串讲能体现模式迁移能力。</p><p><strong>参考答案</strong>：</p><blockquote><p><strong>一句话结论</strong>：双指针之所以能从 O(n²) 降到 O(n) 或 O(n log n)，是因为利用单调性&quot;一次移动就能排除一整批不可能解&quot;；它要求数组有序，或者问题本身具备可收缩的最优子结构。</p></blockquote><ol><li>有序数组原地去重：慢指针 <code>slow</code> 指向已去重区间末尾，快指针 <code>fast</code> 扫描；<code>nums[fast] !== nums[slow]</code> 时才 <code>slow++</code> 并覆盖。时间 O(n)、空间 O(1)，是&quot;读写指针&quot;的经典形态。</li><li>盛最多水的容器：左右指针从两端向中间收，每次移动<strong>较短</strong>的那一侧。原因：容量由短板决定，移动长板高度只会更矮或持平，宽度却一定变小，所以不可能产生更优解。</li><li>三数之和：先排序 O(n log n)，外层固定一个数 <code>nums[i]</code>，内层对右侧区间做左右双指针求两数之和为 <code>-nums[i]</code>。总体 O(n²)，比三重循环的 O(n³) 好一个数量级。</li><li>三数之和的细节：排序后要跳过重复的 <code>nums[i]</code>；找到一组解后左右指针都要跳过重复元素，否则结果集会出现重复三元组。</li><li><strong>复杂度与边界</strong>：去重 O(n)/O(1)、盛水 O(n)/O(1)、三数之和 O(n²)/O(1)（不计排序空间）。边界：空数组与长度不足的数组要直接返回；去重要覆盖最后一个元素；三数之和在 <code>nums[i] &gt; 0</code> 时可直接结束，且不存在 O(n log n) 的通用解法（3SUM 猜想）。</li><li>剪枝：<code>nums[i] + nums[i+1] + nums[i+2] &gt; 0</code> 时也可提前结束，减少无谓循环。</li></ol><div class="language-javascript line-numbers-mode" data-ext="js"><pre class="language-javascript"><code><span class="token comment">// 三数之和：排序 + 固定一个数 + 左右双指针，O(n²)</span>
<span class="token keyword">function</span> <span class="token function">threeSum</span><span class="token punctuation">(</span><span class="token parameter">nums</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
  nums<span class="token punctuation">.</span><span class="token function">sort</span><span class="token punctuation">(</span><span class="token punctuation">(</span><span class="token parameter">a<span class="token punctuation">,</span> b</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> a <span class="token operator">-</span> b<span class="token punctuation">)</span><span class="token punctuation">;</span>
  <span class="token keyword">const</span> res <span class="token operator">=</span> <span class="token punctuation">[</span><span class="token punctuation">]</span><span class="token punctuation">;</span>
  <span class="token keyword">for</span> <span class="token punctuation">(</span><span class="token keyword">let</span> i <span class="token operator">=</span> <span class="token number">0</span><span class="token punctuation">;</span> i <span class="token operator">&lt;</span> nums<span class="token punctuation">.</span>length <span class="token operator">-</span> <span class="token number">2</span><span class="token punctuation">;</span> i<span class="token operator">++</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token keyword">if</span> <span class="token punctuation">(</span>nums<span class="token punctuation">[</span>i<span class="token punctuation">]</span> <span class="token operator">&gt;</span> <span class="token number">0</span><span class="token punctuation">)</span> <span class="token keyword">break</span><span class="token punctuation">;</span>                         <span class="token comment">// 剪枝：最小值为正</span>
    <span class="token keyword">if</span> <span class="token punctuation">(</span>i <span class="token operator">&gt;</span> <span class="token number">0</span> <span class="token operator">&amp;&amp;</span> nums<span class="token punctuation">[</span>i<span class="token punctuation">]</span> <span class="token operator">===</span> nums<span class="token punctuation">[</span>i <span class="token operator">-</span> <span class="token number">1</span><span class="token punctuation">]</span><span class="token punctuation">)</span> <span class="token keyword">continue</span><span class="token punctuation">;</span> <span class="token comment">// 跳过重复的固定值</span>
    <span class="token keyword">let</span> l <span class="token operator">=</span> i <span class="token operator">+</span> <span class="token number">1</span><span class="token punctuation">,</span> r <span class="token operator">=</span> nums<span class="token punctuation">.</span>length <span class="token operator">-</span> <span class="token number">1</span><span class="token punctuation">;</span>
    <span class="token keyword">while</span> <span class="token punctuation">(</span>l <span class="token operator">&lt;</span> r<span class="token punctuation">)</span> <span class="token punctuation">{</span>
      <span class="token keyword">const</span> sum <span class="token operator">=</span> nums<span class="token punctuation">[</span>i<span class="token punctuation">]</span> <span class="token operator">+</span> nums<span class="token punctuation">[</span>l<span class="token punctuation">]</span> <span class="token operator">+</span> nums<span class="token punctuation">[</span>r<span class="token punctuation">]</span><span class="token punctuation">;</span>
      <span class="token keyword">if</span> <span class="token punctuation">(</span>sum <span class="token operator">===</span> <span class="token number">0</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
        res<span class="token punctuation">.</span><span class="token function">push</span><span class="token punctuation">(</span><span class="token punctuation">[</span>nums<span class="token punctuation">[</span>i<span class="token punctuation">]</span><span class="token punctuation">,</span> nums<span class="token punctuation">[</span>l<span class="token punctuation">]</span><span class="token punctuation">,</span> nums<span class="token punctuation">[</span>r<span class="token punctuation">]</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
        <span class="token keyword">while</span> <span class="token punctuation">(</span>l <span class="token operator">&lt;</span> r <span class="token operator">&amp;&amp;</span> nums<span class="token punctuation">[</span>l<span class="token punctuation">]</span> <span class="token operator">===</span> nums<span class="token punctuation">[</span>l <span class="token operator">+</span> <span class="token number">1</span><span class="token punctuation">]</span><span class="token punctuation">)</span> l<span class="token operator">++</span><span class="token punctuation">;</span> <span class="token comment">// 跳过重复</span>
        <span class="token keyword">while</span> <span class="token punctuation">(</span>l <span class="token operator">&lt;</span> r <span class="token operator">&amp;&amp;</span> nums<span class="token punctuation">[</span>r<span class="token punctuation">]</span> <span class="token operator">===</span> nums<span class="token punctuation">[</span>r <span class="token operator">-</span> <span class="token number">1</span><span class="token punctuation">]</span><span class="token punctuation">)</span> r<span class="token operator">--</span><span class="token punctuation">;</span>
        l<span class="token operator">++</span><span class="token punctuation">;</span> r<span class="token operator">--</span><span class="token punctuation">;</span>
      <span class="token punctuation">}</span> <span class="token keyword">else</span> <span class="token keyword">if</span> <span class="token punctuation">(</span>sum <span class="token operator">&lt;</span> <span class="token number">0</span><span class="token punctuation">)</span> l<span class="token operator">++</span><span class="token punctuation">;</span> <span class="token keyword">else</span> r<span class="token operator">--</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>
  <span class="token punctuation">}</span>
  <span class="token keyword">return</span> res<span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>追问与易错点</strong>：</p><ul><li>追问：盛水容器为什么不能移动长板？答：移动长板后新容量 = min(新短板, 原短板或更矮的值) × 更小的宽度，上界严格不升，因此不会产生更优解，可以安全排除。</li><li>追问：双指针和滑动窗口是什么关系？答：滑动窗口是双指针的一种特例，两个指针同向移动维护一个区间；&quot;相向双指针&quot;依赖有序性做剪枝，两者适用条件不同。</li><li>陷阱：三数之和忘记跳过重复元素，结果里会有多组重复三元组；有序数组去重时漏掉把最后一个元素写回结果数组。</li></ul><h3 id="q12-二分查找的标准写法是什么-旋转数组、找峰值怎么改" tabindex="-1"><a class="header-anchor" href="#q12-二分查找的标准写法是什么-旋转数组、找峰值怎么改" aria-hidden="true">#</a> Q12 二分查找的标准写法是什么？旋转数组、找峰值怎么改？</h3><p><strong>考察点</strong>：考区间定义的统一性（左闭右闭 vs 左闭右开）、<code>mid</code> 溢出细节，以及&quot;局部有序即可二分&quot;的迁移能力。</p><p><strong>参考答案</strong>：</p><blockquote><p><strong>一句话结论</strong>：写二分的唯一诀窍是<strong>先定死区间语义</strong>，全程保持同一套不变量：推荐 <code>[left, right]</code> 左闭右闭，循环条件 <code>left &lt;= right</code>，收缩时 <code>left = mid + 1</code> / <code>right = mid - 1</code>，这样一定不会死循环；二分不要求全局有序，只要每次能排除一半。</p></blockquote><ol><li>左闭右闭模板：<code>while (left &lt;= right)</code>；命中返回 <code>mid</code>；<code>nums[mid] &lt; target</code> 则 <code>left = mid + 1</code>；否则 <code>right = mid - 1</code>。区间每次至少缩小 1，必然收敛。</li><li>左闭右开模板：<code>right = nums.length</code>，<code>while (left &lt; right)</code>，<code>right = mid</code>。两套都正确，混用才是 bug 之源——例如左闭右开却写 <code>right = mid - 1</code> 会漏掉元素。</li><li><code>mid</code> 计算写 <code>left + ((right - left) &gt;&gt; 1)</code>：<code>(left + right) / 2</code> 在超大数组（接近 2³¹）时可能整数溢出，JS 用浮点不会有此问题，但这是 Java/C++ 面试的标准答案。</li><li>旋转数组：判断 <code>[left, mid]</code> 是否有序（<code>nums[left] &lt;= nums[mid]</code>，用 <code>&lt;=</code> 而非 <code>&lt;</code>）。左半有序就看 <code>target</code> 是否落在 <code>[nums[left], nums[mid])</code>，右半有序就看是否落在 <code>(nums[mid], nums[right]]</code>，据此收缩。</li><li>找峰值（<code>nums[i] &gt; nums[i+1]</code> 为峰值，两端视为负无穷）：比较 <code>nums[mid]</code> 与 <code>nums[mid+1]</code>，上升就 <code>left = mid + 1</code>，下降就 <code>right = mid</code>，循环结束时 <code>left</code> 即峰值下标。直观解释是&quot;只要处于上坡，右侧必然存在峰值&quot;。</li><li><strong>复杂度与边界</strong>：标准二分与找峰值时间 O(log n)、空间 O(1)；数组必须有序且支持随机访问（链表不能二分）。边界：旋转数组<strong>有重复元素</strong>时（如 <code>[1,1,3,1]</code>）<code>nums[left] === nums[mid]</code> 无法判断哪边有序，只能 <code>left++</code> 逐格收缩，最坏退化成 O(n)；找峰值用 <code>left &lt; right</code> 避免访问越界的 <code>nums[mid+1]</code>。</li></ol><div class="language-javascript line-numbers-mode" data-ext="js"><pre class="language-javascript"><code><span class="token keyword">function</span> <span class="token function">binarySearch</span><span class="token punctuation">(</span><span class="token parameter">nums<span class="token punctuation">,</span> target</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
  <span class="token keyword">let</span> left <span class="token operator">=</span> <span class="token number">0</span><span class="token punctuation">,</span> right <span class="token operator">=</span> nums<span class="token punctuation">.</span>length <span class="token operator">-</span> <span class="token number">1</span><span class="token punctuation">;</span>   <span class="token comment">// 左闭右闭 [left, right]</span>
  <span class="token keyword">while</span> <span class="token punctuation">(</span>left <span class="token operator">&lt;=</span> right<span class="token punctuation">)</span> <span class="token punctuation">{</span>                  <span class="token comment">// 区间为空时退出</span>
    <span class="token keyword">const</span> mid <span class="token operator">=</span> left <span class="token operator">+</span> <span class="token punctuation">(</span><span class="token punctuation">(</span>right <span class="token operator">-</span> left<span class="token punctuation">)</span> <span class="token operator">&gt;&gt;</span> <span class="token number">1</span><span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token comment">// 防溢出写法</span>
    <span class="token keyword">if</span> <span class="token punctuation">(</span>nums<span class="token punctuation">[</span>mid<span class="token punctuation">]</span> <span class="token operator">===</span> target<span class="token punctuation">)</span> <span class="token keyword">return</span> mid<span class="token punctuation">;</span>
    <span class="token keyword">if</span> <span class="token punctuation">(</span>nums<span class="token punctuation">[</span>mid<span class="token punctuation">]</span> <span class="token operator">&lt;</span> target<span class="token punctuation">)</span> left <span class="token operator">=</span> mid <span class="token operator">+</span> <span class="token number">1</span><span class="token punctuation">;</span>   <span class="token comment">// 收缩左边界</span>
    <span class="token keyword">else</span> right <span class="token operator">=</span> mid <span class="token operator">-</span> <span class="token number">1</span><span class="token punctuation">;</span>                     <span class="token comment">// 收缩右边界</span>
  <span class="token punctuation">}</span>
  <span class="token keyword">return</span> <span class="token operator">-</span><span class="token number">1</span><span class="token punctuation">;</span>                               <span class="token comment">// 未找到</span>
<span class="token punctuation">}</span>

<span class="token keyword">function</span> <span class="token function">findPeakElement</span><span class="token punctuation">(</span><span class="token parameter">nums</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
  <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token operator">!</span>nums<span class="token punctuation">.</span>length<span class="token punctuation">)</span> <span class="token keyword">return</span> <span class="token operator">-</span><span class="token number">1</span><span class="token punctuation">;</span>                      <span class="token comment">// 空数组无峰值</span>
  <span class="token keyword">let</span> left <span class="token operator">=</span> <span class="token number">0</span><span class="token punctuation">,</span> right <span class="token operator">=</span> nums<span class="token punctuation">.</span>length <span class="token operator">-</span> <span class="token number">1</span><span class="token punctuation">;</span>
  <span class="token keyword">while</span> <span class="token punctuation">(</span>left <span class="token operator">&lt;</span> right<span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token keyword">const</span> mid <span class="token operator">=</span> left <span class="token operator">+</span> <span class="token punctuation">(</span><span class="token punctuation">(</span>right <span class="token operator">-</span> left<span class="token punctuation">)</span> <span class="token operator">&gt;&gt;</span> <span class="token number">1</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token keyword">if</span> <span class="token punctuation">(</span>nums<span class="token punctuation">[</span>mid<span class="token punctuation">]</span> <span class="token operator">&gt;</span> nums<span class="token punctuation">[</span>mid <span class="token operator">+</span> <span class="token number">1</span><span class="token punctuation">]</span><span class="token punctuation">)</span> right <span class="token operator">=</span> mid<span class="token punctuation">;</span>     <span class="token comment">// 下坡，峰值在左含 mid</span>
    <span class="token keyword">else</span> left <span class="token operator">=</span> mid <span class="token operator">+</span> <span class="token number">1</span><span class="token punctuation">;</span>                            <span class="token comment">// 上坡，峰值在右</span>
  <span class="token punctuation">}</span>
  <span class="token keyword">return</span> left<span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>追问与易错点</strong>：</p><ul><li>追问：怎么找&quot;第一个大于等于 target 的位置&quot;？答：命中时不要返回，令 <code>right = mid</code> 继续向左逼；循环结束 <code>left</code> 即为答案（可能等于 <code>nums.length</code> 表示所有元素都小）。</li><li>追问：二分为什么容易死循环？答：<code>mid</code> 向下取整时若收缩写成 <code>left = mid</code>（而不是 <code>mid + 1</code>），区间长度不变就会死循环。记住&quot;左边界跳一格、右边界跳一格&quot;。</li><li>陷阱：<code>while (left &lt; right)</code> 配 <code>[left, right]</code> 闭区间会漏掉最后剩下的元素；旋转数组判断有序时用 <code>&lt;</code> 而非 <code>&lt;=</code>，区间只剩两个相等元素时方向判反。</li></ul><h3 id="q13-递归、回溯与剪枝-全排列、子集、组合总和怎么统一理解" tabindex="-1"><a class="header-anchor" href="#q13-递归、回溯与剪枝-全排列、子集、组合总和怎么统一理解" aria-hidden="true">#</a> Q13 递归、回溯与剪枝：全排列、子集、组合总和怎么统一理解？</h3><p><strong>考察点</strong>：考回溯模板（选择 → 递归 → 撤销）的迁移能力，以及&quot;什么时候需要 <code>used</code> 数组、什么时候需要 <code>start</code> 下标&quot;。</p><p><strong>参考答案</strong>：</p><blockquote><p><strong>一句话结论</strong>：回溯 = 递归 + 撤销选择，本质是在决策树上做深度优先搜索；<strong>排列</strong>问题用一个 <code>used</code> 数组标记已选元素，<strong>组合/子集</strong>问题用 <code>start</code> 下标保证不重复选前面的元素。</p></blockquote><ol><li>通用模板四件套：① 判断是否到达决策树底部（收集结果）；② 遍历当前可选项；③ 做选择、递归、撤销选择；④ 必要时剪枝提前返回。</li><li>全排列：每层从所有未使用的元素里挑一个，用 <code>used[i]</code> 标记，撤销时 <code>used[i] = false</code> 并 <code>path.pop()</code>。含重复元素时要先排序并跳过&quot;同层重复&quot;的分支。</li><li>子集：把决策树上的<strong>每个节点</strong>都收进结果（不只是叶子），用 <code>start</code> 保证后续只取下标更大的元素。</li><li>组合总和：可重复取同一元素时递归传 <code>i</code>（不 +1），不可重复时传 <code>i + 1</code>；配合&quot;排序 + 当前值大于剩余目标就 break&quot;剪枝。</li><li><strong>复杂度与边界</strong>：全排列时间 O(n·n!)，子集 O(n·2ⁿ)，组合总和介于两者之间，递归栈空间 O(n)。边界：空数组时全排列返回 <code>[[]]</code>（一个空排列）、子集返回 <code>[[]]</code>；收集结果必须拷贝 <code>[...path]</code>；忘记撤销选择会导致结果集不完整。</li><li>递归转迭代：任何递归都能用显式栈改写以避免爆栈；但回溯类题目用栈改写可读性大幅下降，所以实际做法是保留递归 + 控制深度或剪枝降低深度。</li></ol><div class="language-javascript line-numbers-mode" data-ext="js"><pre class="language-javascript"><code><span class="token comment">// 全排列：used 标记 + 回溯撤销（做选择 → 递归 → 撤销）</span>
<span class="token keyword">function</span> <span class="token function">permute</span><span class="token punctuation">(</span><span class="token parameter">nums</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
  <span class="token keyword">const</span> res <span class="token operator">=</span> <span class="token punctuation">[</span><span class="token punctuation">]</span><span class="token punctuation">,</span> path <span class="token operator">=</span> <span class="token punctuation">[</span><span class="token punctuation">]</span><span class="token punctuation">,</span> used <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token class-name">Array</span><span class="token punctuation">(</span>nums<span class="token punctuation">.</span>length<span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">fill</span><span class="token punctuation">(</span><span class="token boolean">false</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
  <span class="token keyword">const</span> <span class="token function-variable function">dfs</span> <span class="token operator">=</span> <span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token punctuation">{</span>
    <span class="token keyword">if</span> <span class="token punctuation">(</span>path<span class="token punctuation">.</span>length <span class="token operator">===</span> nums<span class="token punctuation">.</span>length<span class="token punctuation">)</span> <span class="token keyword">return</span> res<span class="token punctuation">.</span><span class="token function">push</span><span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token operator">...</span>path<span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token comment">// 收集副本</span>
    <span class="token keyword">for</span> <span class="token punctuation">(</span><span class="token keyword">let</span> i <span class="token operator">=</span> <span class="token number">0</span><span class="token punctuation">;</span> i <span class="token operator">&lt;</span> nums<span class="token punctuation">.</span>length<span class="token punctuation">;</span> i<span class="token operator">++</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
      <span class="token keyword">if</span> <span class="token punctuation">(</span>used<span class="token punctuation">[</span>i<span class="token punctuation">]</span><span class="token punctuation">)</span> <span class="token keyword">continue</span><span class="token punctuation">;</span>
      used<span class="token punctuation">[</span>i<span class="token punctuation">]</span> <span class="token operator">=</span> <span class="token boolean">true</span><span class="token punctuation">;</span> path<span class="token punctuation">.</span><span class="token function">push</span><span class="token punctuation">(</span>nums<span class="token punctuation">[</span>i<span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>   <span class="token comment">// 做选择</span>
      <span class="token function">dfs</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
      path<span class="token punctuation">.</span><span class="token function">pop</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span> used<span class="token punctuation">[</span>i<span class="token punctuation">]</span> <span class="token operator">=</span> <span class="token boolean">false</span><span class="token punctuation">;</span>          <span class="token comment">// 撤销选择</span>
    <span class="token punctuation">}</span>
  <span class="token punctuation">}</span><span class="token punctuation">;</span>
  <span class="token function">dfs</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
  <span class="token keyword">return</span> res<span class="token punctuation">;</span>
<span class="token punctuation">}</span>
<span class="token comment">// 子集：start 下标保证不回头，决策树每个节点都是解</span>
<span class="token keyword">function</span> <span class="token function">subsets</span><span class="token punctuation">(</span><span class="token parameter">nums</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
  <span class="token keyword">const</span> res <span class="token operator">=</span> <span class="token punctuation">[</span><span class="token punctuation">]</span><span class="token punctuation">,</span> path <span class="token operator">=</span> <span class="token punctuation">[</span><span class="token punctuation">]</span><span class="token punctuation">;</span>
  <span class="token keyword">const</span> <span class="token function-variable function">dfs</span> <span class="token operator">=</span> <span class="token punctuation">(</span><span class="token parameter">start</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token punctuation">{</span>
    res<span class="token punctuation">.</span><span class="token function">push</span><span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token operator">...</span>path<span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token keyword">for</span> <span class="token punctuation">(</span><span class="token keyword">let</span> i <span class="token operator">=</span> start<span class="token punctuation">;</span> i <span class="token operator">&lt;</span> nums<span class="token punctuation">.</span>length<span class="token punctuation">;</span> i<span class="token operator">++</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
      path<span class="token punctuation">.</span><span class="token function">push</span><span class="token punctuation">(</span>nums<span class="token punctuation">[</span>i<span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token function">dfs</span><span class="token punctuation">(</span>i <span class="token operator">+</span> <span class="token number">1</span><span class="token punctuation">)</span><span class="token punctuation">;</span> path<span class="token punctuation">.</span><span class="token function">pop</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>
  <span class="token punctuation">}</span><span class="token punctuation">;</span>
  <span class="token function">dfs</span><span class="token punctuation">(</span><span class="token number">0</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
  <span class="token keyword">return</span> res<span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>追问与易错点</strong>：</p><ul><li>追问：为什么收集结果要写 <code>[...path]</code> 而不是 <code>res.push(path)</code>？答：<code>path</code> 是同一个数组引用，后续回溯会改它，最后所有结果都会变成同一个（通常是空数组）。</li><li>追问：括号生成怎么套模板？答：左括号数量 <code>&lt; n</code> 就能加左括号，右括号数量 <code>&lt; 左括号数量</code> 才能加右括号，这两个条件天然完成了合法性剪枝，不需要额外校验。</li><li>陷阱：回溯时忘记撤销 <code>used[i] = false</code> 或 <code>path.pop()</code>，会导致后续分支可选项越来越少，结果集不完整。</li></ul><h3 id="q14-二叉树的三种遍历-递归和非递归都要会吗" tabindex="-1"><a class="header-anchor" href="#q14-二叉树的三种遍历-递归和非递归都要会吗" aria-hidden="true">#</a> Q14 二叉树的三种遍历，递归和非递归都要会吗？</h3><p><strong>考察点</strong>：考树遍历的背诵级基本功，以及非递归实现里&quot;访问顺序与入栈顺序&quot;的对应关系；能默写前中序迭代版才算过关。</p><p><strong>参考答案</strong>：</p><blockquote><p><strong>一句话结论</strong>：递归版三种遍历只是&quot;访问根节点的时机不同&quot;（前序在递归左右前、中序在中间、后序在最后），时间 O(n)、空间 O(h)；非递归版要用显式栈，前序最简单（先压右后压左），中序要&quot;一路向左压栈&quot;，后序可用&quot;前序变体 + 结果反转&quot;实现。</p></blockquote><ol><li>递归版：只需交换三行的顺序——前序 <code>visit → left → right</code>，中序 <code>left → visit → right</code>，后序 <code>left → right → visit</code>。</li><li>前序迭代：栈里压节点，弹出即访问，然后<strong>先压右孩子、再压左孩子</strong>（栈是后进先出，压的次序要反过来），这样弹出顺序才是左先右后。</li><li>中序迭代：从根一路向左入栈，走到 <code>null</code> 就弹出栈顶访问，然后转向它的右孩子。这保证了&quot;左子树全部处理完才访问根&quot;。</li><li>后序迭代：把前序的&quot;根左右&quot;改成&quot;根右左&quot;（压栈时先压左再压右），最后把结果数组反转即为&quot;左右根&quot;。这是最省事的写法。</li><li><strong>复杂度与边界</strong>：时间 O(n)，每个节点进出栈各一次；空间 O(h)，h 是树高。边界：空树返回空数组；递归版最坏（链状树）h = n，会随深度增加栈帧甚至爆栈，非递归版用堆上的数组，容量不受引擎栈限制。</li><li>Morris 遍历：利用叶子节点的空指针做线索，可做到 O(1) 空间、O(n) 时间，代价是会临时修改树结构，属于加分项而非必答。</li></ol><div class="language-javascript line-numbers-mode" data-ext="js"><pre class="language-javascript"><code><span class="token comment">// 前序 根-&gt;左-&gt;右（迭代：先压右再压左，弹出即访问）</span>
<span class="token keyword">function</span> <span class="token function">preorder</span><span class="token punctuation">(</span><span class="token parameter">root</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
  <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token operator">!</span>root<span class="token punctuation">)</span> <span class="token keyword">return</span> <span class="token punctuation">[</span><span class="token punctuation">]</span><span class="token punctuation">;</span>
  <span class="token keyword">const</span> res <span class="token operator">=</span> <span class="token punctuation">[</span><span class="token punctuation">]</span><span class="token punctuation">,</span> stack <span class="token operator">=</span> <span class="token punctuation">[</span>root<span class="token punctuation">]</span><span class="token punctuation">;</span>
  <span class="token keyword">while</span> <span class="token punctuation">(</span>stack<span class="token punctuation">.</span>length<span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token keyword">const</span> node <span class="token operator">=</span> stack<span class="token punctuation">.</span><span class="token function">pop</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    res<span class="token punctuation">.</span><span class="token function">push</span><span class="token punctuation">(</span>node<span class="token punctuation">.</span>val<span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token keyword">if</span> <span class="token punctuation">(</span>node<span class="token punctuation">.</span>right<span class="token punctuation">)</span> stack<span class="token punctuation">.</span><span class="token function">push</span><span class="token punctuation">(</span>node<span class="token punctuation">.</span>right<span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token keyword">if</span> <span class="token punctuation">(</span>node<span class="token punctuation">.</span>left<span class="token punctuation">)</span> stack<span class="token punctuation">.</span><span class="token function">push</span><span class="token punctuation">(</span>node<span class="token punctuation">.</span>left<span class="token punctuation">)</span><span class="token punctuation">;</span>
  <span class="token punctuation">}</span>
  <span class="token keyword">return</span> res<span class="token punctuation">;</span>
<span class="token punctuation">}</span>
<span class="token comment">// 中序 左-&gt;根-&gt;右（迭代：一路向左压栈，弹出后转向右孩子）</span>
<span class="token keyword">function</span> <span class="token function">inorder</span><span class="token punctuation">(</span><span class="token parameter">root</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
  <span class="token keyword">const</span> res <span class="token operator">=</span> <span class="token punctuation">[</span><span class="token punctuation">]</span><span class="token punctuation">,</span> stack <span class="token operator">=</span> <span class="token punctuation">[</span><span class="token punctuation">]</span><span class="token punctuation">;</span>
  <span class="token keyword">let</span> cur <span class="token operator">=</span> root<span class="token punctuation">;</span>
  <span class="token keyword">while</span> <span class="token punctuation">(</span>cur <span class="token operator">||</span> stack<span class="token punctuation">.</span>length<span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token keyword">while</span> <span class="token punctuation">(</span>cur<span class="token punctuation">)</span> <span class="token punctuation">{</span> stack<span class="token punctuation">.</span><span class="token function">push</span><span class="token punctuation">(</span>cur<span class="token punctuation">)</span><span class="token punctuation">;</span> cur <span class="token operator">=</span> cur<span class="token punctuation">.</span>left<span class="token punctuation">;</span> <span class="token punctuation">}</span> <span class="token comment">// 一路向左</span>
    cur <span class="token operator">=</span> stack<span class="token punctuation">.</span><span class="token function">pop</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    res<span class="token punctuation">.</span><span class="token function">push</span><span class="token punctuation">(</span>cur<span class="token punctuation">.</span>val<span class="token punctuation">)</span><span class="token punctuation">;</span>                  <span class="token comment">// 左子树处理完才访问根</span>
    cur <span class="token operator">=</span> cur<span class="token punctuation">.</span>right<span class="token punctuation">;</span>
  <span class="token punctuation">}</span>
  <span class="token keyword">return</span> res<span class="token punctuation">;</span>
<span class="token punctuation">}</span>
<span class="token comment">// 后序迭代：按&quot;根右左&quot;遍历后反转结果，即为&quot;左右根&quot;</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>追问与易错点</strong>：</p><ul><li>追问：中序 + 前序能唯一确定一棵二叉树吗？答：能（前提是节点值互不相同）。前序定根，中序划分左右子树，递归即可重建；但前序 + 后序<strong>不能</strong>唯一确定，因为分不清只有一个孩子时它是左还是右。</li><li>追问：怎么判断一棵树是否是二叉搜索树？答：中序遍历结果严格递增即成立；等价做法是递归时携带上下界区间，每个节点都要落在自己的区间内（只比较父子节点是错的）。</li><li>陷阱：前序迭代时先压左再压右，结果会变成&quot;根右左&quot;；后序迭代忘记反转结果数组。</li></ul><h3 id="q15-层序遍历、最大深度、镜像、对称-树题怎么归类" tabindex="-1"><a class="header-anchor" href="#q15-层序遍历、最大深度、镜像、对称-树题怎么归类" aria-hidden="true">#</a> Q15 层序遍历、最大深度、镜像、对称，树题怎么归类？</h3><p><strong>考察点</strong>：考树题的两大范式——&quot;BFS 逐层处理&quot;与&quot;DFS 递归下推/上收&quot;，能按题型选范式并写对对称判断才算过关。</p><p><strong>参考答案</strong>：</p><blockquote><p><strong>一句话结论</strong>：树题只有两个骨架——需要按层处理用 BFS（队列 + 记录每层长度），需要子树信息汇总用 DFS（后序位置&quot;上收&quot;子树返回值）；镜像是对称的特例，对称必须用双指针<strong>交叉</strong>比较。</p></blockquote><ol><li>层序遍历（BFS）：队列初始放根，每轮先记 <code>size = queue.length</code>，一次性弹出这一层的所有节点并把子节点入队，就能把&quot;层&quot;切分出来。空间 O(w)（w 为最大层宽）。</li><li>队列实现细节：用头指针 <code>head++</code> 递增读取代替 <code>queue.shift()</code>——<code>shift</code> 是 O(n) 的搬移操作，会让整体退化成 O(n²)。</li><li>最大深度：DFS 后序 <code>1 + max(depth(left), depth(right))</code>；也可以 BFS 边遍历边计数层数。前者代码更短，后者在极深树上不担心递归栈。</li><li>镜像（翻转二叉树）：递归交换左右孩子再递归翻转；BFS 也可以，每个节点把左右孩子换一下即可。</li><li>判断对称（Symmetric）：这不是比较节点自身，而是<strong>双指针同步比较</strong>——判断 <code>left.left</code> 与 <code>right.right</code>、<code>left.right</code> 与 <code>right.left</code> 是否相等，两个方向都要对上。只比较同层对应位置会漏判。</li><li><strong>复杂度与边界</strong>：四题时间都是 O(n)，层序空间 O(w)、递归类空间 O(h)。边界：空树返回 <code>[]</code>/<code>0</code>/<code>true</code>；对称判断传入的是 <code>root.left</code> 与 <code>root.right</code> 两个子树，而不是 <code>root</code> 自身。</li></ol><div class="language-javascript line-numbers-mode" data-ext="js"><pre class="language-javascript"><code><span class="token comment">// 层序遍历（BFS 逐层：先固定本层长度再切分）</span>
<span class="token keyword">function</span> <span class="token function">levelOrder</span><span class="token punctuation">(</span><span class="token parameter">root</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
  <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token operator">!</span>root<span class="token punctuation">)</span> <span class="token keyword">return</span> <span class="token punctuation">[</span><span class="token punctuation">]</span><span class="token punctuation">;</span>
  <span class="token keyword">const</span> res <span class="token operator">=</span> <span class="token punctuation">[</span><span class="token punctuation">]</span><span class="token punctuation">,</span> queue <span class="token operator">=</span> <span class="token punctuation">[</span>root<span class="token punctuation">]</span><span class="token punctuation">;</span>
  <span class="token keyword">let</span> head <span class="token operator">=</span> <span class="token number">0</span><span class="token punctuation">;</span>                             <span class="token comment">// 头指针代替 shift，避免 O(n) 搬移</span>
  <span class="token keyword">while</span> <span class="token punctuation">(</span>head <span class="token operator">&lt;</span> queue<span class="token punctuation">.</span>length<span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token keyword">const</span> size <span class="token operator">=</span> queue<span class="token punctuation">.</span>length<span class="token punctuation">,</span> level <span class="token operator">=</span> <span class="token punctuation">[</span><span class="token punctuation">]</span><span class="token punctuation">;</span>
    <span class="token keyword">for</span> <span class="token punctuation">(</span><span class="token keyword">let</span> i <span class="token operator">=</span> head<span class="token punctuation">;</span> i <span class="token operator">&lt;</span> size<span class="token punctuation">;</span> i<span class="token operator">++</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
      <span class="token keyword">const</span> node <span class="token operator">=</span> queue<span class="token punctuation">[</span>i<span class="token punctuation">]</span><span class="token punctuation">;</span>
      level<span class="token punctuation">.</span><span class="token function">push</span><span class="token punctuation">(</span>node<span class="token punctuation">.</span>val<span class="token punctuation">)</span><span class="token punctuation">;</span>
      <span class="token keyword">if</span> <span class="token punctuation">(</span>node<span class="token punctuation">.</span>left<span class="token punctuation">)</span> queue<span class="token punctuation">.</span><span class="token function">push</span><span class="token punctuation">(</span>node<span class="token punctuation">.</span>left<span class="token punctuation">)</span><span class="token punctuation">;</span>
      <span class="token keyword">if</span> <span class="token punctuation">(</span>node<span class="token punctuation">.</span>right<span class="token punctuation">)</span> queue<span class="token punctuation">.</span><span class="token function">push</span><span class="token punctuation">(</span>node<span class="token punctuation">.</span>right<span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>
    head <span class="token operator">=</span> size<span class="token punctuation">;</span>
    res<span class="token punctuation">.</span><span class="token function">push</span><span class="token punctuation">(</span>level<span class="token punctuation">)</span><span class="token punctuation">;</span>
  <span class="token punctuation">}</span>
  <span class="token keyword">return</span> res<span class="token punctuation">;</span>
<span class="token punctuation">}</span>
<span class="token comment">// 对称：必须是交叉比较（左的左 vs 右的右、左的右 vs 右的左）</span>
<span class="token keyword">function</span> <span class="token function">isMirror</span><span class="token punctuation">(</span><span class="token parameter">a<span class="token punctuation">,</span> b</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
  <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token operator">!</span>a <span class="token operator">||</span> <span class="token operator">!</span>b<span class="token punctuation">)</span> <span class="token keyword">return</span> a <span class="token operator">===</span> b<span class="token punctuation">;</span>                     <span class="token comment">// 同时为空才对称</span>
  <span class="token keyword">return</span> a<span class="token punctuation">.</span>val <span class="token operator">===</span> b<span class="token punctuation">.</span>val <span class="token operator">&amp;&amp;</span> <span class="token function">isMirror</span><span class="token punctuation">(</span>a<span class="token punctuation">.</span>left<span class="token punctuation">,</span> b<span class="token punctuation">.</span>right<span class="token punctuation">)</span> <span class="token operator">&amp;&amp;</span> <span class="token function">isMirror</span><span class="token punctuation">(</span>a<span class="token punctuation">.</span>right<span class="token punctuation">,</span> b<span class="token punctuation">.</span>left<span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
<span class="token keyword">const</span> <span class="token function-variable function">isSymmetric</span> <span class="token operator">=</span> <span class="token punctuation">(</span><span class="token parameter">root</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token operator">!</span>root <span class="token operator">||</span> <span class="token function">isMirror</span><span class="token punctuation">(</span>root<span class="token punctuation">.</span>left<span class="token punctuation">,</span> root<span class="token punctuation">.</span>right<span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>追问与易错点</strong>：</p><ul><li>追问：对称和镜像有什么区别？答：镜像是把一棵树整体翻转（变换自身），对称是判断一棵树是否是它自己的镜像（比较左右子树），判定函数不同但递归结构相通。</li><li>追问：求最大深度能用 BFS 吗？答：可以，每处理完一层就 <code>depth++</code>，循环结束时的深度就是答案；好处是不受递归栈限制。</li><li>陷阱：对称判断写成 <code>isMirror(a.left, b.left) &amp;&amp; isMirror(a.right, b.right)</code>，这是&quot;结构相同&quot;而不是&quot;对称&quot;，最高频的错误。</li></ul><h3 id="q16-最近公共祖先怎么求-二叉搜索树怎么校验和查找" tabindex="-1"><a class="header-anchor" href="#q16-最近公共祖先怎么求-二叉搜索树怎么校验和查找" aria-hidden="true">#</a> Q16 最近公共祖先怎么求？二叉搜索树怎么校验和查找？</h3><p><strong>考察点</strong>：考&quot;后序上收&quot;这一通用树技巧，以及 BST 定义中&quot;整棵子树的区间约束&quot;这个关键细节。</p><p><strong>参考答案</strong>：</p><blockquote><p><strong>一句话结论</strong>：最近公共祖先（LCA，Lowest Common Ancestor）用后序递归，若左右子树各返回一个目标节点则当前节点即 LCA，只有一侧返回非空就继续上抛，一次遍历 O(n)；BST 的校验必须传&quot;上下界区间&quot;，不能只比较父子节点。</p></blockquote><ol><li>LCA 递归三句：<code>if (!root || root === p || root === q) return root;</code> 取左右递归结果；<code>if (left &amp;&amp; right) return root;</code> 两侧都有就是答案；<code>return left || right;</code> 否则把找到的那个继续向上传递。</li><li>BST 上的 LCA 更快：利用大小关系从根往下走，<code>p</code>、<code>q</code> 都小于当前值就往左、都大于就往右，否则当前节点即 LCA，时间 O(h)。</li><li>BST 定义复习：任意节点的左子树所有值都小于它、右子树所有值都大于它。注意是<strong>子树全体</strong>，不是仅直接孩子。</li><li>常见错解：只判断 <code>root.left.val &lt; root.val &amp;&amp; root.right.val &gt; root.val</code>。反例 <code>[5,1,4,null,null,3,6]</code>：4 的直接左右孩子合法，但它位于 5 的右子树却比 5 小，实际不是 BST。</li><li>正确校验两种做法：一是在递归时携带开区间 <code>(low, high)</code>，每深入一层就收紧一侧边界；二是中序遍历，只要发现某值 ≤ 前一个值就返回 <code>false</code>，代码最短且只需保留&quot;上一个值&quot;一个变量。</li><li><strong>复杂度与边界</strong>：LCA 时间 O(n)、空间 O(h)；BST 校验 O(n)/O(h)；BST 查找平均 O(log n)、最坏 O(n)（插入有序数据退化成链），迭代写法空间 O(1)。边界：<code>p</code> 或 <code>q</code> 不在树中时上述写法可能返回错误节点，需按题意先确认存在性；BST 查找要注意空树。</li></ol><div class="language-javascript line-numbers-mode" data-ext="js"><pre class="language-javascript"><code><span class="token comment">// 最近公共祖先：后序上收，两侧各有一个则当前节点即 LCA</span>
<span class="token keyword">function</span> <span class="token function">lowestCommonAncestor</span><span class="token punctuation">(</span><span class="token parameter">root<span class="token punctuation">,</span> p<span class="token punctuation">,</span> q</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
  <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token operator">!</span>root <span class="token operator">||</span> root <span class="token operator">===</span> p <span class="token operator">||</span> root <span class="token operator">===</span> q<span class="token punctuation">)</span> <span class="token keyword">return</span> root<span class="token punctuation">;</span> <span class="token comment">// 命中或到底</span>
  <span class="token keyword">const</span> left <span class="token operator">=</span> <span class="token function">lowestCommonAncestor</span><span class="token punctuation">(</span>root<span class="token punctuation">.</span>left<span class="token punctuation">,</span> p<span class="token punctuation">,</span> q<span class="token punctuation">)</span><span class="token punctuation">;</span>
  <span class="token keyword">const</span> right <span class="token operator">=</span> <span class="token function">lowestCommonAncestor</span><span class="token punctuation">(</span>root<span class="token punctuation">.</span>right<span class="token punctuation">,</span> p<span class="token punctuation">,</span> q<span class="token punctuation">)</span><span class="token punctuation">;</span>
  <span class="token keyword">if</span> <span class="token punctuation">(</span>left <span class="token operator">&amp;&amp;</span> right<span class="token punctuation">)</span> <span class="token keyword">return</span> root<span class="token punctuation">;</span>
  <span class="token keyword">return</span> left <span class="token operator">||</span> right<span class="token punctuation">;</span>                    <span class="token comment">// 否则把找到的那个继续上抛</span>
<span class="token punctuation">}</span>
<span class="token comment">// 校验 BST：区间法，节点值必须严格落在 (low, high) 内</span>
<span class="token keyword">function</span> <span class="token function">isValidBST</span><span class="token punctuation">(</span><span class="token parameter">root<span class="token punctuation">,</span> low <span class="token operator">=</span> <span class="token operator">-</span><span class="token number">Infinity</span><span class="token punctuation">,</span> high <span class="token operator">=</span> <span class="token number">Infinity</span></span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
  <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token operator">!</span>root<span class="token punctuation">)</span> <span class="token keyword">return</span> <span class="token boolean">true</span><span class="token punctuation">;</span>
  <span class="token keyword">if</span> <span class="token punctuation">(</span>root<span class="token punctuation">.</span>val <span class="token operator">&lt;=</span> low <span class="token operator">||</span> root<span class="token punctuation">.</span>val <span class="token operator">&gt;=</span> high<span class="token punctuation">)</span> <span class="token keyword">return</span> <span class="token boolean">false</span><span class="token punctuation">;</span>
  <span class="token keyword">return</span> <span class="token function">isValidBST</span><span class="token punctuation">(</span>root<span class="token punctuation">.</span>left<span class="token punctuation">,</span> low<span class="token punctuation">,</span> root<span class="token punctuation">.</span>val<span class="token punctuation">)</span> <span class="token operator">&amp;&amp;</span> <span class="token function">isValidBST</span><span class="token punctuation">(</span>root<span class="token punctuation">.</span>right<span class="token punctuation">,</span> root<span class="token punctuation">.</span>val<span class="token punctuation">,</span> high<span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
<span class="token comment">// 查找：迭代下沉，避免递归栈</span>
<span class="token keyword">function</span> <span class="token function">searchBST</span><span class="token punctuation">(</span><span class="token parameter">root<span class="token punctuation">,</span> target</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
  <span class="token keyword">let</span> cur <span class="token operator">=</span> root<span class="token punctuation">;</span>
  <span class="token keyword">while</span> <span class="token punctuation">(</span>cur<span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token keyword">if</span> <span class="token punctuation">(</span>cur<span class="token punctuation">.</span>val <span class="token operator">===</span> target<span class="token punctuation">)</span> <span class="token keyword">return</span> cur<span class="token punctuation">;</span>
    cur <span class="token operator">=</span> target <span class="token operator">&lt;</span> cur<span class="token punctuation">.</span>val <span class="token operator">?</span> cur<span class="token punctuation">.</span>left <span class="token operator">:</span> cur<span class="token punctuation">.</span>right<span class="token punctuation">;</span>
  <span class="token punctuation">}</span>
  <span class="token keyword">return</span> <span class="token keyword">null</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>追问与易错点</strong>：</p><ul><li>追问：BST 插入和删除哪个麻烦？答：删除麻烦。删除有两个孩子的节点时，要用<strong>中序后继</strong>（右子树最小值）或中序前驱替换它，再递归删除后继节点，保持 BST 性质。</li><li>追问：为什么不用&quot;从根往下记路径再比最后一个公共节点&quot;？答：那样要 O(n) 额外空间存路径；一次后序遍历只需 O(h) 递归栈，是面试更想看到的解法。</li><li>陷阱：BST 校验把&quot;左孩子 &lt; 根 &lt; 右孩子&quot;当成条件，<code>[5,1,4,null,null,3,6]</code> 这类用例会判错，这是最经典的翻车点。</li></ul><h3 id="q17-top-k-问题怎么做-堆和快排两种解法怎么取舍" tabindex="-1"><a class="header-anchor" href="#q17-top-k-问题怎么做-堆和快排两种解法怎么取舍" aria-hidden="true">#</a> Q17 Top K 问题怎么做？堆和快排两种解法怎么取舍？</h3><p><strong>考察点</strong>：考堆（Heap）的使用场景与&quot;部分排序&quot;思想，以及 <code>O(n log k)</code> 与 <code>O(n)</code> 期望两种方案的选择依据。</p><p><strong>参考答案</strong>：</p><blockquote><p><strong>一句话结论</strong>：求前 K 大用<strong>容量为 K 的小顶堆</strong>——堆顶是当前 K 个里的最小值，新元素比堆顶大就替换堆顶并下沉，遍历完堆里就是前 K 大；时间 O(n log k)、空间 O(k)，适合海量数据流。</p></blockquote><ol><li>为什么&quot;前 K 大&quot;用小顶堆：需要随时淘汰&quot;当前最小的候选&quot;。小顶堆能在 O(1) 看到最弱者、O(log k) 完成替换；求前 K 小则反过来用大顶堆。</li><li>建堆细节：先把前 K 个元素建堆，再遍历剩余元素。若&quot;先全部入堆再弹出 n-k 次&quot;，会退化成 O(n log n)，不是最优。</li><li>复杂度对比：堆解法 O(n log k) 时间、O(k) 空间，<strong>不要求全量数据驻留内存</strong>，可处理数据流/超大数据；快排分区（Quickselect）解法期望 O(n)、最坏 O(n²)，只需 O(1) 额外空间但必须能随机访问全部数据。</li><li>选择依据：数据量大、流式、内存受限、K 远小于 n → 堆；数据已在内存、只求一次、追求平均最快 → Quickselect（它会打乱元素顺序，若不允许修改原数组要先拷贝）。</li><li>JS 里没有内置优先队列，要手写堆（数组 + 上浮/下沉）；工程中若只是&quot;取最大几个&quot;且 n 不大，直接 <code>sort((a,b)=&gt;b-a).slice(0,k)</code> 反而更快更简单。</li><li><strong>边界条件</strong>：<code>k &lt;= 0</code> 返回空数组，<code>k &gt;= n</code> 返回整个数组；数组有重复值时&quot;前 K 大&quot;通常允许重复计数，若要去重需先 <code>Set</code>；堆的下沉循环要防止 <code>l</code>/<code>r</code> 越界。</li></ol><div class="language-javascript line-numbers-mode" data-ext="js"><pre class="language-javascript"><code><span class="token comment">// 前 K 大：容量 k 的小顶堆（堆顶是当前第 k 名，便于淘汰）</span>
<span class="token keyword">function</span> <span class="token function">topK</span><span class="token punctuation">(</span><span class="token parameter">arr<span class="token punctuation">,</span> k</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
  <span class="token keyword">if</span> <span class="token punctuation">(</span>k <span class="token operator">&lt;=</span> <span class="token number">0</span><span class="token punctuation">)</span> <span class="token keyword">return</span> <span class="token punctuation">[</span><span class="token punctuation">]</span><span class="token punctuation">;</span>
  <span class="token keyword">if</span> <span class="token punctuation">(</span>k <span class="token operator">&gt;=</span> arr<span class="token punctuation">.</span>length<span class="token punctuation">)</span> <span class="token keyword">return</span> arr<span class="token punctuation">.</span><span class="token function">slice</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
  <span class="token keyword">const</span> heap <span class="token operator">=</span> arr<span class="token punctuation">.</span><span class="token function">slice</span><span class="token punctuation">(</span><span class="token number">0</span><span class="token punctuation">,</span> k<span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">sort</span><span class="token punctuation">(</span><span class="token punctuation">(</span><span class="token parameter">a<span class="token punctuation">,</span> b</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> a <span class="token operator">-</span> b<span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token comment">// 简化：用小顶堆数组</span>
  <span class="token keyword">for</span> <span class="token punctuation">(</span><span class="token keyword">let</span> i <span class="token operator">=</span> k<span class="token punctuation">;</span> i <span class="token operator">&lt;</span> arr<span class="token punctuation">.</span>length<span class="token punctuation">;</span> i<span class="token operator">++</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token keyword">if</span> <span class="token punctuation">(</span>arr<span class="token punctuation">[</span>i<span class="token punctuation">]</span> <span class="token operator">&lt;=</span> heap<span class="token punctuation">[</span><span class="token number">0</span><span class="token punctuation">]</span><span class="token punctuation">)</span> <span class="token keyword">continue</span><span class="token punctuation">;</span>                   <span class="token comment">// 不比最弱者大就跳过</span>
    <span class="token keyword">let</span> p <span class="token operator">=</span> <span class="token number">0</span><span class="token punctuation">;</span>                                         <span class="token comment">// 替换堆顶后下沉恢复堆序</span>
    heap<span class="token punctuation">[</span>p<span class="token punctuation">]</span> <span class="token operator">=</span> arr<span class="token punctuation">[</span>i<span class="token punctuation">]</span><span class="token punctuation">;</span>
    <span class="token keyword">while</span> <span class="token punctuation">(</span><span class="token boolean">true</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
      <span class="token keyword">const</span> l <span class="token operator">=</span> <span class="token number">2</span> <span class="token operator">*</span> p <span class="token operator">+</span> <span class="token number">1</span><span class="token punctuation">,</span> r <span class="token operator">=</span> l <span class="token operator">+</span> <span class="token number">1</span><span class="token punctuation">;</span>
      <span class="token keyword">let</span> min <span class="token operator">=</span> p<span class="token punctuation">;</span>
      <span class="token keyword">if</span> <span class="token punctuation">(</span>l <span class="token operator">&lt;</span> k <span class="token operator">&amp;&amp;</span> heap<span class="token punctuation">[</span>l<span class="token punctuation">]</span> <span class="token operator">&lt;</span> heap<span class="token punctuation">[</span>min<span class="token punctuation">]</span><span class="token punctuation">)</span> min <span class="token operator">=</span> l<span class="token punctuation">;</span>
      <span class="token keyword">if</span> <span class="token punctuation">(</span>r <span class="token operator">&lt;</span> k <span class="token operator">&amp;&amp;</span> heap<span class="token punctuation">[</span>r<span class="token punctuation">]</span> <span class="token operator">&lt;</span> heap<span class="token punctuation">[</span>min<span class="token punctuation">]</span><span class="token punctuation">)</span> min <span class="token operator">=</span> r<span class="token punctuation">;</span>
      <span class="token keyword">if</span> <span class="token punctuation">(</span>min <span class="token operator">===</span> p<span class="token punctuation">)</span> <span class="token keyword">break</span><span class="token punctuation">;</span>
      <span class="token punctuation">[</span>heap<span class="token punctuation">[</span>p<span class="token punctuation">]</span><span class="token punctuation">,</span> heap<span class="token punctuation">[</span>min<span class="token punctuation">]</span><span class="token punctuation">]</span> <span class="token operator">=</span> <span class="token punctuation">[</span>heap<span class="token punctuation">[</span>min<span class="token punctuation">]</span><span class="token punctuation">,</span> heap<span class="token punctuation">[</span>p<span class="token punctuation">]</span><span class="token punctuation">]</span><span class="token punctuation">;</span>
      p <span class="token operator">=</span> min<span class="token punctuation">;</span>
    <span class="token punctuation">}</span>
  <span class="token punctuation">}</span>
  <span class="token keyword">return</span> heap<span class="token punctuation">;</span> <span class="token comment">// 堆内即前 k 大（无序）</span>
<span class="token punctuation">}</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>追问与易错点</strong>：</p><ul><li>追问：为什么求前 K 大用小顶堆而不是大顶堆？答：大顶堆堆顶是最大值，无法判断&quot;新元素该不该进来&quot;；只有小顶堆的堆顶才是&quot;当前第 K 名&quot;，便于淘汰。</li><li>追问：堆的上浮与下沉分别用在哪？答：插入元素时上浮（和父节点比），删除堆顶时把末尾元素移到堆顶再下沉（和孩子比）。建堆时从最后一个非叶子节点开始逐个下沉，可在 O(n) 内完成。</li><li>陷阱：说&quot;建堆需要 O(n log n)&quot;是错的——自底向上建堆是 O(n)，堆排序整体才是 O(n log n)。</li></ul><h3 id="q18-动态规划入门-爬楼梯、最大子数组和、打家劫舍、最长递增子序列怎么做" tabindex="-1"><a class="header-anchor" href="#q18-动态规划入门-爬楼梯、最大子数组和、打家劫舍、最长递增子序列怎么做" aria-hidden="true">#</a> Q18 动态规划入门：爬楼梯、最大子数组和、打家劫舍、最长递增子序列怎么做？</h3><p><strong>考察点</strong>：考 DP 的状态定义、转移方程推导与空间优化，是算法面试区分度最高的一题。</p><p><strong>参考答案</strong>：</p><blockquote><p><strong>一句话结论</strong>：动态规划（Dynamic Programming）三步走——<strong>定义状态（dp[i] 表示什么）、写转移方程（dp[i] 由哪些更小状态推来）、定初始条件与遍历顺序</strong>；能用滚动变量把空间从 O(n) 压到 O(1) 是常见加分点。</p></blockquote><ol><li>爬楼梯：<code>dp[i]</code> 表示爬到第 i 阶的方法数，<code>dp[i] = dp[i-1] + dp[i-2]</code>，初始 <code>dp[1]=1, dp[2]=2</code>。本质是斐波那契数列，用两个变量滚动即可把空间降到 O(1)。</li><li>最大子数组和（Kadane 算法）：<code>dp[i]</code> 表示&quot;以 i 结尾的最大连续子数组和&quot;，<code>dp[i] = max(nums[i], dp[i-1] + nums[i])</code>——要么自己另起一段，要么接上前面的。答案是所有 <code>dp[i]</code> 的最大值。</li><li>打家劫舍：<code>dp[i] = max(dp[i-1], dp[i-2] + nums[i])</code>——不偷第 i 家就沿用前一家，偷则与 i-1 互斥；同样可用滚动变量优化到 O(1) 空间。</li><li>最长递增子序列（LIS）：基础解法 <code>dp[i]</code> 表示&quot;以 i 结尾的 LIS 长度&quot;，<code>dp[i] = max(dp[j]) + 1 (j &lt; i 且 nums[j] &lt; nums[i])</code>，时间 O(n²)、空间 O(n)。优化解用&quot;贪心 + 二分&quot;的 <code>tails</code> 数组（<code>tails[k]</code> 表示长度 k+1 的递增子序列的最小结尾值），时间 O(n log n)。</li><li>0-1 背包：<code>dp[i][j] = max(dp[i-1][j], dp[i-1][j-w[i]] + v[i])</code>；压缩成一维后<strong>容量必须倒序遍历</strong>，否则同一物品会被重复使用（那就变成完全背包了）。</li><li><strong>复杂度与边界</strong>：爬楼梯 O(n)/O(1)、最大子数组和 O(n)/O(1)、打家劫舍 O(n)/O(1)、LIS 基础 O(n²)/O(n) 或优化 O(n log n)/O(n)、背包 O(n·capacity)/O(capacity)。边界：空数组返回 0；LIS 的答案不是 <code>dp[n-1]</code> 而是 <code>max(dp)</code>；<code>nums</code> 全为负数时最大子数组和就是最大的那个负数。</li></ol><div class="language-javascript line-numbers-mode" data-ext="js"><pre class="language-javascript"><code><span class="token comment">// 爬楼梯：滚动变量，O(n) 时间 O(1) 空间</span>
<span class="token keyword">function</span> <span class="token function">climbStairs</span><span class="token punctuation">(</span><span class="token parameter">n</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
  <span class="token keyword">let</span> prev <span class="token operator">=</span> <span class="token number">1</span><span class="token punctuation">,</span> cur <span class="token operator">=</span> <span class="token number">1</span><span class="token punctuation">;</span>               <span class="token comment">// dp[0]=1, dp[1]=1</span>
  <span class="token keyword">for</span> <span class="token punctuation">(</span><span class="token keyword">let</span> i <span class="token operator">=</span> <span class="token number">2</span><span class="token punctuation">;</span> i <span class="token operator">&lt;=</span> n<span class="token punctuation">;</span> i<span class="token operator">++</span><span class="token punctuation">)</span> <span class="token punctuation">[</span>prev<span class="token punctuation">,</span> cur<span class="token punctuation">]</span> <span class="token operator">=</span> <span class="token punctuation">[</span>cur<span class="token punctuation">,</span> prev <span class="token operator">+</span> cur<span class="token punctuation">]</span><span class="token punctuation">;</span> <span class="token comment">// dp[i]=dp[i-1]+dp[i-2]</span>
  <span class="token keyword">return</span> cur<span class="token punctuation">;</span>
<span class="token punctuation">}</span>
<span class="token comment">// 最大子数组和：Kadane，dp[i] = max(nums[i], dp[i-1] + nums[i])</span>
<span class="token keyword">function</span> <span class="token function">maxSubArray</span><span class="token punctuation">(</span><span class="token parameter">nums</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
  <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token operator">!</span>nums<span class="token punctuation">.</span>length<span class="token punctuation">)</span> <span class="token keyword">return</span> <span class="token number">0</span><span class="token punctuation">;</span>          <span class="token comment">// 空数组边界：返回 0 而不是 undefined</span>
  <span class="token keyword">let</span> cur <span class="token operator">=</span> nums<span class="token punctuation">[</span><span class="token number">0</span><span class="token punctuation">]</span><span class="token punctuation">,</span> best <span class="token operator">=</span> nums<span class="token punctuation">[</span><span class="token number">0</span><span class="token punctuation">]</span><span class="token punctuation">;</span>
  <span class="token keyword">for</span> <span class="token punctuation">(</span><span class="token keyword">let</span> i <span class="token operator">=</span> <span class="token number">1</span><span class="token punctuation">;</span> i <span class="token operator">&lt;</span> nums<span class="token punctuation">.</span>length<span class="token punctuation">;</span> i<span class="token operator">++</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    cur <span class="token operator">=</span> Math<span class="token punctuation">.</span><span class="token function">max</span><span class="token punctuation">(</span>nums<span class="token punctuation">[</span>i<span class="token punctuation">]</span><span class="token punctuation">,</span> cur <span class="token operator">+</span> nums<span class="token punctuation">[</span>i<span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token comment">// 另起一段 or 接上前面</span>
    best <span class="token operator">=</span> Math<span class="token punctuation">.</span><span class="token function">max</span><span class="token punctuation">(</span>best<span class="token punctuation">,</span> cur<span class="token punctuation">)</span><span class="token punctuation">;</span>
  <span class="token punctuation">}</span>
  <span class="token keyword">return</span> best<span class="token punctuation">;</span>
<span class="token punctuation">}</span>
<span class="token comment">// 0-1 背包：一维压缩后容量必须倒序，保证每件物品只用一次</span>
<span class="token keyword">function</span> <span class="token function">knapsack</span><span class="token punctuation">(</span><span class="token parameter">weights<span class="token punctuation">,</span> values<span class="token punctuation">,</span> capacity</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
  <span class="token keyword">const</span> dp <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token class-name">Array</span><span class="token punctuation">(</span>capacity <span class="token operator">+</span> <span class="token number">1</span><span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">fill</span><span class="token punctuation">(</span><span class="token number">0</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
  <span class="token keyword">for</span> <span class="token punctuation">(</span><span class="token keyword">let</span> i <span class="token operator">=</span> <span class="token number">0</span><span class="token punctuation">;</span> i <span class="token operator">&lt;</span> weights<span class="token punctuation">.</span>length<span class="token punctuation">;</span> i<span class="token operator">++</span><span class="token punctuation">)</span>
    <span class="token keyword">for</span> <span class="token punctuation">(</span><span class="token keyword">let</span> j <span class="token operator">=</span> capacity<span class="token punctuation">;</span> j <span class="token operator">&gt;=</span> weights<span class="token punctuation">[</span>i<span class="token punctuation">]</span><span class="token punctuation">;</span> j<span class="token operator">--</span><span class="token punctuation">)</span> dp<span class="token punctuation">[</span>j<span class="token punctuation">]</span> <span class="token operator">=</span> Math<span class="token punctuation">.</span><span class="token function">max</span><span class="token punctuation">(</span>dp<span class="token punctuation">[</span>j<span class="token punctuation">]</span><span class="token punctuation">,</span> dp<span class="token punctuation">[</span>j <span class="token operator">-</span> weights<span class="token punctuation">[</span>i<span class="token punctuation">]</span><span class="token punctuation">]</span> <span class="token operator">+</span> values<span class="token punctuation">[</span>i<span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
  <span class="token keyword">return</span> dp<span class="token punctuation">[</span>capacity<span class="token punctuation">]</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>追问与易错点</strong>：</p><ul><li>追问：怎么判断一道题能不能用 DP？答：两个特征——<strong>最优子结构</strong>（大问题最优解由子问题最优解构成）和<strong>重叠子问题</strong>（递归会重复计算同一状态）。缺少重叠子问题就只是分治，用备忘录没收益。</li><li>追问：状态转移方程怎么推？答：先想&quot;最后一步决策是什么&quot;，把所有可能的选择枚举出来，再对每种选择写出&quot;它依赖哪个更小的状态 + 这一步的收益&quot;，取 <code>max</code>/<code>min</code>/累加。用暴力递归写出来、加备忘录、再改迭代——这是最稳的推导路径。</li><li>陷阱：LIS 返回 <code>dp[n-1]</code> 而不是 <code>max(dp)</code>；0-1 背包一维压缩时正序遍历容量，把物品用了多次导致答案偏大。</li></ul><h3 id="q19-贪心怎么用-分发饼干、跳跃游戏为什么贪心是对的" tabindex="-1"><a class="header-anchor" href="#q19-贪心怎么用-分发饼干、跳跃游戏为什么贪心是对的" aria-hidden="true">#</a> Q19 贪心怎么用？分发饼干、跳跃游戏为什么贪心是对的？</h3><p><strong>考察点</strong>：考贪心的适用条件（局部最优能否推出全局最优）与&quot;用交换论证说明为什么贪心成立&quot;的表达能力。</p><p><strong>参考答案</strong>：</p><blockquote><p><strong>一句话结论</strong>：贪心在每一步都取当前看起来最优的选择，且<strong>不回溯</strong>；它成立的前提是问题具备&quot;贪心选择性质&quot;——必须能证明局部最优可以推出全局最优。分发饼干和跳跃游戏都满足这个前提。</p></blockquote><ol><li>贪心 vs 动态规划：贪心每一步只保留一个决策、不回头，时间通常 O(n log n) 或 O(n)；DP 会枚举所有可能并比较，更稳但更慢，且能处理贪心失效的问题（如 0-1 背包按性价比贪心就是错的）。</li><li>分发饼干（Assign Cookies）：两组都升序排序，双指针从最小的孩子和最小的饼干开始——饼干够就喂这个孩子、两指针都前进，不够就换更大的饼干。贪心依据：用能满足的最小饼干去满足最小胃口的孩子，能最大化剩余资源。</li><li>跳跃游戏（Jump Game）：维护 <code>maxReach</code> 表示当前能到达的最远下标，遍历时若 <code>i &gt; maxReach</code> 说明卡住返回 <code>false</code>，否则更新 <code>maxReach = max(maxReach, i + nums[i])</code>。</li><li>跳跃游戏 II（求最少步数）：在&quot;当前步能覆盖的区间&quot;内找出下一跳的最远边界，走到边界就 <code>steps++</code> 并更新边界。本质是 BFS 分层，但用 O(1) 空间实现。</li><li>贪心为什么对（交换论证）：若最优解的第一步与贪心选择不同，可以把最优解的第一步替换成贪心选择而不使结果变差，反复替换即可得出&quot;贪心解也是最优解&quot;。能说出这个论证框架是加分点。</li><li><strong>复杂度与边界</strong>：分发饼干 O(n log n)（排序主导）+ O(1) 空间，跳跃游戏 O(n)/O(1)。边界：空数组、只有一个元素；跳跃游戏起点必须可达（<code>nums[0] = 0</code> 且长度 &gt; 1 时直接返回 <code>false</code>）；其他经典贪心还有区间调度（按结束时间排序）与合并区间（按起始排序）。</li></ol><div class="language-javascript line-numbers-mode" data-ext="js"><pre class="language-javascript"><code><span class="token comment">// 分发饼干：两组升序 + 双指针，用最小饼干满足最小胃口</span>
<span class="token keyword">function</span> <span class="token function">findContentChildren</span><span class="token punctuation">(</span><span class="token parameter">g<span class="token punctuation">,</span> s</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
  g<span class="token punctuation">.</span><span class="token function">sort</span><span class="token punctuation">(</span><span class="token punctuation">(</span><span class="token parameter">a<span class="token punctuation">,</span> b</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> a <span class="token operator">-</span> b<span class="token punctuation">)</span><span class="token punctuation">;</span>
  s<span class="token punctuation">.</span><span class="token function">sort</span><span class="token punctuation">(</span><span class="token punctuation">(</span><span class="token parameter">a<span class="token punctuation">,</span> b</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> a <span class="token operator">-</span> b<span class="token punctuation">)</span><span class="token punctuation">;</span>
  <span class="token keyword">let</span> child <span class="token operator">=</span> <span class="token number">0</span><span class="token punctuation">,</span> cookie <span class="token operator">=</span> <span class="token number">0</span><span class="token punctuation">;</span>
  <span class="token keyword">while</span> <span class="token punctuation">(</span>child <span class="token operator">&lt;</span> g<span class="token punctuation">.</span>length <span class="token operator">&amp;&amp;</span> cookie <span class="token operator">&lt;</span> s<span class="token punctuation">.</span>length<span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token keyword">if</span> <span class="token punctuation">(</span>s<span class="token punctuation">[</span>cookie<span class="token punctuation">]</span> <span class="token operator">&gt;=</span> g<span class="token punctuation">[</span>child<span class="token punctuation">]</span><span class="token punctuation">)</span> child<span class="token operator">++</span><span class="token punctuation">;</span>  <span class="token comment">// 满足了这个孩子</span>
    cookie<span class="token operator">++</span><span class="token punctuation">;</span>                            <span class="token comment">// 这块饼干无论用没用都往后走</span>
  <span class="token punctuation">}</span>
  <span class="token keyword">return</span> child<span class="token punctuation">;</span>
<span class="token punctuation">}</span>
<span class="token comment">// 跳跃游戏：维护最远可达，遍历到不可达位置即失败</span>
<span class="token keyword">function</span> <span class="token function">canJump</span><span class="token punctuation">(</span><span class="token parameter">nums</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
  <span class="token keyword">let</span> maxReach <span class="token operator">=</span> <span class="token number">0</span><span class="token punctuation">;</span>
  <span class="token keyword">for</span> <span class="token punctuation">(</span><span class="token keyword">let</span> i <span class="token operator">=</span> <span class="token number">0</span><span class="token punctuation">;</span> i <span class="token operator">&lt;</span> nums<span class="token punctuation">.</span>length<span class="token punctuation">;</span> i<span class="token operator">++</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token keyword">if</span> <span class="token punctuation">(</span>i <span class="token operator">&gt;</span> maxReach<span class="token punctuation">)</span> <span class="token keyword">return</span> <span class="token boolean">false</span><span class="token punctuation">;</span>      <span class="token comment">// 当前位置不可达，卡住</span>
    maxReach <span class="token operator">=</span> Math<span class="token punctuation">.</span><span class="token function">max</span><span class="token punctuation">(</span>maxReach<span class="token punctuation">,</span> i <span class="token operator">+</span> nums<span class="token punctuation">[</span>i<span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token keyword">if</span> <span class="token punctuation">(</span>maxReach <span class="token operator">&gt;=</span> nums<span class="token punctuation">.</span>length <span class="token operator">-</span> <span class="token number">1</span><span class="token punctuation">)</span> <span class="token keyword">return</span> <span class="token boolean">true</span><span class="token punctuation">;</span>
  <span class="token punctuation">}</span>
  <span class="token keyword">return</span> <span class="token boolean">true</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>追问与易错点</strong>：</p><ul><li>追问：零钱兑换用贪心对吗？答：不一定。只有币值互相成倍数关系（如 1、5、10、25 这类典型币制）贪心才成立；否则要用 DP 求最少硬币数。这是贪心的经典反例。</li><li>追问：分发饼干为什么要排序？答：把&quot;最小饼干配最小胃口&quot;变成可比较的顺序扫描，避免用大饼干浪费在小胃口孩子身上；不排序无法保证局部最优的顺序性。</li><li>陷阱：把贪心和 DP 混为一谈，或者声称&quot;贪心总是更优&quot;。贪心的优势是快，代价是适用范围窄且必须能证明，证不出来就该换 DP。</li></ul><h3 id="q20-只出现一次的数字、位计数、位运算技巧-前端面试会问吗" tabindex="-1"><a class="header-anchor" href="#q20-只出现一次的数字、位计数、位运算技巧-前端面试会问吗" aria-hidden="true">#</a> Q20 只出现一次的数字、位计数、位运算技巧，前端面试会问吗？</h3><p><strong>考察点</strong>：考异或（XOR）的性质与位运算基础，这类题代码极短但能分辨基础是否扎实。</p><p><strong>参考答案</strong>：</p><blockquote><p><strong>一句话结论</strong>：异或有三条性质——<code>a ^ a = 0</code>、<code>a ^ 0 = a</code>、满足交换律与结合律，所以全部元素异或一遍，成对出现的会互相抵消，剩下的就是只出现一次的数字；时间 O(n)、空间 O(1)。</p></blockquote><ol><li>只出现一次的数字：<code>reduce((acc, n) =&gt; acc ^ n, 0)</code> 一行解决。相比&quot;用哈希表统计次数&quot;，省掉 O(n) 空间，这是最常被追问的对比点。</li><li>变体：其余元素出现三次用位计数（统计每一位上 1 的个数对 3 取模）；有两个只出现一次的数字时，先整体异或得到 <code>x ^ y</code>，取其最低位的 1 作为分组依据把数组分成两组，各自异或即得两个数。</li><li>位计数（Counting Bits）：求 0 到 n 每个数的二进制中 1 的个数，用 DP：<code>dp[i] = dp[i &gt;&gt; 1] + (i &amp; 1)</code>，时间 O(n)。</li><li>常用位运算技巧：<code>n &amp; 1</code> 判奇偶（比 <code>n % 2</code> 对负数更安全）；<code>n &amp; (n - 1)</code> 消掉最低位的 1（可数 1 的个数、判是否为 2 的幂：<code>n &gt; 0 &amp;&amp; (n &amp; (n-1)) === 0</code>）；<code>n &amp; -n</code> 取最低位的 1。</li><li>交换两个数：<code>a ^= b; b ^= a; a ^= b;</code>（无需临时变量）。但现代工程里<strong>不推荐</strong>这样写，可读性差且对同一变量自交换会归零，属于炫技题而非生产写法。</li><li><strong>复杂度与边界</strong>：只出现一次的数字 O(n)/O(1)；位计数 O(n)/O(n)（可优化到 O(1) 只需返回数组）。边界：<code>reduce</code> 必须显式传初始值 <code>0</code>，否则空数组会抛 <code>TypeError: Reduce of empty array with no initial value</code>（不是返回 <code>undefined</code>）；JS 位运算会把操作数转成 <strong>32 位有符号整数</strong>，<code>1 &lt;&lt; 31</code> 是负数 <code>-2147483648</code>，超过 2³¹ 的值要用 <code>Math.floor(n / 2)</code> 或 <code>&gt;&gt;&gt; 0</code>。</li></ol><div class="language-javascript line-numbers-mode" data-ext="js"><pre class="language-javascript"><code><span class="token comment">// 只出现一次的数字（其余都出现两次）：全部异或，成对的互相抵消</span>
<span class="token keyword">const</span> <span class="token function-variable function">singleNumber</span> <span class="token operator">=</span> <span class="token punctuation">(</span><span class="token parameter">nums</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> nums<span class="token punctuation">.</span><span class="token function">reduce</span><span class="token punctuation">(</span><span class="token punctuation">(</span><span class="token parameter">acc<span class="token punctuation">,</span> n</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> acc <span class="token operator">^</span> n<span class="token punctuation">,</span> <span class="token number">0</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token comment">// 位计数：0..n 每个数的二进制 1 的个数</span>
<span class="token keyword">function</span> <span class="token function">countBits</span><span class="token punctuation">(</span><span class="token parameter">n</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
  <span class="token keyword">const</span> dp <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token class-name">Array</span><span class="token punctuation">(</span>n <span class="token operator">+</span> <span class="token number">1</span><span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">fill</span><span class="token punctuation">(</span><span class="token number">0</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
  <span class="token keyword">for</span> <span class="token punctuation">(</span><span class="token keyword">let</span> i <span class="token operator">=</span> <span class="token number">1</span><span class="token punctuation">;</span> i <span class="token operator">&lt;=</span> n<span class="token punctuation">;</span> i<span class="token operator">++</span><span class="token punctuation">)</span> dp<span class="token punctuation">[</span>i<span class="token punctuation">]</span> <span class="token operator">=</span> dp<span class="token punctuation">[</span>i <span class="token operator">&gt;&gt;</span> <span class="token number">1</span><span class="token punctuation">]</span> <span class="token operator">+</span> <span class="token punctuation">(</span>i <span class="token operator">&amp;</span> <span class="token number">1</span><span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token comment">// 右移一位的 1 个数 + 最低位</span>
  <span class="token keyword">return</span> dp<span class="token punctuation">;</span>
<span class="token punctuation">}</span>
<span class="token comment">// 交换两个数（原理演示，可读性差，生产不推荐）</span>
<span class="token keyword">let</span> a <span class="token operator">=</span> <span class="token number">3</span><span class="token punctuation">,</span> b <span class="token operator">=</span> <span class="token number">5</span><span class="token punctuation">;</span>
a <span class="token operator">^=</span> b<span class="token punctuation">;</span> b <span class="token operator">^=</span> a<span class="token punctuation">;</span> a <span class="token operator">^=</span> b<span class="token punctuation">;</span>          <span class="token comment">// a=5, b=3</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>追问与易错点</strong>：</p><ul><li>追问：<code>n &amp; (n - 1)</code> 为什么能消掉最低位的 1？答：减 1 会把最低位的 1 变成 0、其右侧的 0 全变成 1，与原数做与运算后，该位及其右侧全归零，等价于抹掉最低位的 1。</li><li>追问：<code>nums.reduce((a, b) =&gt; a ^ b)</code> 对空数组返回什么？答：直接抛 <code>TypeError: Reduce of empty array with no initial value</code>（空数组且未传初始值时 <code>reduce</code> 是报错，不是返回 <code>undefined</code>），所以必须显式传 <code>0</code> 作为初始值，这也是常见的小陷阱。</li><li>陷阱：用 <code>&lt;&lt;</code> 处理超过 32 位的数值，结果静默错误；JS 里安全整数范围是 <code>Number.MAX_SAFE_INTEGER</code>（2⁵³-1），再大要用 <code>BigInt</code>。</li></ul><h3 id="q21-前端真实业务算法-树形结构与扁平数组怎么互转" tabindex="-1"><a class="header-anchor" href="#q21-前端真实业务算法-树形结构与扁平数组怎么互转" aria-hidden="true">#</a> Q21 前端真实业务算法：树形结构与扁平数组怎么互转？</h3><p><strong>考察点</strong>：这是前端最常考的&quot;业务算法&quot;——权限菜单、组织架构、级联选择器都要用；考递归、哈希优化与删除引用字段的细节。</p><p><strong>参考答案</strong>：</p><blockquote><p><strong>一句话结论</strong>：扁平转树用&quot;一次遍历建 id → 节点映射，再一次遍历挂接父子&quot;的哈希法，时间 O(n) 远优于对每层反复筛选的 O(n²)；树转扁平用 DFS 递归，携带父 id 与层级信息。</p></blockquote><ol><li>哈希建树两步：① 遍历一次，把每项包成 <code>{ ...item, children: [] }</code> 存入 <code>Map</code>；② 遍历一次，有 <code>parentId</code> 且父节点存在就挂到 <code>parent.children</code>，否则作为根节点。全程不嵌套查找。</li><li>常见错误写法：对每个节点执行 <code>list.filter(x =&gt; x.parentId === node.id)</code> 来递归找孩子，时间复杂度 O(n²)，几千条数据就会明显卡顿——面试官很爱追问这里。</li><li>树转扁平：DFS 前序递归，把节点压入结果数组时剔除 <code>children</code> 字段，并记录 <code>parentId</code> 与 <code>level</code>。</li><li><strong>复杂度与边界</strong>：扁平转树 O(n) 时间、O(n) 空间；树转扁平 O(n) 时间、O(h) 递归栈。边界：数据里存在&quot;孤儿节点&quot;（父 id 找不到）时应作为根节点或收集到异常列表，不能静默丢弃；数据可能有多棵树（森林），结果是数组而不是单根对象；<code>parentId === rootId</code> 要单独判断，否则根节点会被挂到虚拟根上形成环。</li><li>前端真实坑：直接改原对象会污染上游数据，所以要浅拷贝；很多 UI 组件（如 <code>el-tree</code>）对空 <code>children</code> 仍会渲染展开箭头，所以常在末尾把空 <code>children</code> 删掉。</li><li>反向场景：级联选择器拿到的是选中节点的 id 数组，需要根据 <code>parentId</code> 链向上回溯出完整路径，本质是&quot;用 Map 反查父节点&quot;的向上遍历。</li></ol><div class="language-javascript line-numbers-mode" data-ext="js"><pre class="language-javascript"><code><span class="token comment">// 扁平 -&gt; 树：O(n) 哈希法（res 为根节点集合，支持森林）</span>
<span class="token keyword">function</span> <span class="token function">listToTree</span><span class="token punctuation">(</span><span class="token parameter">list<span class="token punctuation">,</span> rootId <span class="token operator">=</span> <span class="token keyword">null</span></span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
  <span class="token keyword">const</span> map <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token class-name">Map</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">,</span> res <span class="token operator">=</span> <span class="token punctuation">[</span><span class="token punctuation">]</span><span class="token punctuation">;</span>
  <span class="token keyword">for</span> <span class="token punctuation">(</span><span class="token keyword">const</span> item <span class="token keyword">of</span> list<span class="token punctuation">)</span> map<span class="token punctuation">.</span><span class="token function">set</span><span class="token punctuation">(</span>item<span class="token punctuation">.</span>id<span class="token punctuation">,</span> <span class="token punctuation">{</span> <span class="token operator">...</span>item<span class="token punctuation">,</span> <span class="token literal-property property">children</span><span class="token operator">:</span> <span class="token punctuation">[</span><span class="token punctuation">]</span> <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token comment">// 先建映射</span>
  <span class="token keyword">for</span> <span class="token punctuation">(</span><span class="token keyword">const</span> item <span class="token keyword">of</span> list<span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token keyword">const</span> node <span class="token operator">=</span> map<span class="token punctuation">.</span><span class="token function">get</span><span class="token punctuation">(</span>item<span class="token punctuation">.</span>id<span class="token punctuation">)</span><span class="token punctuation">,</span> parent <span class="token operator">=</span> map<span class="token punctuation">.</span><span class="token function">get</span><span class="token punctuation">(</span>item<span class="token punctuation">.</span>parentId<span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token comment">// 自引用（parentId === id）要按根处理，否则会被静默丢弃并形成自环</span>
    <span class="token keyword">if</span> <span class="token punctuation">(</span>parent <span class="token operator">&amp;&amp;</span> item<span class="token punctuation">.</span>parentId <span class="token operator">!==</span> rootId <span class="token operator">&amp;&amp;</span> item<span class="token punctuation">.</span>parentId <span class="token operator">!==</span> item<span class="token punctuation">.</span>id<span class="token punctuation">)</span> parent<span class="token punctuation">.</span>children<span class="token punctuation">.</span><span class="token function">push</span><span class="token punctuation">(</span>node<span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token keyword">else</span> res<span class="token punctuation">.</span><span class="token function">push</span><span class="token punctuation">(</span>node<span class="token punctuation">)</span><span class="token punctuation">;</span>                       <span class="token comment">// 无父或父为根 =&gt; 森林的根</span>
  <span class="token punctuation">}</span>
  <span class="token keyword">return</span> res<span class="token punctuation">;</span>
<span class="token punctuation">}</span>
<span class="token comment">// 树 -&gt; 扁平：DFS 携带父 id 与层级</span>
<span class="token keyword">function</span> <span class="token function">treeToList</span><span class="token punctuation">(</span><span class="token parameter">tree<span class="token punctuation">,</span> parentId <span class="token operator">=</span> <span class="token keyword">null</span><span class="token punctuation">,</span> level <span class="token operator">=</span> <span class="token number">0</span><span class="token punctuation">,</span> out <span class="token operator">=</span> <span class="token punctuation">[</span><span class="token punctuation">]</span></span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
  <span class="token keyword">for</span> <span class="token punctuation">(</span><span class="token keyword">const</span> node <span class="token keyword">of</span> tree<span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token keyword">const</span> <span class="token punctuation">{</span> children<span class="token punctuation">,</span> <span class="token operator">...</span>rest <span class="token punctuation">}</span> <span class="token operator">=</span> node<span class="token punctuation">;</span>        <span class="token comment">// 剔除 children</span>
    out<span class="token punctuation">.</span><span class="token function">push</span><span class="token punctuation">(</span><span class="token punctuation">{</span> <span class="token operator">...</span>rest<span class="token punctuation">,</span> parentId<span class="token punctuation">,</span> level <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token keyword">if</span> <span class="token punctuation">(</span>children <span class="token operator">&amp;&amp;</span> children<span class="token punctuation">.</span>length<span class="token punctuation">)</span> <span class="token function">treeToList</span><span class="token punctuation">(</span>children<span class="token punctuation">,</span> node<span class="token punctuation">.</span>id<span class="token punctuation">,</span> level <span class="token operator">+</span> <span class="token number">1</span><span class="token punctuation">,</span> out<span class="token punctuation">)</span><span class="token punctuation">;</span>
  <span class="token punctuation">}</span>
  <span class="token keyword">return</span> out<span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>追问与易错点</strong>：</p><ul><li>追问：为什么推荐 <code>Map</code> 而不是普通对象做映射？答：<code>Map</code> 的 key 支持任意类型且没有原型链污染（<code>id</code> 恰好叫 <code>constructor</code> 时普通对象会出错），<code>get</code>/<code>set</code> 也是 O(1)。</li><li>追问：树很深（几万层）怎么办？答：递归会爆栈，改成&quot;显式栈 + while 循环&quot;的迭代 DFS，或分片处理（<code>requestIdleCallback</code> / 虚拟滚动），避免长任务阻塞主线程。</li><li>陷阱：<code>list.filter(x =&gt; x.parentId === id)</code> 的 O(n²) 写法；忘记 <code>parentId === rootId</code> 判断导致根节点被挂到虚拟根上形成环。</li></ul><h3 id="q22-前端真实业务算法-对象深比较和两个数组-diff-怎么写" tabindex="-1"><a class="header-anchor" href="#q22-前端真实业务算法-对象深比较和两个数组-diff-怎么写" aria-hidden="true">#</a> Q22 前端真实业务算法：对象深比较和两个数组 diff 怎么写？</h3><p><strong>考察点</strong>：考递归比较的完备性（循环引用、<code>NaN</code>、<code>Date</code>），以及&quot;对象数组必须按业务主键比较&quot;这一现实约束。</p><p><strong>参考答案</strong>：</p><blockquote><p><strong>一句话结论</strong>：深比较先比引用与类型，再分情况处理日期、正则、<code>Map/Set</code>，最后递归比较自有可枚举键，并用 <code>WeakMap</code> 记录已访问对象处理循环引用；数组 diff 要按业务主键建 <code>Map</code>，输出&quot;新增 / 删除 / 修改&quot;三类差异，不能直接比较对象引用。</p></blockquote><ol><li>深比较的快速失败：<code>a === b</code> 直接 <code>true</code>（覆盖同一引用与原始值）；<code>NaN === NaN</code> 是 <code>false</code>，要用 <code>Number.isNaN</code> 特判；一方为 <code>null</code>/非对象则判定不等。</li><li>类型检查：用 <code>Object.getPrototypeOf(a) !== Object.getPrototypeOf(b)</code> 判断&quot;不同构造函数的实例不等&quot;，避免把 <code>[]</code> 和 <code>{}</code> 混为一谈。</li><li>分类型处理：<code>Date</code> 比 <code>getTime()</code>；<code>RegExp</code> 比 <code>source</code> 与 <code>flags</code>；数组先比 <code>length</code> 再逐项递归；对象先比键数量再逐键递归。<code>Map</code>/<code>Set</code> 需要双向检查元素存在性。</li><li>循环引用：用 <code>WeakMap</code> 存&quot;正在比较的对象对&quot;，命中就直接返回 <code>true</code>，切断无限递归；用 <code>WeakMap</code> 而非 <code>Map</code> 是为了不阻止对象被 GC。</li><li>原始值差集：<code>a.filter(x =&gt; !setB.has(x))</code>，把内层 O(m) 的 <code>includes</code> 降到 O(1)，整体从 O(n·m) 降到 O(n+m)；对称差集就是把两个方向的结果拼起来。</li><li><strong>复杂度与边界</strong>：深比较时间 O(节点数)、空间 O(深度 + 已访问对)；差集 O(n+m)。边界：<code>{a:1}</code> 与 <code>{b:1}</code> 必须判不等（要比键名集合而不只是值）；<code>Set</code> 对对象数组无效（按引用比较）；对象数组 diff 要按 <code>id</code> 而不是引用。</li></ol><div class="language-javascript line-numbers-mode" data-ext="js"><pre class="language-javascript"><code><span class="token comment">// 深比较：比引用 -&gt; 比类型 -&gt; WeakMap 防循环引用 -&gt; 递归比键与值</span>
<span class="token keyword">function</span> <span class="token function">deepEqual</span><span class="token punctuation">(</span>a<span class="token punctuation">,</span> b<span class="token punctuation">,</span> seen <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token class-name">WeakMap</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
  <span class="token keyword">if</span> <span class="token punctuation">(</span>a <span class="token operator">===</span> b<span class="token punctuation">)</span> <span class="token keyword">return</span> <span class="token boolean">true</span><span class="token punctuation">;</span>
  <span class="token keyword">if</span> <span class="token punctuation">(</span>Number<span class="token punctuation">.</span><span class="token function">isNaN</span><span class="token punctuation">(</span>a<span class="token punctuation">)</span> <span class="token operator">&amp;&amp;</span> Number<span class="token punctuation">.</span><span class="token function">isNaN</span><span class="token punctuation">(</span>b<span class="token punctuation">)</span><span class="token punctuation">)</span> <span class="token keyword">return</span> <span class="token boolean">true</span><span class="token punctuation">;</span>   <span class="token comment">// NaN 特判</span>
  <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token keyword">typeof</span> a <span class="token operator">!==</span> <span class="token string">&#39;object&#39;</span> <span class="token operator">||</span> <span class="token keyword">typeof</span> b <span class="token operator">!==</span> <span class="token string">&#39;object&#39;</span> <span class="token operator">||</span> <span class="token operator">!</span>a <span class="token operator">||</span> <span class="token operator">!</span>b<span class="token punctuation">)</span> <span class="token keyword">return</span> <span class="token boolean">false</span><span class="token punctuation">;</span>
  <span class="token keyword">if</span> <span class="token punctuation">(</span>Object<span class="token punctuation">.</span><span class="token function">getPrototypeOf</span><span class="token punctuation">(</span>a<span class="token punctuation">)</span> <span class="token operator">!==</span> Object<span class="token punctuation">.</span><span class="token function">getPrototypeOf</span><span class="token punctuation">(</span>b<span class="token punctuation">)</span><span class="token punctuation">)</span> <span class="token keyword">return</span> <span class="token boolean">false</span><span class="token punctuation">;</span>
  <span class="token keyword">if</span> <span class="token punctuation">(</span>seen<span class="token punctuation">.</span><span class="token function">get</span><span class="token punctuation">(</span>a<span class="token punctuation">)</span> <span class="token operator">===</span> b<span class="token punctuation">)</span> <span class="token keyword">return</span> <span class="token boolean">true</span><span class="token punctuation">;</span>                    <span class="token comment">// 循环引用已比较过</span>
  seen<span class="token punctuation">.</span><span class="token function">set</span><span class="token punctuation">(</span>a<span class="token punctuation">,</span> b<span class="token punctuation">)</span><span class="token punctuation">;</span>
  <span class="token keyword">if</span> <span class="token punctuation">(</span>a <span class="token keyword">instanceof</span> <span class="token class-name">Date</span><span class="token punctuation">)</span> <span class="token keyword">return</span> a<span class="token punctuation">.</span><span class="token function">getTime</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">===</span> b<span class="token punctuation">.</span><span class="token function">getTime</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
  <span class="token keyword">if</span> <span class="token punctuation">(</span>a <span class="token keyword">instanceof</span> <span class="token class-name">RegExp</span><span class="token punctuation">)</span> <span class="token keyword">return</span> a<span class="token punctuation">.</span>source <span class="token operator">===</span> b<span class="token punctuation">.</span>source <span class="token operator">&amp;&amp;</span> a<span class="token punctuation">.</span>flags <span class="token operator">===</span> b<span class="token punctuation">.</span>flags<span class="token punctuation">;</span> <span class="token comment">// 正则比 source + flags</span>
  <span class="token keyword">if</span> <span class="token punctuation">(</span>a <span class="token keyword">instanceof</span> <span class="token class-name">Map</span> <span class="token operator">||</span> a <span class="token keyword">instanceof</span> <span class="token class-name">Set</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>   <span class="token comment">// Map/Set 的内容不在自有属性上，必须按元素双向查存在性</span>
    <span class="token keyword">if</span> <span class="token punctuation">(</span>a<span class="token punctuation">.</span>size <span class="token operator">!==</span> b<span class="token punctuation">.</span>size<span class="token punctuation">)</span> <span class="token keyword">return</span> <span class="token boolean">false</span><span class="token punctuation">;</span>
    <span class="token keyword">const</span> eb <span class="token operator">=</span> <span class="token punctuation">[</span><span class="token operator">...</span>b<span class="token punctuation">]</span><span class="token punctuation">;</span>
    <span class="token keyword">return</span> <span class="token punctuation">[</span><span class="token operator">...</span>a<span class="token punctuation">]</span><span class="token punctuation">.</span><span class="token function">every</span><span class="token punctuation">(</span><span class="token punctuation">(</span><span class="token parameter">x</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> eb<span class="token punctuation">.</span><span class="token function">some</span><span class="token punctuation">(</span><span class="token punctuation">(</span><span class="token parameter">y</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token function">deepEqual</span><span class="token punctuation">(</span>x<span class="token punctuation">,</span> y<span class="token punctuation">,</span> seen<span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
  <span class="token punctuation">}</span>
  <span class="token keyword">const</span> ka <span class="token operator">=</span> Reflect<span class="token punctuation">.</span><span class="token function">ownKeys</span><span class="token punctuation">(</span>a<span class="token punctuation">)</span><span class="token punctuation">,</span> kb <span class="token operator">=</span> Reflect<span class="token punctuation">.</span><span class="token function">ownKeys</span><span class="token punctuation">(</span>b<span class="token punctuation">)</span><span class="token punctuation">;</span>
  <span class="token keyword">return</span> ka<span class="token punctuation">.</span>length <span class="token operator">===</span> kb<span class="token punctuation">.</span>length <span class="token operator">&amp;&amp;</span> ka<span class="token punctuation">.</span><span class="token function">every</span><span class="token punctuation">(</span><span class="token punctuation">(</span><span class="token parameter">k</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token function">deepEqual</span><span class="token punctuation">(</span>a<span class="token punctuation">[</span>k<span class="token punctuation">]</span><span class="token punctuation">,</span> b<span class="token punctuation">[</span>k<span class="token punctuation">]</span><span class="token punctuation">,</span> seen<span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
<span class="token comment">// 对象数组 diff：按 id 建索引，输出新增 / 删除 / 修改</span>
<span class="token keyword">function</span> <span class="token function">diffById</span><span class="token punctuation">(</span><span class="token parameter">prev<span class="token punctuation">,</span> next</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
  <span class="token keyword">const</span> prevMap <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token class-name">Map</span><span class="token punctuation">(</span>prev<span class="token punctuation">.</span><span class="token function">map</span><span class="token punctuation">(</span><span class="token punctuation">(</span><span class="token parameter">i</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span>i<span class="token punctuation">.</span>id<span class="token punctuation">,</span> i<span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
  <span class="token keyword">const</span> added <span class="token operator">=</span> <span class="token punctuation">[</span><span class="token punctuation">]</span><span class="token punctuation">,</span> updated <span class="token operator">=</span> <span class="token punctuation">[</span><span class="token punctuation">]</span><span class="token punctuation">,</span> nextIds <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token class-name">Set</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
  <span class="token keyword">for</span> <span class="token punctuation">(</span><span class="token keyword">const</span> item <span class="token keyword">of</span> next<span class="token punctuation">)</span> <span class="token punctuation">{</span>
    nextIds<span class="token punctuation">.</span><span class="token function">add</span><span class="token punctuation">(</span>item<span class="token punctuation">.</span>id<span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token keyword">const</span> old <span class="token operator">=</span> prevMap<span class="token punctuation">.</span><span class="token function">get</span><span class="token punctuation">(</span>item<span class="token punctuation">.</span>id<span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token operator">!</span>old<span class="token punctuation">)</span> added<span class="token punctuation">.</span><span class="token function">push</span><span class="token punctuation">(</span>item<span class="token punctuation">)</span><span class="token punctuation">;</span>                            <span class="token comment">// 新增</span>
    <span class="token keyword">else</span> <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token constant">JSON</span><span class="token punctuation">.</span><span class="token function">stringify</span><span class="token punctuation">(</span>old<span class="token punctuation">)</span> <span class="token operator">!==</span> <span class="token constant">JSON</span><span class="token punctuation">.</span><span class="token function">stringify</span><span class="token punctuation">(</span>item<span class="token punctuation">)</span><span class="token punctuation">)</span> updated<span class="token punctuation">.</span><span class="token function">push</span><span class="token punctuation">(</span>item<span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token comment">// 修改</span>
  <span class="token punctuation">}</span>
  <span class="token keyword">return</span> <span class="token punctuation">{</span> added<span class="token punctuation">,</span> updated<span class="token punctuation">,</span> <span class="token literal-property property">removed</span><span class="token operator">:</span> prev<span class="token punctuation">.</span><span class="token function">filter</span><span class="token punctuation">(</span><span class="token punctuation">(</span><span class="token parameter">i</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token operator">!</span>nextIds<span class="token punctuation">.</span><span class="token function">has</span><span class="token punctuation">(</span>i<span class="token punctuation">.</span>id<span class="token punctuation">)</span><span class="token punctuation">)</span> <span class="token punctuation">}</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>追问与易错点</strong>：</p><ul><li>追问：<code>JSON.stringify</code> 比对的坑有哪些？答：键顺序不同会判不等；<code>undefined</code>、函数、<code>Symbol</code> 会被丢弃；<code>Date</code> 被转成字符串失去类型；循环引用直接抛错；<code>NaN</code> 变 <code>null</code>。</li><li>追问：为什么不用 <code>JSON.stringify</code> 做整体 diff？答：它只能判&quot;整体是否相同&quot;，拿不到&quot;哪个字段变了&quot;，也无法区分新增与删除，只适合做廉价的&quot;是否变化&quot;判断。</li><li>陷阱：只递归比较&quot;值&quot;却忘记比较<strong>键名集合</strong>，导致 <code>{a:1}</code> 与 <code>{b:1}</code> 被判相等；<code>a.filter(x =&gt; !b.includes(x))</code> 在几千条数据时明显卡顿。</li></ul><h3 id="q23-前端真实业务算法-多字段排序与中文排序、版本号比较怎么做" tabindex="-1"><a class="header-anchor" href="#q23-前端真实业务算法-多字段排序与中文排序、版本号比较怎么做" aria-hidden="true">#</a> Q23 前端真实业务算法：多字段排序与中文排序、版本号比较怎么做？</h3><p><strong>考察点</strong>：考复合比较器的写法、中文拼音排序与 UTF-16 编码排序的差异，以及版本号必须转数字比较这一细节。</p><p><strong>参考答案</strong>：</p><blockquote><p><strong>一句话结论</strong>：多字段排序用一个&quot;逐字段比较、首个不等即返回&quot;的复合比较器；中文排序必须用 <code>localeCompare(&#39;zh-Hans-CN&#39;, { numeric: true })</code> 或复用的 <code>Intl.Collator</code>，直接用 <code>&lt;</code> 会按 UTF-16 码元排序；版本号按 <code>.</code> 切段后必须转数字比较，否则 <code>&#39;10&#39; &lt; &#39;9&#39;</code> 成立。</p></blockquote><ol><li>复合比较器骨架：遍历排序字段列表，逐字段取值比较；结果非 0 就按该字段的 <code>order</code> 乘上方向系数返回，全相等返回 0。比较器<strong>必须返回数字</strong>，返回 <code>true/false</code> 会被转成 <code>1/0</code>，永远给不出负数。</li><li>中文排序原理：JS 的 <code>&#39;张&#39; &lt; &#39;李&#39;</code> 比较的是 UTF-16 码元值，与拼音无关；<code>localeCompare</code> 走国际化排序规则（按汉语拼音），<code>{ numeric: true }</code> 还能让 <code>&quot;file10&quot;</code> 排在 <code>&quot;file2&quot;</code> 之后（自然排序）。</li><li>性能要点：<code>Intl.Collator</code> 的实例化开销大，必须在排序函数<strong>外面</strong>创建一次并复用 <code>collator.compare</code>；每次比较都 <code>new Intl.Collator()</code> 会慢几十倍。</li><li><code>sort</code> 稳定性（ES2019 起规范保证）意味着&quot;先按次要字段排一次、再按主要字段排一次&quot;也能得到多字段结果，但复合比较器只需一次排序、语义更直白。</li><li>版本号比较：先用 <code>-</code> 拆出预发布标识，主版本再按 <code>.</code> 切分并 <code>map(Number)</code>，缺失段补 0，逐段比较首个不等即返回；要剥掉 <code>v</code> 前缀。<strong>注意</strong><code>map(Number)</code> 会把 <code>&#39;0-beta&#39;</code> 变成 <code>NaN</code> 导致比较失效，所以预发布标识必须切开后单独判断——按语义化版本（SemVer）规则，带预发布标识的版本<strong>小于</strong>对应正式版本。</li><li><strong>复杂度与边界</strong>：排序 O(n log n·字段数)、空间 O(n)（<code>[...list]</code> 拷贝）；版本号 O(段数)、空间 O(段数)。边界：<code>null</code>/<code>undefined</code> 参与比较会得到 <code>NaN</code> 导致结果不可预测，要先归一化；空数组、单元素数组要能直接返回；<code>1.0</code> 与 <code>1.0.0</code> 按补 0 规则判等。</li></ol><div class="language-javascript line-numbers-mode" data-ext="js"><pre class="language-javascript"><code><span class="token comment">// 多字段排序：逐字段比较，首个不等字段决定顺序（collator 只建一次）</span>
<span class="token keyword">const</span> collator <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token class-name">Intl<span class="token punctuation">.</span>Collator</span><span class="token punctuation">(</span><span class="token string">&#39;zh-Hans-CN&#39;</span><span class="token punctuation">,</span> <span class="token punctuation">{</span> <span class="token literal-property property">numeric</span><span class="token operator">:</span> <span class="token boolean">true</span> <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token keyword">function</span> <span class="token function">multiSort</span><span class="token punctuation">(</span><span class="token parameter">list<span class="token punctuation">,</span> fields</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
  <span class="token keyword">return</span> <span class="token punctuation">[</span><span class="token operator">...</span>list<span class="token punctuation">]</span><span class="token punctuation">.</span><span class="token function">sort</span><span class="token punctuation">(</span><span class="token punctuation">(</span><span class="token parameter">a<span class="token punctuation">,</span> b</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token punctuation">{</span>
    <span class="token keyword">for</span> <span class="token punctuation">(</span><span class="token keyword">const</span> <span class="token punctuation">{</span> key<span class="token punctuation">,</span> order <span class="token operator">=</span> <span class="token string">&#39;asc&#39;</span> <span class="token punctuation">}</span> <span class="token keyword">of</span> fields<span class="token punctuation">)</span> <span class="token punctuation">{</span>
      <span class="token keyword">const</span> va <span class="token operator">=</span> a<span class="token punctuation">[</span>key<span class="token punctuation">]</span> <span class="token operator">??</span> <span class="token string">&#39;&#39;</span><span class="token punctuation">,</span> vb <span class="token operator">=</span> b<span class="token punctuation">[</span>key<span class="token punctuation">]</span> <span class="token operator">??</span> <span class="token string">&#39;&#39;</span><span class="token punctuation">;</span>       <span class="token comment">// 空值归一化</span>
      <span class="token keyword">const</span> r <span class="token operator">=</span> <span class="token keyword">typeof</span> va <span class="token operator">===</span> <span class="token string">&#39;string&#39;</span> <span class="token operator">||</span> <span class="token keyword">typeof</span> vb <span class="token operator">===</span> <span class="token string">&#39;string&#39;</span>
        <span class="token operator">?</span> collator<span class="token punctuation">.</span><span class="token function">compare</span><span class="token punctuation">(</span><span class="token function">String</span><span class="token punctuation">(</span>va<span class="token punctuation">)</span><span class="token punctuation">,</span> <span class="token function">String</span><span class="token punctuation">(</span>vb<span class="token punctuation">)</span><span class="token punctuation">)</span>
        <span class="token operator">:</span> <span class="token punctuation">(</span>va <span class="token operator">&gt;</span> vb <span class="token operator">?</span> <span class="token number">1</span> <span class="token operator">:</span> va <span class="token operator">&lt;</span> vb <span class="token operator">?</span> <span class="token operator">-</span><span class="token number">1</span> <span class="token operator">:</span> <span class="token number">0</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
      <span class="token keyword">if</span> <span class="token punctuation">(</span>r <span class="token operator">!==</span> <span class="token number">0</span><span class="token punctuation">)</span> <span class="token keyword">return</span> r <span class="token operator">*</span> <span class="token punctuation">(</span>order <span class="token operator">===</span> <span class="token string">&#39;desc&#39;</span> <span class="token operator">?</span> <span class="token operator">-</span><span class="token number">1</span> <span class="token operator">:</span> <span class="token number">1</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>
    <span class="token keyword">return</span> <span class="token number">0</span><span class="token punctuation">;</span>                                           <span class="token comment">// 全相等：保持稳定次序</span>
  <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
<span class="token comment">// 版本号比较：先拆预发布标识，再逐段比数字；预发布小于正式版</span>
<span class="token keyword">function</span> <span class="token function">compareVersion</span><span class="token punctuation">(</span><span class="token parameter">v1<span class="token punctuation">,</span> v2</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
  <span class="token keyword">const</span> <span class="token punctuation">[</span>c1<span class="token punctuation">,</span> pre1<span class="token punctuation">]</span> <span class="token operator">=</span> <span class="token function">String</span><span class="token punctuation">(</span>v1<span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">replace</span><span class="token punctuation">(</span><span class="token regex"><span class="token regex-delimiter">/</span><span class="token regex-source language-regex">^v</span><span class="token regex-delimiter">/</span><span class="token regex-flags">i</span></span><span class="token punctuation">,</span> <span class="token string">&#39;&#39;</span><span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">split</span><span class="token punctuation">(</span><span class="token string">&#39;-&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
  <span class="token keyword">const</span> <span class="token punctuation">[</span>c2<span class="token punctuation">,</span> pre2<span class="token punctuation">]</span> <span class="token operator">=</span> <span class="token function">String</span><span class="token punctuation">(</span>v2<span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">replace</span><span class="token punctuation">(</span><span class="token regex"><span class="token regex-delimiter">/</span><span class="token regex-source language-regex">^v</span><span class="token regex-delimiter">/</span><span class="token regex-flags">i</span></span><span class="token punctuation">,</span> <span class="token string">&#39;&#39;</span><span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">split</span><span class="token punctuation">(</span><span class="token string">&#39;-&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
  <span class="token keyword">const</span> a <span class="token operator">=</span> c1<span class="token punctuation">.</span><span class="token function">split</span><span class="token punctuation">(</span><span class="token string">&#39;.&#39;</span><span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">map</span><span class="token punctuation">(</span>Number<span class="token punctuation">)</span><span class="token punctuation">,</span> b <span class="token operator">=</span> c2<span class="token punctuation">.</span><span class="token function">split</span><span class="token punctuation">(</span><span class="token string">&#39;.&#39;</span><span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">map</span><span class="token punctuation">(</span>Number<span class="token punctuation">)</span><span class="token punctuation">;</span>
  <span class="token keyword">for</span> <span class="token punctuation">(</span><span class="token keyword">let</span> i <span class="token operator">=</span> <span class="token number">0</span><span class="token punctuation">;</span> i <span class="token operator">&lt;</span> Math<span class="token punctuation">.</span><span class="token function">max</span><span class="token punctuation">(</span>a<span class="token punctuation">.</span>length<span class="token punctuation">,</span> b<span class="token punctuation">.</span>length<span class="token punctuation">)</span><span class="token punctuation">;</span> i<span class="token operator">++</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token keyword">const</span> x <span class="token operator">=</span> a<span class="token punctuation">[</span>i<span class="token punctuation">]</span> <span class="token operator">||</span> <span class="token number">0</span><span class="token punctuation">,</span> y <span class="token operator">=</span> b<span class="token punctuation">[</span>i<span class="token punctuation">]</span> <span class="token operator">||</span> <span class="token number">0</span><span class="token punctuation">;</span>   <span class="token comment">// 缺失段补 0</span>
    <span class="token keyword">if</span> <span class="token punctuation">(</span>x <span class="token operator">!==</span> y<span class="token punctuation">)</span> <span class="token keyword">return</span> x <span class="token operator">&gt;</span> y <span class="token operator">?</span> <span class="token number">1</span> <span class="token operator">:</span> <span class="token operator">-</span><span class="token number">1</span><span class="token punctuation">;</span>
  <span class="token punctuation">}</span>
  <span class="token keyword">if</span> <span class="token punctuation">(</span>pre1 <span class="token operator">===</span> pre2<span class="token punctuation">)</span> <span class="token keyword">return</span> <span class="token number">0</span><span class="token punctuation">;</span>
  <span class="token keyword">return</span> <span class="token operator">!</span>pre1 <span class="token operator">?</span> <span class="token number">1</span> <span class="token operator">:</span> <span class="token operator">!</span>pre2 <span class="token operator">?</span> <span class="token operator">-</span><span class="token number">1</span> <span class="token operator">:</span> <span class="token punctuation">(</span>pre1 <span class="token operator">&gt;</span> pre2 <span class="token operator">?</span> <span class="token number">1</span> <span class="token operator">:</span> <span class="token operator">-</span><span class="token number">1</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>追问与易错点</strong>：</p><ul><li>追问：为什么 <code>&#39;10&#39; &lt; &#39;9&#39;</code> 是 <code>true</code>？答：字符串按 UTF-16 码元逐位比较，<code>&#39;1&#39;</code> 的码元小于 <code>&#39;9&#39;</code>，所以字典序判定为小；版本号与数字比较必须先转数字。</li><li>追问：<code>localeCompare</code> 和 <code>Intl.Collator</code> 怎么选？答：只排少量数据用 <code>localeCompare</code> 更省事；排序字段固定且数据量大时用 <code>Intl.Collator</code> 复用实例，性能明显更好。</li><li>陷阱：中文排序直接用 <code>a.name &gt; b.name ? 1 : -1</code>；版本号用字符串比较；不先切出预发布标识就用 <code>map(Number)</code> 解析，<code>&#39;0-beta&#39;</code> 变成 <code>NaN</code> 让整段比较静默失效。</li></ul><h3 id="q24-前端真实业务算法-区间合并、会议时间冲突检测、时间格式化怎么做" tabindex="-1"><a class="header-anchor" href="#q24-前端真实业务算法-区间合并、会议时间冲突检测、时间格式化怎么做" aria-hidden="true">#</a> Q24 前端真实业务算法：区间合并、会议时间冲突检测、时间格式化怎么做？</h3><p><strong>考察点</strong>：考排序 + 区间扫描这一通用模式，以及时间点比较、跨天、相邻区间是否合并等业务边界。</p><p><strong>参考答案</strong>：</p><blockquote><p><strong>一句话结论</strong>：区间合并先按<strong>起始时间升序排序</strong>，再线性扫描：若当前区间起点 ≤ 上一个合并区间的终点就合并（终点取两者最大），否则另起一段；时间 O(n log n)、空间 O(n)。</p></blockquote><ol><li>为什么必须先排序：只有按起点有序，才能保证&quot;当前区间一定与已有结果里最后一段相邻&quot;，从而只需比较最后一次结果，不需要回头检查。</li><li>合并判定：<code>cur.start &lt;= last.end</code> 就合并，<code>last.end = max(last.end, cur.end)</code>。<strong>取 max 不能省</strong>——<code>[1,10]</code> 与 <code>[2,3]</code> 合并时若直接取 <code>cur.end</code>，结果会被错误截短为 <code>[1,3]</code>。</li><li>相邻不算重叠：<code>[1,2]</code> 与 <code>[2,3]</code> 是否合并取决于业务（&quot;紧邻的两个会议&quot;通常不算冲突），所以判定用 <code>&lt;=</code> 还是 <code>&lt;</code> 要按需求定，这是最常被追问的细节。冲突检测的通用式子是两个区间是否满足 <code>a.start &lt; b.end &amp;&amp; b.start &lt; a.end</code>。</li><li>时间比较：统一转成时间戳（<code>Date.parse</code> 或 <code>getTime()</code>）比较最稳；<code>&#39;09:00&#39;</code> 这种纯时间字符串不能直接做算术，直接按字典序比大小也只对补零且同一天的时间成立，跨天或漏补零（如 <code>&#39;9:00&#39;</code> 与 <code>&#39;10:00&#39;</code>）就会错，要么补上日期、要么切成&quot;当天分钟数&quot;。</li><li><strong>复杂度与边界</strong>：排序 O(n log n) 是瓶颈，扫描本身 O(n)，空间 O(n)（结果数组）。边界：空数组与单区间要直接返回；不要原地修改传入数组（<code>sort</code> 与 <code>last[1] = ...</code> 都会改），要浅拷贝；时间格式化要注意 <code>getMonth()</code> 从 0 开始、<code>new Date(&#39;2024-01-01&#39;)</code> 按 UTC 解析而 <code>new Date(&#39;2024/01/01&#39;)</code> 按本地时区解析，跨时区会差一天。</li><li>业务延伸：日程表空闲时段 = 合并后的忙碌区间的补集；甘特图按资源分组后各自合并。</li></ol><div class="language-javascript line-numbers-mode" data-ext="js"><pre class="language-javascript"><code><span class="token comment">// 合并区间（会议时间合并）：intervals = [[1,3],[2,6],[8,10],[15,18]]</span>
<span class="token keyword">function</span> <span class="token function">mergeIntervals</span><span class="token punctuation">(</span><span class="token parameter">intervals</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
  <span class="token keyword">if</span> <span class="token punctuation">(</span>intervals<span class="token punctuation">.</span>length <span class="token operator">&lt;=</span> <span class="token number">1</span><span class="token punctuation">)</span> <span class="token keyword">return</span> intervals<span class="token punctuation">.</span><span class="token function">slice</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
  <span class="token keyword">const</span> sorted <span class="token operator">=</span> <span class="token punctuation">[</span><span class="token operator">...</span>intervals<span class="token punctuation">]</span><span class="token punctuation">.</span><span class="token function">sort</span><span class="token punctuation">(</span><span class="token punctuation">(</span><span class="token parameter">a<span class="token punctuation">,</span> b</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> a<span class="token punctuation">[</span><span class="token number">0</span><span class="token punctuation">]</span> <span class="token operator">-</span> b<span class="token punctuation">[</span><span class="token number">0</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token comment">// 按起点升序</span>
  <span class="token keyword">const</span> res <span class="token operator">=</span> <span class="token punctuation">[</span>sorted<span class="token punctuation">[</span><span class="token number">0</span><span class="token punctuation">]</span><span class="token punctuation">.</span><span class="token function">slice</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">]</span><span class="token punctuation">;</span>
  <span class="token keyword">for</span> <span class="token punctuation">(</span><span class="token keyword">let</span> i <span class="token operator">=</span> <span class="token number">1</span><span class="token punctuation">;</span> i <span class="token operator">&lt;</span> sorted<span class="token punctuation">.</span>length<span class="token punctuation">;</span> i<span class="token operator">++</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token keyword">const</span> last <span class="token operator">=</span> res<span class="token punctuation">[</span>res<span class="token punctuation">.</span>length <span class="token operator">-</span> <span class="token number">1</span><span class="token punctuation">]</span><span class="token punctuation">,</span> cur <span class="token operator">=</span> sorted<span class="token punctuation">[</span>i<span class="token punctuation">]</span><span class="token punctuation">;</span>
    <span class="token keyword">if</span> <span class="token punctuation">(</span>cur<span class="token punctuation">[</span><span class="token number">0</span><span class="token punctuation">]</span> <span class="token operator">&lt;=</span> last<span class="token punctuation">[</span><span class="token number">1</span><span class="token punctuation">]</span><span class="token punctuation">)</span> last<span class="token punctuation">[</span><span class="token number">1</span><span class="token punctuation">]</span> <span class="token operator">=</span> Math<span class="token punctuation">.</span><span class="token function">max</span><span class="token punctuation">(</span>last<span class="token punctuation">[</span><span class="token number">1</span><span class="token punctuation">]</span><span class="token punctuation">,</span> cur<span class="token punctuation">[</span><span class="token number">1</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token comment">// 重叠须取最大终点</span>
    <span class="token keyword">else</span> res<span class="token punctuation">.</span><span class="token function">push</span><span class="token punctuation">(</span>cur<span class="token punctuation">.</span><span class="token function">slice</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span>                                <span class="token comment">// 无重叠，另起一段</span>
  <span class="token punctuation">}</span>
  <span class="token keyword">return</span> res<span class="token punctuation">;</span>
<span class="token punctuation">}</span>
<span class="token comment">// 判断两个区间是否重叠（会议冲突检测）</span>
<span class="token keyword">const</span> <span class="token function-variable function">isOverlap</span> <span class="token operator">=</span> <span class="token punctuation">(</span><span class="token parameter">a<span class="token punctuation">,</span> b</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> a<span class="token punctuation">[</span><span class="token number">0</span><span class="token punctuation">]</span> <span class="token operator">&lt;</span> b<span class="token punctuation">[</span><span class="token number">1</span><span class="token punctuation">]</span> <span class="token operator">&amp;&amp;</span> b<span class="token punctuation">[</span><span class="token number">0</span><span class="token punctuation">]</span> <span class="token operator">&lt;</span> a<span class="token punctuation">[</span><span class="token number">1</span><span class="token punctuation">]</span><span class="token punctuation">;</span>
<span class="token comment">// 相对时间：Intl.RelativeTimeFormat 免去手写补零与月份偏移</span>
<span class="token keyword">const</span> rtf <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token class-name">Intl<span class="token punctuation">.</span>RelativeTimeFormat</span><span class="token punctuation">(</span><span class="token string">&#39;zh-CN&#39;</span><span class="token punctuation">,</span> <span class="token punctuation">{</span> <span class="token literal-property property">numeric</span><span class="token operator">:</span> <span class="token string">&#39;auto&#39;</span> <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token keyword">const</span> <span class="token function-variable function">minutesAgo</span> <span class="token operator">=</span> <span class="token punctuation">(</span><span class="token parameter">m</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> rtf<span class="token punctuation">.</span><span class="token function">format</span><span class="token punctuation">(</span><span class="token operator">-</span>m<span class="token punctuation">,</span> <span class="token string">&#39;minute&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token comment">// &quot;3 分钟前&quot;</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>追问与易错点</strong>：</p><ul><li>追问：为什么不拷贝就直接改 <code>intervals</code> 里的元素？答：<code>sort</code> 与 <code>last[1] = ...</code> 都会修改传入的数组，会污染调用方数据（React 里还可能因为引用不变导致不重渲染），所以要先浅拷贝。</li><li>追问：怎么求&quot;空闲时间&quot;？答：把所有忙碌区间合并后，在相邻两段之间取空隙；注意处理一天/一周的边界（首段之前与末段之后也算空闲）。</li><li>陷阱：合并时只更新 <code>last.end = cur.end</code> 而不取 <code>max</code>，遇到被包含的区间结果就会变短；把 <code>&#39;09:00&#39;</code> 当通用可比较的时间戳做跨天运算。</li></ul><h3 id="q25-前端真实业务算法-url-参数解析与序列化、模板字符串变量替换怎么做" tabindex="-1"><a class="header-anchor" href="#q25-前端真实业务算法-url-参数解析与序列化、模板字符串变量替换怎么做" aria-hidden="true">#</a> Q25 前端真实业务算法：URL 参数解析与序列化、模板字符串变量替换怎么做？</h3><p><strong>考察点</strong>：考 URL 编解码、边界字符处理，以及模板替换的安全性；能说清&quot;为什么不该手写正则解析完整 URL&quot;才算过关。</p><p><strong>参考答案</strong>：</p><blockquote><p><strong>一句话结论</strong>：解析用 <code>new URLSearchParams</code>（或 <code>URL</code> 对象取 <code>searchParams</code>），它能正确处理编码、重复键与特殊字符；序列化用 <code>params.toString()</code>，手写拼接必须过一遍 <code>encodeURIComponent</code>；模板替换用 <code>/\\{\\{\\s*(\\w+)\\s*\\}\\}/g</code> 配 <code>replace</code> 回调，绝不用 <code>eval</code>。</p></blockquote><ol><li><code>URLSearchParams</code> 的优势：自动解码 <code>%20</code>/<code>+</code>、支持 <code>append</code> 保留重复键、<code>getAll</code> 拿到同名参数的数组；手写 <code>split(&#39;&amp;&#39;)</code> + <code>split(&#39;=&#39;)</code> 在值里含未编码的 <code>=</code> 或 <code>&amp;</code> 时会切错。</li><li>重复键的处理差异：<code>get(&#39;a&#39;)</code> 只返回<strong>第一个</strong>，<code>getAll(&#39;a&#39;)</code> 返回全部；所以 <code>a=1&amp;a=2</code> 这种多选框参数必须用 <code>getAll</code>，这是最常见的漏判。</li><li>构造查询串：<code>new URLSearchParams({ a: 1, b: &#39;中 文&#39; }).toString()</code> 会自动编码为 <code>a=1&amp;b=%E4%B8%AD+%E6%96%87</code>（空格在表单编码里是 <code>+</code>）；数组参数要循环 <code>append</code>。</li><li>取完整信息要用 <code>URL</code> 对象：<code>new URL(location.href)</code> 能拿到 <code>protocol</code>/<code>host</code>/<code>pathname</code>/<code>hash</code>；注意 <code>hash</code> 里的参数（<code>#/path?id=1</code>）不会进 <code>searchParams</code>，单页应用要手动从 <code>hash</code> 里再解析一次。</li><li>模板替换：<code>tpl.replace(/\\{\\{\\s*(\\w+)\\s*\\}\\}/g, (_, k) =&gt; data[k] ?? &#39;&#39;)</code>。必须用<strong>回调函数</strong>形式——若第二个参数传字符串，变量值里的 <code>$&amp;</code>、<code>$1</code> 会被当成替换模式产生意外输出。绝不能用 <code>new Function</code>/<code>eval</code>，模板内容一旦来自用户输入就是远程代码执行（RCE）漏洞。</li><li><strong>复杂度与边界</strong>：解析与序列化都是 O(参数字符数)、空间 O(k)（k 为参数个数）。边界：手写解析要 <code>try/catch</code> 包住 <code>decodeURIComponent</code>（用户手改地址栏出现单独的 <code>%</code> 会抛 <code>URIError</code>）；空值参数 <code>?a=</code> 要保留为空字符串而非 <code>undefined</code>；<code>encodeURI</code> 不编码 <code>:/?#[]@</code> 适合整条 URL，<code>encodeURIComponent</code> 会编码它们、适合单个参数值。</li></ol><div class="language-javascript line-numbers-mode" data-ext="js"><pre class="language-javascript"><code><span class="token comment">// 解析：支持重复键（a=1&amp;a=2 返回数组）</span>
<span class="token keyword">function</span> <span class="token function">parseQuery</span><span class="token punctuation">(</span><span class="token parameter">url</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
  <span class="token keyword">const</span> params <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token class-name">URL</span><span class="token punctuation">(</span>url<span class="token punctuation">,</span> location<span class="token punctuation">.</span>origin<span class="token punctuation">)</span><span class="token punctuation">.</span>searchParams<span class="token punctuation">;</span>
  <span class="token keyword">const</span> res <span class="token operator">=</span> <span class="token punctuation">{</span><span class="token punctuation">}</span><span class="token punctuation">;</span>
  <span class="token keyword">for</span> <span class="token punctuation">(</span><span class="token keyword">const</span> key <span class="token keyword">of</span> <span class="token keyword">new</span> <span class="token class-name">Set</span><span class="token punctuation">(</span>params<span class="token punctuation">.</span><span class="token function">keys</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>   <span class="token comment">// 去重键名</span>
    <span class="token keyword">const</span> all <span class="token operator">=</span> params<span class="token punctuation">.</span><span class="token function">getAll</span><span class="token punctuation">(</span>key<span class="token punctuation">)</span><span class="token punctuation">;</span>
    res<span class="token punctuation">[</span>key<span class="token punctuation">]</span> <span class="token operator">=</span> all<span class="token punctuation">.</span>length <span class="token operator">&gt;</span> <span class="token number">1</span> <span class="token operator">?</span> all <span class="token operator">:</span> all<span class="token punctuation">[</span><span class="token number">0</span><span class="token punctuation">]</span><span class="token punctuation">;</span>
  <span class="token punctuation">}</span>
  <span class="token keyword">return</span> res<span class="token punctuation">;</span>
<span class="token punctuation">}</span>
<span class="token comment">// 序列化：自动编码，跳过空值，数组展开为重复键</span>
<span class="token keyword">function</span> <span class="token function">stringifyQuery</span><span class="token punctuation">(</span><span class="token parameter">obj</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
  <span class="token keyword">const</span> params <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token class-name">URLSearchParams</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
  <span class="token keyword">for</span> <span class="token punctuation">(</span><span class="token keyword">const</span> <span class="token punctuation">[</span>k<span class="token punctuation">,</span> v<span class="token punctuation">]</span> <span class="token keyword">of</span> Object<span class="token punctuation">.</span><span class="token function">entries</span><span class="token punctuation">(</span>obj<span class="token punctuation">)</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token keyword">if</span> <span class="token punctuation">(</span>v <span class="token operator">===</span> <span class="token keyword">undefined</span> <span class="token operator">||</span> v <span class="token operator">===</span> <span class="token keyword">null</span> <span class="token operator">||</span> v <span class="token operator">===</span> <span class="token string">&#39;&#39;</span><span class="token punctuation">)</span> <span class="token keyword">continue</span><span class="token punctuation">;</span>
    <span class="token keyword">if</span> <span class="token punctuation">(</span>Array<span class="token punctuation">.</span><span class="token function">isArray</span><span class="token punctuation">(</span>v<span class="token punctuation">)</span><span class="token punctuation">)</span> v<span class="token punctuation">.</span><span class="token function">forEach</span><span class="token punctuation">(</span><span class="token punctuation">(</span><span class="token parameter">item</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> params<span class="token punctuation">.</span><span class="token function">append</span><span class="token punctuation">(</span>k<span class="token punctuation">,</span> item<span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token keyword">else</span> params<span class="token punctuation">.</span><span class="token function">append</span><span class="token punctuation">(</span>k<span class="token punctuation">,</span> v<span class="token punctuation">)</span><span class="token punctuation">;</span>
  <span class="token punctuation">}</span>
  <span class="token keyword">return</span> params<span class="token punctuation">.</span><span class="token function">toString</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
<span class="token comment">// 模板变量替换：只替换已知键，未提供则保留原样（禁止 eval）</span>
<span class="token keyword">function</span> <span class="token function">render</span><span class="token punctuation">(</span><span class="token parameter">tpl<span class="token punctuation">,</span> data</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
  <span class="token keyword">return</span> tpl<span class="token punctuation">.</span><span class="token function">replace</span><span class="token punctuation">(</span><span class="token regex"><span class="token regex-delimiter">/</span><span class="token regex-source language-regex">\\{\\{\\s*(\\w+)\\s*\\}\\}</span><span class="token regex-delimiter">/</span><span class="token regex-flags">g</span></span><span class="token punctuation">,</span> <span class="token punctuation">(</span><span class="token parameter">raw<span class="token punctuation">,</span> k</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span>
    <span class="token class-name">Object</span><span class="token punctuation">.</span>prototype<span class="token punctuation">.</span><span class="token function">hasOwnProperty</span><span class="token punctuation">.</span><span class="token function">call</span><span class="token punctuation">(</span>data<span class="token punctuation">,</span> k<span class="token punctuation">)</span> <span class="token operator">?</span> <span class="token function">String</span><span class="token punctuation">(</span>data<span class="token punctuation">[</span>k<span class="token punctuation">]</span><span class="token punctuation">)</span> <span class="token operator">:</span> raw<span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
<span class="token comment">// render(&#39;你好 {{ name }}，共 {{n}} 条&#39;, { name: &#39;刘群&#39;, n: 3 })</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>追问与易错点</strong>：</p><ul><li>追问：<code>encodeURI</code> 和 <code>encodeURIComponent</code> 有什么区别？答：<code>encodeURI</code> 不编码 <code>:/?#[]@</code> 等 URL 结构字符，适合编码整条 URL；<code>encodeURIComponent</code> 会把它们也编码，适合编码单个参数值。拼参数时用错了会导致分隔符被转义。</li><li>追问：<code>location.search</code> 里 <code>+</code> 代表什么？答：在 <code>application/x-www-form-urlencoded</code> 语义下 <code>+</code> 代表空格；<code>URLSearchParams</code> 会把它解成空格，手写 <code>decodeURIComponent</code> 不会，两者结果不一致。</li><li>陷阱：用正则 <code>/[?&amp;]([^&amp;]+)=([^&amp;]*)/g</code> 解析完整 URL，遇到 <code>#hash</code> 里的 <code>?</code>、值里未编码的 <code>&amp;</code>、path 中的 <code>?</code> 都会解析错；用 <code>replace</code> 传字符串导致 <code>$&amp;</code> 被特殊处理。</li></ul><h3 id="q26-前端真实业务算法-大数相加、千分位格式化、驼峰下划线互转怎么做" tabindex="-1"><a class="header-anchor" href="#q26-前端真实业务算法-大数相加、千分位格式化、驼峰下划线互转怎么做" aria-hidden="true">#</a> Q26 前端真实业务算法：大数相加、千分位格式化、驼峰下划线互转怎么做？</h3><p><strong>考察点</strong>：考 JS 精度边界意识与字符串处理基本功；这三题体量小、出现频率高，是&quot;送分题&quot;也是&quot;送命题&quot;。</p><p><strong>参考答案</strong>：</p><blockquote><p><strong>一句话结论</strong>：超过 <code>Number.MAX_SAFE_INTEGER</code>（2⁵³-1）的整数必须用 <code>BigInt</code> 或字符串逐位相加；千分位可以用 <code>toLocaleString</code> 或 <code>Intl.NumberFormat</code>，但要注意保留小数位；驼峰与下划线互转核心是正则 + 回调替换。</p></blockquote><ol><li>大数相加（字符串版）：从末位开始逐位相加，带上进位 <code>carry</code>，结果前插到结果字符串；两个数长度不同时短的按 0 补齐。</li><li>大数相加的现实选择：现代浏览器直接用 <code>BigInt</code> 最省事——<code>BigInt(&#39;9007199254740993&#39;) + 1n</code>；但 <code>BigInt</code> 不能与 <code>Number</code> 混算，且 <code>JSON.stringify</code> 会直接抛 <code>TypeError</code>，序列化前要转字符串。手写逐位相加考的是算法功底，<code>BigInt</code> 考的是 API 熟悉度，两者都答上最好。</li><li>千分位格式化：<code>(1234567.891).toLocaleString(&#39;zh-CN&#39;, { minimumFractionDigits: 2 })</code> 最稳；手写正则 <code>n.toFixed(2).replace(/\\B(?=(\\d{3})+(?!\\d))/g, &#39;,&#39;)</code> 要注意该正则只作用于小数点前的部分。</li><li>反解析：去掉逗号再 <code>parseFloat</code>；还要处理货币符号时用 <code>Number(str.replace(/[^\\d.-]/g, &#39;&#39;))</code> 兜底。</li><li>驼峰与下划线互转：下划线转小驼峰 <code>str.replace(/_(\\w)/g, (_, c) =&gt; c.toUpperCase())</code>；驼峰转下划线用 <code>/([a-z\\d])([A-Z])/g</code> 配 <code>&#39;$1_$2&#39;</code> 再 <code>toLowerCase()</code>，它只在&quot;小写字母后紧跟大写字母&quot;处断词，所以 <code>getHTTPCode</code> 得到 <code>get_httpcode</code>；若改用 <code>/([A-Z])/g</code> 就会把连续的每个大写字母都断开，得到 <code>get_h_t_t_p_code</code>。</li><li><strong>复杂度与边界</strong>：三者都是 O(n) 时间、O(n) 空间。边界：<code>0.1 + 0.2 !== 0.3</code>（IEEE 754 二进制浮点无法精确表示），金额应转成整数分再算或使用 decimal.js；大数相加结果要去掉前导 0；负数与大数混算要先判符号。</li></ol><div class="language-javascript line-numbers-mode" data-ext="js"><pre class="language-javascript"><code><span class="token comment">// 大数相加：字符串逐位相加（不使用 BigInt）</span>
<span class="token keyword">function</span> <span class="token function">addStrings</span><span class="token punctuation">(</span><span class="token parameter">a<span class="token punctuation">,</span> b</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
  <span class="token keyword">let</span> i <span class="token operator">=</span> a<span class="token punctuation">.</span>length <span class="token operator">-</span> <span class="token number">1</span><span class="token punctuation">,</span> j <span class="token operator">=</span> b<span class="token punctuation">.</span>length <span class="token operator">-</span> <span class="token number">1</span><span class="token punctuation">,</span> carry <span class="token operator">=</span> <span class="token number">0</span><span class="token punctuation">,</span> res <span class="token operator">=</span> <span class="token string">&#39;&#39;</span><span class="token punctuation">;</span>
  <span class="token keyword">while</span> <span class="token punctuation">(</span>i <span class="token operator">&gt;=</span> <span class="token number">0</span> <span class="token operator">||</span> j <span class="token operator">&gt;=</span> <span class="token number">0</span> <span class="token operator">||</span> carry<span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token keyword">const</span> sum <span class="token operator">=</span> <span class="token punctuation">(</span><span class="token operator">+</span>a<span class="token punctuation">[</span>i<span class="token operator">--</span><span class="token punctuation">]</span> <span class="token operator">||</span> <span class="token number">0</span><span class="token punctuation">)</span> <span class="token operator">+</span> <span class="token punctuation">(</span><span class="token operator">+</span>b<span class="token punctuation">[</span>j<span class="token operator">--</span><span class="token punctuation">]</span> <span class="token operator">||</span> <span class="token number">0</span><span class="token punctuation">)</span> <span class="token operator">+</span> carry<span class="token punctuation">;</span> <span class="token comment">// 越界按 0 处理</span>
    res <span class="token operator">=</span> <span class="token punctuation">(</span>sum <span class="token operator">%</span> <span class="token number">10</span><span class="token punctuation">)</span> <span class="token operator">+</span> res<span class="token punctuation">;</span>      <span class="token comment">// 当前位前插</span>
    carry <span class="token operator">=</span> sum <span class="token operator">&gt;=</span> <span class="token number">10</span> <span class="token operator">?</span> <span class="token number">1</span> <span class="token operator">:</span> <span class="token number">0</span><span class="token punctuation">;</span>   <span class="token comment">// 进位</span>
  <span class="token punctuation">}</span>
  <span class="token keyword">return</span> res<span class="token punctuation">.</span><span class="token function">replace</span><span class="token punctuation">(</span><span class="token regex"><span class="token regex-delimiter">/</span><span class="token regex-source language-regex">^0+(?=\\d)</span><span class="token regex-delimiter">/</span></span><span class="token punctuation">,</span> <span class="token string">&#39;&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token comment">// 去掉前导 0</span>
<span class="token punctuation">}</span>
<span class="token comment">// 千分位格式化（保留两位小数）</span>
<span class="token keyword">const</span> <span class="token function-variable function">thousands</span> <span class="token operator">=</span> <span class="token punctuation">(</span><span class="token parameter">n</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> n<span class="token punctuation">.</span><span class="token function">toFixed</span><span class="token punctuation">(</span><span class="token number">2</span><span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">replace</span><span class="token punctuation">(</span><span class="token regex"><span class="token regex-delimiter">/</span><span class="token regex-source language-regex">\\B(?=(\\d{3})+(?!\\d))</span><span class="token regex-delimiter">/</span><span class="token regex-flags">g</span></span><span class="token punctuation">,</span> <span class="token string">&#39;,&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token comment">// 下划线 &lt;-&gt; 小驼峰</span>
<span class="token keyword">const</span> <span class="token function-variable function">toCamel</span> <span class="token operator">=</span> <span class="token punctuation">(</span><span class="token parameter">s</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> s<span class="token punctuation">.</span><span class="token function">replace</span><span class="token punctuation">(</span><span class="token regex"><span class="token regex-delimiter">/</span><span class="token regex-source language-regex">_(\\w)</span><span class="token regex-delimiter">/</span><span class="token regex-flags">g</span></span><span class="token punctuation">,</span> <span class="token punctuation">(</span><span class="token parameter">_<span class="token punctuation">,</span> c</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> c<span class="token punctuation">.</span><span class="token function">toUpperCase</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token keyword">const</span> <span class="token function-variable function">toSnake</span> <span class="token operator">=</span> <span class="token punctuation">(</span><span class="token parameter">s</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> s<span class="token punctuation">.</span><span class="token function">replace</span><span class="token punctuation">(</span><span class="token regex"><span class="token regex-delimiter">/</span><span class="token regex-source language-regex">([a-z\\d])([A-Z])</span><span class="token regex-delimiter">/</span><span class="token regex-flags">g</span></span><span class="token punctuation">,</span> <span class="token string">&#39;$1_$2&#39;</span><span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">toLowerCase</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>追问与易错点</strong>：</p><ul><li>追问：为什么 <code>0.1 + 0.2 !== 0.3</code>？答：IEEE 754 双精度浮点用二进制表示小数，0.1 与 0.2 都是无限循环小数只能近似存储，相加后误差累积。金额计算应转成整数分再算，或使用 decimal.js 之类的库。</li><li>追问：<code>BigInt</code> 有什么使用限制？答：不能与 <code>Number</code> 混合运算（抛 <code>TypeError</code>）、<code>Math</code> 系列方法不支持、<code>JSON.stringify</code> 会抛错；要序列化得自定义 <code>toJSON</code> 或转成字符串。</li><li>陷阱：千分位正则写成 <code>/\\d{3}/g</code> 会把 <code>1234</code> 变成 <code>,1,234</code>；驼峰转下划线用 <code>/([A-Z])/g</code> 处理 <code>getHTTPCode</code> 得到 <code>get_h_t_t_p_code</code>，与后端约定不符。</li></ul><h3 id="q27-前端真实业务算法-虚拟列表的可见区间怎么算" tabindex="-1"><a class="header-anchor" href="#q27-前端真实业务算法-虚拟列表的可见区间怎么算" aria-hidden="true">#</a> Q27 前端真实业务算法：虚拟列表的可见区间怎么算？</h3><p><strong>考察点</strong>：考&quot;固定行高虚拟滚动&quot;的核心公式与缓冲区设计，是长列表性能优化的必考题，也是本类题里唯一的困难题。</p><p><strong>参考答案</strong>：</p><blockquote><p><strong>一句话结论</strong>：固定行高时，<code>start = Math.floor(scrollTop / itemHeight)</code>、<code>visibleCount = Math.ceil(containerHeight / itemHeight)</code>，渲染区间取 <code>[start - buffer, start + visibleCount + buffer]</code>，并用 <code>transform: translateY(startIndex * itemHeight)</code> 撑出正确位置。</p></blockquote><ol><li>三要素：容器高度 <code>containerHeight</code>、行高 <code>itemHeight</code>、滚动距离 <code>scrollTop</code>。可见起始下标就是&quot;滚过了几行&quot;，可见数量就是&quot;容器能装几行&quot;。</li><li>为什么必须加缓冲区（Buffer）：快速滚动时浏览器来不及渲染，会出现白屏闪烁；上下各多渲染 2-5 行能让新内容在进入视口前就绪。缓冲区大小是&quot;滚动流畅度 vs 渲染开销&quot;的取舍参数。</li><li>撑高与定位：外层容器高度设为 <code>total * itemHeight</code>（或用 <code>padding-top</code> / 内层占位 div），可视区用 <code>position: absolute; transform: translateY(offsetY)</code> 偏移。用 <code>transform</code> 而不是 <code>top</code>，因为前者只触发合成层、不引起重排。</li><li>总高度必须正确：整表高度决定滚动条长度，算错会导致&quot;滚到底部还有空白&quot;或&quot;最后几条滚不到&quot;。</li><li><strong>复杂度与边界</strong>：每次滚动计算是 O(1)，渲染的 DOM 数是 O(visibleCount + 2·buffer) 而不是 O(n)。边界：<code>scrollTop</code> 为 0 时 <code>startIndex</code> 必须钳到 0；滚到底部时 <code>endIndex</code> 要 <code>Math.min(total - 1, ...)</code> 防止越界取到 <code>undefined</code>；缓冲区不能设得过大（如 50），否则虚拟列表反而比直出更慢。</li><li>不定行高的处理：无法用除法直接定位，常见方案是&quot;预估行高 + 动态测量并缓存&quot;（渲染后用 <code>ResizeObserver</code> 测量真实高度写回缓存，滚动时用前缀和或二分查找定位区间），定位变成 O(log n)，实现难度显著上升，也是面试官区分深度的地方。</li></ol><div class="language-javascript line-numbers-mode" data-ext="js"><pre class="language-javascript"><code><span class="token comment">// 固定行高虚拟列表：计算可见区间</span>
<span class="token keyword">function</span> <span class="token function">getRange</span><span class="token punctuation">(</span><span class="token parameter"><span class="token punctuation">{</span> scrollTop<span class="token punctuation">,</span> containerHeight<span class="token punctuation">,</span> itemHeight<span class="token punctuation">,</span> total<span class="token punctuation">,</span> buffer <span class="token operator">=</span> <span class="token number">3</span> <span class="token punctuation">}</span></span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
  <span class="token keyword">const</span> start <span class="token operator">=</span> Math<span class="token punctuation">.</span><span class="token function">floor</span><span class="token punctuation">(</span>scrollTop <span class="token operator">/</span> itemHeight<span class="token punctuation">)</span><span class="token punctuation">;</span>              <span class="token comment">// 首个可见行</span>
  <span class="token keyword">const</span> visibleCount <span class="token operator">=</span> Math<span class="token punctuation">.</span><span class="token function">ceil</span><span class="token punctuation">(</span>containerHeight <span class="token operator">/</span> itemHeight<span class="token punctuation">)</span><span class="token punctuation">;</span>  <span class="token comment">// 可见行数</span>
  <span class="token keyword">const</span> startIndex <span class="token operator">=</span> Math<span class="token punctuation">.</span><span class="token function">max</span><span class="token punctuation">(</span><span class="token number">0</span><span class="token punctuation">,</span> start <span class="token operator">-</span> buffer<span class="token punctuation">)</span><span class="token punctuation">;</span>                <span class="token comment">// 上缓冲</span>
  <span class="token keyword">const</span> endIndex <span class="token operator">=</span> Math<span class="token punctuation">.</span><span class="token function">min</span><span class="token punctuation">(</span>total <span class="token operator">-</span> <span class="token number">1</span><span class="token punctuation">,</span> start <span class="token operator">+</span> visibleCount <span class="token operator">+</span> buffer<span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token comment">// 下缓冲</span>
  <span class="token keyword">return</span> <span class="token punctuation">{</span>
    startIndex<span class="token punctuation">,</span>
    endIndex<span class="token punctuation">,</span>
    <span class="token literal-property property">offsetY</span><span class="token operator">:</span> startIndex <span class="token operator">*</span> itemHeight<span class="token punctuation">,</span>                            <span class="token comment">// 偏移量</span>
    <span class="token literal-property property">totalHeight</span><span class="token operator">:</span> total <span class="token operator">*</span> itemHeight<span class="token punctuation">,</span>                             <span class="token comment">// 撑高总高度</span>
  <span class="token punctuation">}</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
<span class="token comment">// items.slice(startIndex, endIndex + 1) 只渲染这一段</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>追问与易错点</strong>：</p><ul><li>追问：滚动事件里直接 <code>setState</code> 有什么问题？答：高频滚动会触发大量重渲染导致掉帧；应该用 <code>requestAnimationFrame</code> 节流、用 <code>passive: true</code> 监听，或只在计算出的 <code>startIndex</code> 真正变化时才更新。</li><li>追问：行高不固定怎么办？答：先用预估值渲染，再用 <code>ResizeObserver</code> 或渲染后测量真实高度更新缓存；定位时用缓存的前缀和数组 + 二分查找找出起始下标。代价是定位变成 O(log n) 且实现复杂。</li><li>陷阱：忘记 <code>Math.min</code>/<code>Math.max</code> 边界钳制，滚到顶部或底部时下标越界取到 <code>undefined</code>；用 <code>top</code> 定位而非 <code>transform</code>，滚动时不断触发重排而掉帧。</li></ul><h3 id="q28-前端真实业务算法-正则校验、随机抽样与洗牌有哪些必须知道的坑" tabindex="-1"><a class="header-anchor" href="#q28-前端真实业务算法-正则校验、随机抽样与洗牌有哪些必须知道的坑" aria-hidden="true">#</a> Q28 前端真实业务算法：正则校验、随机抽样与洗牌有哪些必须知道的坑？</h3><p><strong>考察点</strong>：考&quot;看起来对但实际错&quot;的经典陷阱——正则不加锚点、洗牌用 <code>sort(random)</code>；这两题最容易暴露基础是否扎实。</p><p><strong>参考答案</strong>：</p><blockquote><p><strong>一句话结论</strong>：正则校验必须加 <code>^</code> 与 <code>$</code> 锚点，并理解&quot;正则只保证格式不保证真实性&quot;；洗牌必须用 Fisher-Yates（<code>sort(() =&gt; Math.random() - 0.5)</code> 分布不均匀）；抽样的进阶版是蓄水池抽样。</p></blockquote><ol><li>邮箱校验：<code>/^[\\w.+-]+@[\\w-]+(\\.[\\w-]+)+$/</code> 只做基本格式校验，不能判断邮箱真实存在，也不该追求&quot;完全符合 RFC 5322&quot;（那条正则几百字符，维护成本极高）。业务上还要配合验证码/邮件确认。</li><li>手机号校验：中国大陆用 <code>/^1[3-9]\\d{9}$/</code>。<strong>锚点不能省</strong>——不加 <code>^$</code> 时 <code>&quot;abc13812345678xyz&quot;</code> 也会返回 <code>true</code>，这是最经典的误判。</li><li>Fisher-Yates 洗牌：从后往前遍历，每次把当前元素与 <code>[0, i]</code> 中的随机下标交换。时间 O(n)、原地交换，能保证 n! 种排列等概率。</li><li>为什么 <code>arr.sort(() =&gt; Math.random() - 0.5)</code> 是错的：比较器不满足传递性，各元素被比较的次数不均等，导致某些排列概率明显偏高（n 小时偏差肉眼可见），而且不同引擎结果不同。这是最常被考&quot;你到底懂不懂&quot;的一题。</li><li>随机抽样：从数组中不重复取 k 个，可用&quot;洗牌后取前 k 个&quot;，或&quot;蓄水池抽样（Reservoir Sampling）&quot;——后者能在<strong>不知道总数</strong>的数据流上等概率抽样，是处理大文件/日志流的正解。</li><li><strong>复杂度与边界</strong>：Fisher-Yates 与蓄水池抽样都是 O(n) 时间；洗牌要拷贝数组以免改原数组，蓄水池抽样空间 O(k)。边界：<code>Math.random()</code> 不会返回 1，所以 <code>Math.floor(Math.random() * n)</code> 能正确覆盖 <code>[0, n-1]</code>；它是伪随机且不可用于加密场景（令牌、抽奖种子），涉及安全要用 <code>crypto.getRandomValues()</code>。</li></ol><div class="language-javascript line-numbers-mode" data-ext="js"><pre class="language-javascript"><code><span class="token comment">// Fisher-Yates 洗牌：等概率 O(n)，不改原数组</span>
<span class="token keyword">function</span> <span class="token function">shuffle</span><span class="token punctuation">(</span><span class="token parameter">arr</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
  <span class="token keyword">const</span> a <span class="token operator">=</span> arr<span class="token punctuation">.</span><span class="token function">slice</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
  <span class="token keyword">for</span> <span class="token punctuation">(</span><span class="token keyword">let</span> i <span class="token operator">=</span> a<span class="token punctuation">.</span>length <span class="token operator">-</span> <span class="token number">1</span><span class="token punctuation">;</span> i <span class="token operator">&gt;</span> <span class="token number">0</span><span class="token punctuation">;</span> i<span class="token operator">--</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token keyword">const</span> j <span class="token operator">=</span> Math<span class="token punctuation">.</span><span class="token function">floor</span><span class="token punctuation">(</span>Math<span class="token punctuation">.</span><span class="token function">random</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">*</span> <span class="token punctuation">(</span>i <span class="token operator">+</span> <span class="token number">1</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token comment">// [0, i] 均匀取一个</span>
    <span class="token punctuation">[</span>a<span class="token punctuation">[</span>i<span class="token punctuation">]</span><span class="token punctuation">,</span> a<span class="token punctuation">[</span>j<span class="token punctuation">]</span><span class="token punctuation">]</span> <span class="token operator">=</span> <span class="token punctuation">[</span>a<span class="token punctuation">[</span>j<span class="token punctuation">]</span><span class="token punctuation">,</span> a<span class="token punctuation">[</span>i<span class="token punctuation">]</span><span class="token punctuation">]</span><span class="token punctuation">;</span>                   <span class="token comment">// 交换到末尾已定区</span>
  <span class="token punctuation">}</span>
  <span class="token keyword">return</span> a<span class="token punctuation">;</span>
<span class="token punctuation">}</span>
<span class="token comment">// 蓄水池抽样：从数据流中随机取 k 个（不知道总数也能等概率）</span>
<span class="token keyword">function</span> <span class="token function">reservoir</span><span class="token punctuation">(</span><span class="token parameter">stream<span class="token punctuation">,</span> k</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
  <span class="token keyword">const</span> res <span class="token operator">=</span> stream<span class="token punctuation">.</span><span class="token function">slice</span><span class="token punctuation">(</span><span class="token number">0</span><span class="token punctuation">,</span> k<span class="token punctuation">)</span><span class="token punctuation">;</span>
  <span class="token keyword">for</span> <span class="token punctuation">(</span><span class="token keyword">let</span> i <span class="token operator">=</span> k<span class="token punctuation">;</span> i <span class="token operator">&lt;</span> stream<span class="token punctuation">.</span>length<span class="token punctuation">;</span> i<span class="token operator">++</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token keyword">const</span> j <span class="token operator">=</span> Math<span class="token punctuation">.</span><span class="token function">floor</span><span class="token punctuation">(</span>Math<span class="token punctuation">.</span><span class="token function">random</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">*</span> <span class="token punctuation">(</span>i <span class="token operator">+</span> <span class="token number">1</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token keyword">if</span> <span class="token punctuation">(</span>j <span class="token operator">&lt;</span> k<span class="token punctuation">)</span> res<span class="token punctuation">[</span>j<span class="token punctuation">]</span> <span class="token operator">=</span> stream<span class="token punctuation">[</span>i<span class="token punctuation">]</span><span class="token punctuation">;</span>                 <span class="token comment">// 以 k/(i+1) 的概率替换</span>
  <span class="token punctuation">}</span>
  <span class="token keyword">return</span> res<span class="token punctuation">;</span>
<span class="token punctuation">}</span>
<span class="token keyword">const</span> <span class="token function-variable function">isEmail</span> <span class="token operator">=</span> <span class="token punctuation">(</span><span class="token parameter">s</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token regex"><span class="token regex-delimiter">/</span><span class="token regex-source language-regex">^[\\w.+-]+@[\\w-]+(\\.[\\w-]+)+$</span><span class="token regex-delimiter">/</span></span><span class="token punctuation">.</span><span class="token function">test</span><span class="token punctuation">(</span>s<span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token keyword">const</span> <span class="token function-variable function">isPhoneCN</span> <span class="token operator">=</span> <span class="token punctuation">(</span><span class="token parameter">s</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token regex"><span class="token regex-delimiter">/</span><span class="token regex-source language-regex">^1[3-9]\\d{9}$</span><span class="token regex-delimiter">/</span></span><span class="token punctuation">.</span><span class="token function">test</span><span class="token punctuation">(</span>s<span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>追问与易错点</strong>：</p><ul><li>追问：为什么随机比较器会破坏排序？答：<code>sort</code> 依赖比较结果的一致性（若 a&lt;b、b&lt;c 则 a&lt;c）来决定交换，随机返回值让这个前提失效，实际等价于一次有偏的乱序；V8 对短数组走插入排序，会有明显的&quot;靠前元素更不容易被移动&quot;的偏差。</li><li>追问：洗牌和随机抽样是一回事吗？答：不是。洗牌要打乱全部元素（输出长度 n），抽样只要均匀取出 k 个（输出长度 k，且通常比洗牌更省内存，蓄水池抽样可处理无穷流）。</li><li>陷阱：正则忘记加锚点导致&quot;包含即通过&quot;；用 <code>sort(() =&gt; Math.random() - 0.5)</code> 洗牌；用 <code>Math.random()</code> 生成 token。</li></ul><h2 id="本章小结" tabindex="-1"><a class="header-anchor" href="#本章小结" aria-hidden="true">#</a> 本章小结</h2><ul><li>复杂度看增长趋势不看常数：抓最深层的执行次数、取最高阶、扔低阶项；均摊复杂度（如 <code>push</code> 扩容、双栈队列）是对操作序列总代价摊派，不等于按概率求期望的平均复杂度。</li><li>排序核心是那张对比表：快排平均最快但最坏 O(n²) 且不稳定，归并稳定且适合链表但要 O(n) 空间，堆排原地且最坏可控；ES2019 起 <code>sort</code> 稳定，所以&quot;多次稳定排序&quot;是实现多字段排序的正规手段。</li><li>链表题的通用武器是哑节点 + 快慢指针：反转、判环、找中点、合并有序链表都基于同一套指针操作，&quot;先存后继再反转&quot;是不断链的唯一纪律。</li><li>栈与队列的关键是语义匹配：括号匹配与单调栈用&quot;最近相关性&quot;，最小栈用辅助栈记录历史最小值，双栈队列靠&quot;只倒腾一次&quot;拿到均摊 O(1)。</li><li>二分查找的唯一诀窍是全程锁定区间语义：定死 <code>[left, right]</code> 还是 <code>[left, right)</code>，收缩时左边界跳一格、右边界跳一格就不会死循环；只要具备单调性（旋转数组的局部有序、峰值题的爬坡方向）就能二分。</li><li>滑动窗口与双指针能降复杂度，靠的都是&quot;一次移动排除一整批候选项&quot;的单调性剪枝；无重复最长子串、三数之和、盛水容器是同一思想的三种外壳。</li><li>回溯的固定模板是&quot;做选择 → 递归 → 撤销选择&quot;，排列用 <code>used</code> 标记、组合与子集用 <code>start</code> 下标，收集结果必须拷贝 <code>[...path]</code>；递归转迭代用显式栈。</li><li>树题只有两个骨架：按层处理用 BFS（先记 <code>size</code> 切分层，用头指针代替 <code>shift</code>），子树信息汇总用 DFS 后序上收（最大深度、LCA 都是这个模式）；BST 校验必须用上下界区间或中序严格递增。</li><li>动态规划三步走：定义状态、写转移方程、定初始条件；推导路径是&quot;暴力递归 → 加备忘录 → 改迭代&quot;，0-1 背包一维压缩必须倒序遍历容量；贪心必须能证明，证不出就换 DP（零钱兑换是经典反例）。</li><li>前端业务算法的高频套路集中在四类：哈希聚合（分组、diff、树扁平互转）、区间与时间处理（合并、冲突检测、相对时间）、字符串解析（URL、模板、版本号、命名转换）、渲染计算（虚拟列表可见区间）；共同优化点是&quot;把 O(n²) 的嵌套查找换成 O(1) 的 <code>Map</code>/<code>Set</code>&quot;。</li><li>精度与随机是高危区：超过 2⁵³-1 用 <code>BigInt</code> 或字符串逐位算，金额转整数分；洗牌必须用 Fisher-Yates 而不是 <code>sort(() =&gt; Math.random() - 0.5)</code>，安全场景用 <code>crypto.getRandomValues()</code> 而不是 <code>Math.random()</code>。</li></ul>`,227);function c(l,u){return s(),a("div",null,[e,t(" COUNT: 28 ")])}const k=n(o,[["render",c],["__file","24-algorithm.html.vue"]]);export{k as default};
